package com.timemeasurer.app.core.data.model

import com.timemeasurer.app.core.model.timer.TimerProgressType
import com.timemeasurer.app.core.model.timer.TimerSettingsModel
import com.timemeasurer.app.core.model.timer.TimerTimeType
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject

fun TimerSettingsModel.toEncodeString(): String = Json.encodeToString(TimerSettingsModel.serializer(), this)

fun String.toTimerSettingsModel(): TimerSettingsModel {
    val json = Json.decodeFromString<JsonObject>(this)
    val base = Json.decodeFromJsonElement(TimerSettingsModel.serializer(), json)

    return base.copy(
        sessionDurationUnit = json["sessionDurationUnit"]?.let { Json.decodeFromJsonElement(TimerTimeType.serializer(), it) } ?: TimerTimeType.MINUTES,
        shortBreakDurationUnit = json["shortBreakDurationUnit"]?.let { Json.decodeFromJsonElement(TimerTimeType.serializer(), it) } ?: TimerTimeType.MINUTES,
        longBreakDurationUnit = json["longBreakDurationUnit"]?.let { Json.decodeFromJsonElement(TimerTimeType.serializer(), it) } ?: TimerTimeType.MINUTES,
        progressType = json["progressType"]?.let { Json.decodeFromJsonElement(TimerProgressType.serializer(), it) } ?: TimerProgressType.Circular,
    )
}