package com.timemeasurer.app.feature.stopwatches.models

import com.timemeasurer.app.core.domain.common.ValidateNameUseCase
import com.timemeasurer.app.core.model.icon.DefaultIconIds
import org.jetbrains.compose.resources.StringResource

sealed interface StopwatchActions {
    data object None : StopwatchActions
    data class ShowError(val error: StringResource) : StopwatchActions

    data class ShowCreateStopwatchDialog(
        val isDialogVisible: Boolean = false,
        val stopwatchId: Long = 1L,
        val iconId: String = DefaultIconIds.STOPWATCH,
        val nameError: StringResource? = null,
        val maxNameLength: Int = ValidateNameUseCase.MAX_LENGTH,
    ) : StopwatchActions

    data class ShowRenameStopwatchDialog(
        val isDialogVisible: Boolean = false,
        val stopwatchId: Long = 0L,
        val currentName: String = "",
        val iconId: String = "",
        val nameError: StringResource? = null,
        val maxNameLength: Int = ValidateNameUseCase.MAX_LENGTH,
    ) : StopwatchActions

    data class ShowDeleteStopwatchDialog(
        val isDialogVisible: Boolean = false,
        val stopwatchId: Long = 0L,
        val currentName: String = ""
    ) : StopwatchActions

    data object OpenStatistics : StopwatchActions

    data class ShowResetStopwatchDialog(
        val isDialogVisible: Boolean = false,
        val stopwatchId: Long = 0L
    ) : StopwatchActions
}
