package com.timemeasurer.app.core.domain.timer

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.data.repositories.timers.TimersRepository
import com.timemeasurer.app.core.model.timer.TimerModel
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.withContext
import kotlin.time.ExperimentalTime

@OptIn(ExperimentalTime::class)
class UpdateTimerUseCase(
    private val timersRepository: TimersRepository,
    private val ioScope: CoroutineScope,
    private val ioDispatcher: CoroutineDispatcher,
) {
    suspend operator fun invoke(item: TimerModel): Result<Long> = withContext(ioDispatcher) {
        timersRepository.updateTimer(item)
    }

    suspend operator fun invoke(timerId: Long, newName: String, iconId: String): Result<Long> = withContext(ioDispatcher) {
        timersRepository.renameTimer(timerId, newName, iconId)
    }
}
