package com.timemeasurer.app.core.domain.ext

import kotlinx.datetime.TimeZone
import kotlinx.datetime.toLocalDateTime
import kotlin.time.ExperimentalTime
import kotlin.time.Instant

@ExperimentalTime
val Instant.toFormatterDateTime: String?
    get() = kotlin.runCatching {
        val dateTime = toLocalDateTime(TimeZone.UTC)
        "${dateTime.date.day} ${dateTime.date.month.toString().lowercase()} ${dateTime.date.year} " +
            "${dateTime.time.hour}:${dateTime.time.minute}:${dateTime.time.second}"
    }.getOrNull()


fun Long.toHoursMinutes(): String {
    val hours = this / 3600
    val minutes = (this % 3600) / 60
    return "${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}"
}

fun Long.toHoursMinutesSecondsMillis(): String {
    val hours = this / 3_600_000
    val minutes = (this % 3_600_000) / 60_000
    val seconds = (this % 60_000) / 1_000
    val millis = this % 1_000
    val h = hours.toString().padStart(2, '0')
    val m = minutes.toString().padStart(2, '0')
    val s = seconds.toString().padStart(2, '0')
    val ms = millis.toString().padStart(3, '0')
    return "$h:$m:$s.$ms"
}