package com.timemeasurer.app.core.model.converters

import kotlin.time.Instant

private const val DATE_TIME_TEMPLATE = "yyyy-MM-ddTHH:mm:ssZ"

@OptIn(kotlin.time.ExperimentalTime::class)
fun dateTimeConverter(dateTime: String): Instant {
    return Instant.parse(dateTime)
}

@OptIn(kotlin.time.ExperimentalTime::class)
fun dateTimeConverter(dateTime: Long): Instant {
    return Instant.fromEpochMilliseconds(dateTime)
}

@OptIn(kotlin.time.ExperimentalTime::class)
fun dateTimeConverter(dateTime: Instant): Long {
    return dateTime.toEpochMilliseconds()
}

