package com.timemeasurer.app.core.model.converters

import com.timemeasurer.app.core.model.timer.TimerTypeModel
import kotlin.time.ExperimentalTime

@OptIn(ExperimentalTime::class)
fun timerTypeConverter(type: String): TimerTypeModel {
    return TimerTypeModel.entries.find { it.name == type } ?: TimerTypeModel.Session
}

@OptIn(ExperimentalTime::class)
fun timerTypeConverter(type: TimerTypeModel): String {
    return type.name
}