package com.timemeasurer.app.core.domain.settings

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.data.repositories.settings.SettingsRepository
import com.timemeasurer.app.core.model.ActiveTimerSetting
import com.timemeasurer.app.core.model.SettingsModel
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.mapNotNull

class SingleActiveTimerSettingUseCase(
    private val settingsRepository: SettingsRepository,
) {
    operator fun invoke(): Flow<ActiveTimerSetting> = settingsRepository.getSettings()
        .mapNotNull { result ->
            when (result) {
                is Result.Success -> {
                    val model = result.data ?: SettingsModel()
                    ActiveTimerSetting(
                        isEnabled = model.isSingleActiveTimer,
                        activeTimerId = model.singleActiveTimerId,
                    )
                }
                is Result.Error -> ActiveTimerSetting(
                    isEnabled = SettingsModel().isSingleActiveTimer,
                    activeTimerId = SettingsModel().singleActiveTimerId,
                )
                is Result.Loading -> null
            }
        }

    suspend fun setEnabled(enabled: Boolean) {
        val current = settingsRepository.getSettings()
            .first { it is Result.Success }
            .let { (it as Result.Success).data ?: SettingsModel() }
        settingsRepository.setSettings(
            current.copy(
                isSingleActiveTimer = enabled,
                singleActiveTimerId = if (enabled) current.singleActiveTimerId else null,
            )
        )
    }

    suspend fun setActiveTimerId(timerId: Long?) {
        val current = settingsRepository.getSettings()
            .first { it is Result.Success }
            .let { (it as Result.Success).data ?: SettingsModel() }
        settingsRepository.setSettings(current.copy(singleActiveTimerId = timerId))
    }
}
