package com.timemeasurer.app.core.data.repositories.timers

import app.cash.sqldelight.async.coroutines.awaitAsList
import app.cash.sqldelight.async.coroutines.awaitAsOneOrNull
import app.cash.sqldelight.coroutines.asFlow
import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.common.result.startLoading
import com.timemeasurer.app.core.data.database.AppDatabase
import com.timemeasurer.app.core.data.model.entitiesToTimersModels
import com.timemeasurer.app.core.data.model.toEncodeString
import com.timemeasurer.app.core.data.model.toTimerModel
import com.timemeasurer.app.core.data.model.toTimersEntity
import com.timemeasurer.app.core.model.timer.TimerModel
import com.timemeasurer.app.core.model.timer.TimerSettingsModel
import com.timemeasurer.app.core.remote_services.CrashlyticsService
import com.timemeasurer.app.core.remote_services.NoOpCrashlyticsService
import data.TimersEntity
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.filterNot
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.onStart

@OptIn(kotlin.time.ExperimentalTime::class)
internal class TimersRepositoryImpl(
    private val database: AppDatabase,
    private val scope: CoroutineScope,
    private val crashlytics: CrashlyticsService = NoOpCrashlyticsService()
) : TimersRepository {

    override suspend fun getTimers(): Flow<Result<List<TimerModel>>> {
        val dbFlow = database.db().timersQueries.selectAll()
            .asFlow()
            .map { it.awaitAsList() }
            .map<List<TimersEntity>, Result<List<TimerModel>>> {
                Result.Success(it.entitiesToTimersModels())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("TimersRepositoryImpl() - getTimers()")
                crashlytics.recordException(it)
                println("TimersRepositoryImpl() - getTimers() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun getTimersById(sinceId: Long, count: Long): Flow<Result<List<TimerModel>>> {
        val dbFlow = database.db().timersQueries.selectSinceId(sinceId = sinceId, count = count)
            .asFlow()
            .map { it.awaitAsList() }
            .filterNot { it.isEmpty() }
            .map<List<TimersEntity>, Result<List<TimerModel>>> {
                Result.Success(it.entitiesToTimersModels())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("TimersRepositoryImpl() - getTimersById()")
                crashlytics.recordException(it)
                println("TimersRepositoryImpl() - getTimersById() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun getTimerById(id: Long): Flow<Result<TimerModel?>> {
        val dbFlow = database.db().timersQueries.selectTimerById(timerId = id)
            .asFlow()
            .map { it.awaitAsOneOrNull() }
            .map<TimersEntity?, Result<TimerModel?>> {
                Result.Success(it?.toTimerModel())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("TimersRepositoryImpl() - getTimerById()")
                crashlytics.recordException(it)
                println("TimersRepositoryImpl() - getTimerById() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun getTimersByName(name: String): Flow<Result<List<TimerModel>>> {
        val dbFlow = database.db().timersQueries.selectTimerByName(name = name)
            .asFlow()
            .map { it.awaitAsList() }
            .filterNot { it.isEmpty() }
            .map<List<TimersEntity>, Result<List<TimerModel>>> {
                Result.Success(it.entitiesToTimersModels())
            }
            .onStart { emit(Result.Loading) }
            .catch {
                crashlytics.log("TimersRepositoryImpl() - getTimersByName()")
                crashlytics.recordException(it)
                println("TimersRepositoryImpl() - getTimersByName() - error: $it")
                emit(Result.Error(it))
            }

        return dbFlow.startLoading()
            .distinctUntilChanged()
    }

    override suspend fun updateTimer(item: TimerModel): Result<Long> {
        val result = runCatching {
            database.db().timersQueries.insertOrUpdate(item.toTimersEntity())
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("TimerRepositoryImpl() - updateTimer()")
            crashlytics.recordException(it)
        }

        val rowsCount = result.getOrNull() ?: 0L
        println("TimerRepositoryImpl() - updateTimer(): ${rowsCount}, ${result.exceptionOrNull()}")
        return if (rowsCount > 0) Result.Success(rowsCount)
        else Result.Error(exception = result.exceptionOrNull(), error = "Rows updated is 0")
    }

    override suspend fun renameTimer(timerId: Long, newName: String, iconId: String): Result<Long> {
        val result = runCatching {
            val entity = database.db().timersQueries.selectTimerById(timerId).awaitAsOneOrNull()
                ?: throw IllegalStateException("Timer not found: $timerId")

            val model = entity.toTimerModel()
            val updated = model.copy(
                name = newName,
                settings = model.settings.copy(iconId = iconId)
            ).toTimersEntity()

            database.db().timersQueries.updateNameAndSettingsById(
                name = updated.name,
                settings = updated.settings,
                timerId = timerId
            )
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("TimerRepositoryImpl() - renameTimer()")
            crashlytics.recordException(it)
        }

        val rowsCount = result.getOrNull() ?: 0L
        println("TimerRepositoryImpl() - renameTimer(): ${rowsCount}, ${result.exceptionOrNull()}")
        return if (rowsCount > 0) Result.Success(rowsCount)
        else Result.Error(exception = result.exceptionOrNull(), error = "Rows updated is 0")
    }

    override suspend fun deleteTimer(timerId: Long): Result<Long> {
        val result = runCatching {
            database.db().timersQueries.deleteTimerById(timerId)
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("TimerRepositoryImpl() - deleteTimer()")
            crashlytics.recordException(it)
        }

        val rowsCount = result.getOrNull() ?: 0L
        println("TimerRepositoryImpl() - deleteTimer(): ${rowsCount}, ${result.exceptionOrNull()}")
        return if (rowsCount > 0) Result.Success(rowsCount)
        else Result.Error(exception = result.exceptionOrNull(), error = "Rows deleted is 0")
    }

    override suspend fun createTimer(name: String, settings: TimerSettingsModel): Result<TimerModel> {
        val result = runCatching {
            database.db().timersQueries.insertTimerAndReturn(
                name = name,
                settings = settings.toEncodeString()
            ).awaitAsOneOrNull()
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("TimerRepositoryImpl() - createNewTimer()")
            crashlytics.recordException(it)
        }

        val timer = result.getOrNull()
        println("TimerRepositoryImpl() - createNewTimer(): ${timer}, ${result.exceptionOrNull()}")
        return if (timer != null) Result.Success(timer.toTimerModel())
        else Result.Error(exception = result.exceptionOrNull(), error = "Create timer fail")
    }

    override suspend fun updateAllTimersSettings(settings: TimerSettingsModel): Result<Long> {
        val result = runCatching {
            database.db().timersQueries.updateAllTimersSettings(settings = settings.toEncodeString())
        }
        result.exceptionOrNull()?.let {
            crashlytics.log("TimerRepositoryImpl() - updateAllTimersSettings()")
            crashlytics.recordException(it)
        }

        val rowsCount = result.getOrNull() ?: 0L
        println("TimerRepositoryImpl() - updateAllTimersSettings(): ${rowsCount}, ${result.exceptionOrNull()}")
        return if (rowsCount > 0) Result.Success(rowsCount)
        else Result.Error(exception = result.exceptionOrNull(), error = "Update all timers settings fail")
    }


}