package com.timemeasurer.app.core.domain.sound

import com.timemeasurer.app.core.model.timer.TimerSettingsModel
import com.timemeasurer.app.core.model.timer.TimerTypeModel

class TimerSoundInteractor(
    private val playTimerCountdownSoundUseCase: PlayTimerCountdownSoundUseCase,
    private val playTimerPeriodEndSoundUseCase: PlayTimerPeriodEndSoundUseCase,
    private val playSoundPreviewUseCase: PlaySoundPreviewUseCase,
    private val stopSoundPreviewUseCase: StopSoundPreviewUseCase,
) {
    fun playCountdown(settings: TimerSettingsModel) {
        playTimerCountdownSoundUseCase(settings)
    }

    suspend fun playPeriodEnd(settings: TimerSettingsModel, type: TimerTypeModel) {
        playTimerPeriodEndSoundUseCase(settings, type)
    }

    fun playPreview(soundId: String) {
        playSoundPreviewUseCase(soundId)
    }

    fun stopPreview() {
        stopSoundPreviewUseCase()
    }
}
