package com.timemeasurer.app.core.model.timer

import kotlin.time.ExperimentalTime
import kotlin.time.Instant

@OptIn(ExperimentalTime::class)
data class TimerSessionModel(
    val id: Long = 0L,
    val timerId: Long,
    val session: Long,
    val type: TimerTypeModel,
    val startedAt: Instant,
    val endAt: Instant = startedAt,
)