private val ArrowSize = 4.dp
private val ArrowGap = 12.dp
private val DataMargin = 4.dp
private val MinBarHeight = 2.dp
private val PointMarkerRadius = 3.dp

@Composable
fun GraphWidget(
    data: List<GraphModel>,
    graphSettings: GraphSettingsModel,
    modifier: Modifier = Modifier,
    onGraphTypeChange: State<((GraphType) -> Unit)?> = remember { mutableStateOf<((GraphType) -> Unit)?>(null) },
) {
    if (data.isEmpty()) return

    val graphType = graphSettings.graphType
    val textMeasurer = rememberTextMeasurer()

    val minY = data.minOf { it.point.y }
    val maxY = data.maxOf { it.point.y }
    val yBaseline = if (graphType == GraphType.Bar) minOf(0f, minY) else minY
    val yRange = maxY - yBaseline

    val showYLabels = graphSettings.showYAxisLabels
    val showXLabels = graphSettings.showXAxisLabels
    val yTickAreaWidthDp = if (showYLabels) 30.dp else 0.dp
    val xTickAreaHeightDp = if (showXLabels) 20.dp else 0.dp

    Row(modifier = modifier) {
        if (graphSettings.showYAxisLabel && graphSettings.yAxisLabel.isNotEmpty()) {
            Box(
                modifier = Modifier
                    .fillMaxHeight()
                    .width(20.dp)
                    .padding(end = 4.dp),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = graphSettings.yAxisLabel,
                    softWrap = false,
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.rotate(-90f)
                        .wrapContentSize(unbounded = true)
                )
            }
        }

        Column(modifier = Modifier.weight(1f)) {
            Box(modifier = Modifier.weight(1f)) {
                Row(modifier = Modifier.fillMaxSize()) {
                    // Fixed Y-axis column: draws Y tick labels and tick marks
                    Box(
                        modifier = Modifier
                            .fillMaxHeight()
                            .width(yTickAreaWidthDp)
                    ) {
                        Canvas(modifier = Modifier.fillMaxSize().clipToBounds()) {
                            drawYTicks(
                                showYAxisLabels = graphSettings.showYAxisLabels,
                                yBaseline = yBaseline,
                                yRange = yRange,
                                textMeasurer = textMeasurer,
                                xTickAreaHeightDp = xTickAreaHeightDp,
                            )
                        }
                    }

                    // Scrolling data column + fixed X-axis overlay
                    BoxWithConstraints(
                        modifier = Modifier
                            .weight(1f)
                            .fillMaxHeight()
                    ) {
                        val availableWidthDp = maxWidth

                        val totalWidthDp = when (graphType) {
                            GraphType.Line -> {
                                val minSpacing = 8.dp
                                val count = data.size.coerceAtLeast(1)
                                maxOf(availableWidthDp, minSpacing * count)
                            }
                            GraphType.Bar -> {
                                val count = data.size.coerceAtLeast(1)
                                val barW = maxOf(
                                    8.dp,
                                    minOf(availableWidthDp / count, availableWidthDp / 2)
                                )
                                barW * count
                            }
                        }

                        val needsScroll = totalWidthDp > availableWidthDp
                        val scrollState = rememberScrollState()

                        Box(modifier = Modifier.fillMaxSize()) {
                            // Scrollable data area: padded on right for arrowhead, draws graph content and X tick labels
                            Box(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .padding(end = ArrowSize)
                                    .clipToBounds()
                            ) {
                                Canvas(
                                    modifier = Modifier
                                        .fillMaxHeight()
                                        .clipToBounds()
                                        .then(
                                            if (needsScroll) Modifier.horizontalScroll(scrollState)
                                            else Modifier
                                        )
                                        .then(
                                            if (needsScroll) Modifier.width(totalWidthDp)
                                            else Modifier.fillMaxWidth()
                                        )
                                ) {
                                    drawData(
                                        points = data,
                                        graphType = graphType,
                                        graphColor = graphSettings.graphColor,
                                        yBaseline = yBaseline,
                                        yRange = yRange,
                                        textMeasurer = textMeasurer,
                                        showXAxisLabels = graphSettings.showXAxisLabels,
                                        xTickAreaHeightDp = xTickAreaHeightDp,
                                    )
                                }
                            }

                            // Fixed axes overlay: draws Y axis line, X axis line, and arrowheads (never scrolls)
                            Canvas(modifier = Modifier.fillMaxSize()) {
                                drawFixedAxes(xTickAreaHeightDp = xTickAreaHeightDp)
                            }
                        }
                    }
                }
            }

            if (graphSettings.showXAxisLabel && graphSettings.xAxisLabel.isNotEmpty()) {
                Text(
                    text = graphSettings.xAxisLabel,
                    textAlign = TextAlign.Center,
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.fillMaxWidth()
                )
            }

            val onGraphTypeSelected = onGraphTypeChange.value
            if (graphSettings.showGraphTypeSelector && onGraphTypeSelected != null) {
                Spacer(modifier = Modifier.height(8.dp))
                GraphTypeSelector(
                    selectedType = graphSettings.graphType,
                    onSelect = onGraphTypeSelected,
                )
            }
        }
    }
}

@Composable
private fun GraphTypeSelector(
    selectedType: GraphType,
    onSelect: (GraphType) -> Unit,
    modifier: Modifier = Modifier,
) {
    Row(
        modifier = modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(16.dp, Alignment.CenterHorizontally),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        GraphType.entries.forEach { type ->
            Row(
                modifier = Modifier
                    .selectable(
                        selected = selectedType == type,
                        interactionSource = null,
                        indication = null,
                        role = Role.RadioButton,
                        onClick = { onSelect(type) },
                    ),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                SmallRadioButton(selected = selectedType == type)
                Spacer(Modifier.width(3.dp))
                Icon(
                    imageVector = type.icon,
                    contentDescription = null,
                    modifier = Modifier.size(24.dp),
                    tint = MaterialTheme.colorScheme.onSurfaceVariant,
                )
            }
        }
    }
}

@Composable
private fun SmallRadioButton(
    selected: Boolean,
    modifier: Modifier = Modifier,
) {
    CompositionLocalProvider(LocalMinimumInteractiveComponentSize provides 0.dp) {
        RadioButton(
            selected = selected,
            onClick = null,
            modifier = modifier.size(20.dp),
        )
    }
}

private fun DrawScope.drawYTicks(
    showYAxisLabels: Boolean,
    yBaseline: Float,
    yRange: Float,
    textMeasurer: TextMeasurer,
    xTickAreaHeightDp: Dp,
) {
    if (!showYAxisLabels) return

    val yAxisX = size.width
    val graphTop = ArrowGap.toPx() + ArrowSize.toPx()
    val graphBottom = size.height - xTickAreaHeightDp.toPx()
    val graphHeight = graphBottom - graphTop

    val axisColor = Color.Gray
    val tickTextStyle = TextStyle(fontSize = 10.sp, color = Color.Gray)

    val yTickCount = 5
    for (i in 0 until yTickCount) {
        val fraction = i.toFloat() / (yTickCount - 1)
        val yValue = yBaseline + fraction * yRange
        val yPos = graphBottom - fraction * graphHeight

        drawLine(
            color = axisColor,
            start = Offset(yAxisX - 5.dp.toPx(), yPos),
            end = Offset(yAxisX, yPos),
            strokeWidth = 1.dp.toPx()
        )

        val label = formatTickValue(yValue)
        val textResult = textMeasurer.measure(text = label, style = tickTextStyle)
        drawText(
            textLayoutResult = textResult,
            topLeft = Offset(
                yAxisX - textResult.size.width - 8.dp.toPx(),
                yPos - textResult.size.height / 2f
            )
        )
    }
}

private fun DrawScope.drawData(
    points: List<GraphModel>,
    graphType: GraphType,
    graphColor: Color,
    yBaseline: Float,
    yRange: Float,
    textMeasurer: TextMeasurer,
    showXAxisLabels: Boolean,
    xTickAreaHeightDp: Dp,
) {
    val tickTextStyle = TextStyle(fontSize = 10.sp, color = Color.Gray)
    val axisColor = Color.Gray

    val graphTop = ArrowGap.toPx() + DataMargin.toPx()
    val graphBottom = size.height - xTickAreaHeightDp.toPx()
    val graphWidth = size.width
    val graphHeight = graphBottom - graphTop

    val maxXTicks = 10
    val xTickInterval = if (points.size <= maxXTicks) 1
    else maxOf(1, points.size / 5)

    when (graphType) {
        GraphType.Line -> {
            val stepX = if (points.size > 1) graphWidth / (points.size - 1)
            else graphWidth / 2f

            for (i in points.indices) {
                val x = if (points.size > 1) i * stepX
                else graphWidth / 2f
                val yFraction = if (yRange == 0f) 0.5f else (points[i].point.y - yBaseline) / yRange
                val y = graphBottom - yFraction * graphHeight

                drawCircle(
                    color = graphColor,
                    radius = PointMarkerRadius.toPx(),
                    center = Offset(x, y)
                )

                if (i < points.size - 1) {
                    val nextX = (i + 1) * stepX
                    val nextYFraction = if (yRange == 0f) 0.5f else (points[i + 1].point.y - yBaseline) / yRange
                    val nextY = graphBottom - nextYFraction * graphHeight
                    drawLine(
                        color = graphColor,
                        start = Offset(x, y),
                        end = Offset(nextX, nextY),
                        strokeWidth = 2.dp.toPx()
                    )
                }

                if (showXAxisLabels && i % xTickInterval == 0) {
                    drawXTick(
                        axisColor = axisColor,
                        tickTextStyle = tickTextStyle,
                        textMeasurer = textMeasurer,
                        x = x,
                        graphBottom = graphBottom,
                        label = points[i].point.x.toInt().toString()
                    )
                }
            }
        }

        GraphType.Bar -> {
            val barWidth = maxOf(
                8.dp.toPx(),
                minOf(graphWidth / points.size, graphWidth / 2f)
            )
            val barGap = barWidth * 0.05f
            val barDrawWidth = barWidth - barGap

            for (i in points.indices) {
                val x = i * barWidth
                val value = points[i].point.y
                val barHeight = if (yRange == 0f) 0f else maxOf(
                    ((value - yBaseline) / yRange) * graphHeight,
                    if (value > yBaseline) MinBarHeight.toPx() else 0f
                )
                val y = graphBottom - barHeight

                drawRect(
                    color = graphColor,
                    topLeft = Offset(x + barGap / 2f, y),
                    size = Size(barDrawWidth, barHeight)
                )

                if (showXAxisLabels && i % xTickInterval == 0) {
                    val barCenter = x + barWidth / 2f
                    drawXTick(
                        axisColor = axisColor,
                        tickTextStyle = tickTextStyle,
                        textMeasurer = textMeasurer,
                        x = barCenter,
                        graphBottom = graphBottom,
                        label = points[i].point.x.toInt().toString()
                    )
                }
            }
        }
    }
}

private fun DrawScope.drawFixedAxes(
    xTickAreaHeightDp: Dp,
) {
    val arrowSizePx = ArrowSize.toPx()
    val arrowGapPx = ArrowGap.toPx()
    val graphBottom = size.height - xTickAreaHeightDp.toPx()
    val graphTop = arrowGapPx + arrowSizePx
    val axisColor = Color.Gray

    // Y axis line
    drawLine(
        color = axisColor,
        start = Offset(0f, graphTop),
        end = Offset(0f, graphBottom),
        strokeWidth = 1.dp.toPx()
    )

    // Y arrowhead (pointing up)
    val yArrowPath = Path().apply {
        moveTo(0f, arrowGapPx)
        lineTo(-arrowSizePx, arrowGapPx + arrowSizePx)
        lineTo(arrowSizePx, arrowGapPx + arrowSizePx)
        close()
    }
    drawPath(path = yArrowPath, color = axisColor)

    // X axis line
    drawLine(
        color = axisColor,
        start = Offset(0f, graphBottom),
        end = Offset(size.width - arrowSizePx, graphBottom),
        strokeWidth = 1.dp.toPx()
    )

    // X arrowhead (pointing right)
    val xArrowPath = Path().apply {
        moveTo(size.width, graphBottom)
        lineTo(size.width - arrowSizePx, graphBottom - arrowSizePx)
        lineTo(size.width - arrowSizePx, graphBottom + arrowSizePx)
        close()
    }
    drawPath(path = xArrowPath, color = axisColor)
}

private fun DrawScope.drawXTick(
    axisColor: Color,
    tickTextStyle: TextStyle,
    textMeasurer: TextMeasurer,
    x: Float,
    graphBottom: Float,
    label: String,
) {
    drawLine(
        color = axisColor,
        start = Offset(x, graphBottom),
        end = Offset(x, graphBottom + 5.dp.toPx()),
        strokeWidth = 1.dp.toPx()
    )

    val textResult = textMeasurer.measure(text = label, style = tickTextStyle)
    val textX = (x - textResult.size.width / 2f)
        .coerceIn(0f, size.width - textResult.size.width)
    drawText(
        textLayoutResult = textResult,
        topLeft = Offset(
            textX,
            graphBottom + 8.dp.toPx()
        )
    )
}

private fun formatTickValue(value: Float): String {
    val rounded = value.roundToInt()
    if (rounded.toFloat() == value) return rounded.toString()
    val decimal = ((value - rounded) * 10).roundToInt().coerceIn(0, 9)
    return "$rounded.$decimal"
}

