@Preview
@Composable
private fun GraphWidgetPreviewWithTypeSelector() {
    MaterialTheme {
        val primaryColor = MaterialTheme.colorScheme.primary
        val sampleData = remember {
            mutableListOf(
                GraphModel(Point(0f, 1000f)),
                GraphModel(Point(1f, 5000f)),
                GraphModel(Point(2f, 3000f)),
                GraphModel(Point(3f, 8000f)),
                GraphModel(Point(4f, 2000f)),
            )
        }
        var currentType by remember { mutableStateOf<GraphType>(GraphType.Line) }
        val graphSettings = remember(currentType) {
            GraphSettingsModel(
                graphType = currentType,
                graphColor = primaryColor,
                xAxisLabel = "Lap",
                yAxisLabel = "Duration",
