package com.timemeasurer.app.core.domain.timer

class ValidateLongBreakAfterUseCase {
    companion object {
        const val MIN = 2
        const val MAX = 100
    }

    fun validate(value: Int): ValidateLongBreakAfterResult {
        val clamped = value.coerceIn(MIN, MAX)
        return ValidateLongBreakAfterResult(
            clampedValue = clamped,
            isClamped = clamped != value,
            min = MIN,
            max = MAX,
        )
    }
}
