package com.timemeasurer.app.feature.settings

import androidx.lifecycle.viewModelScope
import com.timemeasurer.app.core.common.AppBuildInfo
import com.timemeasurer.app.core.common.di.Inject
import com.timemeasurer.app.core.data.repositories.theme.ThemeRepository
import com.timemeasurer.app.core.domain.settings.KeepScreenOnSettingUseCase
import com.timemeasurer.app.core.domain.settings.SingleActiveTimerSettingUseCase
import com.timemeasurer.app.core.domain.settings.VibrationSettingUseCase
import com.timemeasurer.app.core.model.SettingsData
import com.timemeasurer.app.core.ui.viewmodels.UiState
import com.timemeasurer.app.core.ui.viewmodels.UiStateViewModel
import com.timemeasurer.app.feature.settings.models.SettingsActions
import com.timemeasurer.app.feature.settings.models.SettingsEvents
import com.timemeasurer.app.feature.settings.models.SettingsUiModel
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

class SettingsViewModel(
    private val singleActiveTimerSettingUseCase: SingleActiveTimerSettingUseCase = Inject.instance(),
    private val keepScreenOnSettingUseCase: KeepScreenOnSettingUseCase = Inject.instance(),
    private val vibrationSettingUseCase: VibrationSettingUseCase = Inject.instance(),
    private val themeRepository: ThemeRepository = Inject.instance(),
) :  UiStateViewModel<SettingsUiModel, SettingsActions, SettingsEvents>(
    initialAction = SettingsActions.None
) {

    override val state: StateFlow<UiState<SettingsUiModel>> = combine(
        themeRepository.themeData,
        singleActiveTimerSettingUseCase(),
        keepScreenOnSettingUseCase(),
        vibrationSettingUseCase(),
    ) { themeData, activeTimerSetting, keepScreenOn, vibration ->
        UiState.Success(
            SettingsUiModel(
                settingsData = SettingsData(version = AppBuildInfo.VERSION_NAME),
                themeData = themeData,
                isSingleActiveTimer = activeTimerSetting.isEnabled,
                isKeepScreenOn = keepScreenOn,
                isVibrationEnabled = vibration,
            )
        )
    }.stateIn(
        scope = viewModelScope,
        started = SharingStarted.Lazily,
        initialValue = UiState.Loading
    )

    override fun setEvent(item: SettingsEvents) {
        when (item) {
            is SettingsEvents.UpdateDarkThemeConfig -> {
                viewModelScope.launch {
                    themeRepository.setDarkThemeConfig(item.darkThemeConfig)
                }
            }
            is SettingsEvents.UpdateSingleActiveTimer -> {
                viewModelScope.launch {
                    singleActiveTimerSettingUseCase.setEnabled(item.value)
                }
            }
            is SettingsEvents.UpdateKeepScreenOn -> {
                viewModelScope.launch {
                    keepScreenOnSettingUseCase.setEnabled(item.value)
                }
            }
            is SettingsEvents.UpdateVibration -> {
                viewModelScope.launch {
                    vibrationSettingUseCase.setEnabled(item.value)
                }
            }
            is SettingsEvents.None -> {}
        }
    }
}
