    bind<GetStopwatchesStatisticsUseCase>() with provider { GetStopwatchesStatisticsUseCase(instance(), instance(), instance(tag = DI_TAG_DISPATCHER_IO)) }

    // Stopwatch interactor
    bind<StopwatchesInteractors>() with singleton {
        StopwatchesInteractors(instance(), instance(), instance(), instance(), instance(), instance(), instance(), instance(), instance(),
