    bind<PlayTimerCountdownSoundUseCase>() with provider { PlayTimerCountdownSoundUseCase(instance()) }
    bind<PlayTimerPeriodEndSoundUseCase>() with provider { PlayTimerPeriodEndSoundUseCase(instance(), instance()) }
    bind<PlaySoundPreviewUseCase>() with provider { PlaySoundPreviewUseCase(instance()) }
    bind<StopSoundPreviewUseCase>() with provider { StopSoundPreviewUseCase(instance()) }
    bind<TimerSoundInteractor>() with provider { TimerSoundInteractor(instance(), instance(), instance(), instance()) }

