    bind<ValidateTimerDurationUseCase>() with provider { ValidateTimerDurationUseCase() }
    bind<ValidateLongBreakAfterUseCase>() with provider { ValidateLongBreakAfterUseCase() }
    bind<ValidateNameUseCase>() with provider { ValidateNameUseCase() }
