package com.timemeasurer.app.feature.timer_settings

import androidx.lifecycle.viewModelScope
import com.timemeasurer.app.core.common.di.Inject
import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.domain.sound.TimerSoundInteractor
import com.timemeasurer.app.core.domain.timer.GetTimerByIdUseCase
import com.timemeasurer.app.core.domain.timer.GetTimersUseCase
import com.timemeasurer.app.core.domain.timer.UpdateAllTimersSettingsUseCase
import com.timemeasurer.app.core.domain.timer.UpdateTimerUseCase
import com.timemeasurer.app.core.domain.timer.ValidateLongBreakAfterUseCase
import com.timemeasurer.app.core.domain.timer.ValidateTimerDurationUseCase
import com.timemeasurer.app.core.model.timer.TimerModel
import com.timemeasurer.app.core.model.timer.TimerSettingsEvents
import com.timemeasurer.app.core.model.timer.TimerSettingsModel
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.unknown_error
import com.timemeasurer.app.core.ui.viewmodels.UiState
import com.timemeasurer.app.core.ui.viewmodels.UiStateViewModel
import com.timemeasurer.app.feature.timer_settings.models.TimerSettingsActions
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

internal class TimerSettingsViewModel(
    private val getTimerByIdUseCase: GetTimerByIdUseCase = Inject.instance(),
    private val updateTimerUseCase: UpdateTimerUseCase = Inject.instance(),
    private val getTimersUseCase: GetTimersUseCase = Inject.instance(),
    private val updateAllTimersSettingsUseCase: UpdateAllTimersSettingsUseCase = Inject.instance(),
    private val timerSoundInteractor: TimerSoundInteractor = Inject.instance(),
    private val validateTimerDurationUseCase: ValidateTimerDurationUseCase = Inject.instance(),
    private val validateLongBreakAfterUseCase: ValidateLongBreakAfterUseCase = Inject.instance(),
) : UiStateViewModel<TimerSettingsModel, TimerSettingsActions, TimerSettingsEvents>(
    initialAction = TimerSettingsActions.None
) {
    private val _timerId = MutableStateFlow<Long?>(null)
    private val _timerName = MutableStateFlow<String?>(null)
    private val _uiModel = MutableStateFlow<TimerSettingsModel?>(null)

    override val state: StateFlow<UiState<TimerSettingsModel>> = _uiModel
        .map { if (it != null) UiState.Success(it) else UiState.Empty }
        .stateIn(
            scope = viewModelScope,
            started = SharingStarted.Lazily,
            initialValue = UiState.Loading
        )

    override fun setEvent(item: TimerSettingsEvents) {
        when (item) {
            TimerSettingsEvents.None -> setAction(TimerSettingsActions.None)
            is TimerSettingsEvents.Load -> {
                val timerId = item.timerId
                if (timerId != null) {
                    loadSingleTimer(timerId)
                } else {
                    loadGlobalTemplate()
                }
            }
            is TimerSettingsEvents.UpdateSessionDuration -> _uiModel.update {
                val model = it ?: return@update it
                if (item.value == model.sessionDuration) return@update model
                val result = validateTimerDurationUseCase.validate(item.value, model.sessionDurationUnit)
                model.copy(
                    sessionDuration = result.validatedMs,
                    sessionDurationErrorMin = if (result.isClamped) result.displayMin else null,
                    sessionDurationErrorMax = if (result.isClamped) result.displayMax else null,
                )
            }
            is TimerSettingsEvents.UpdateShortBreakDuration -> _uiModel.update {
                val model = it ?: return@update it
                if (item.value == model.shortBreakDuration) return@update model
                val result = validateTimerDurationUseCase.validate(item.value, model.shortBreakDurationUnit)
                model.copy(
                    shortBreakDuration = result.validatedMs,
                    shortBreakDurationErrorMin = if (result.isClamped) result.displayMin else null,
                    shortBreakDurationErrorMax = if (result.isClamped) result.displayMax else null,
                )
            }
            is TimerSettingsEvents.UpdateLongBreakDuration -> _uiModel.update {
                val model = it ?: return@update it
                if (item.value == model.longBreakDuration) return@update model
                val result = validateTimerDurationUseCase.validate(item.value, model.longBreakDurationUnit)
                model.copy(
                    longBreakDuration = result.validatedMs,
                    longBreakDurationErrorMin = if (result.isClamped) result.displayMin else null,
                    longBreakDurationErrorMax = if (result.isClamped) result.displayMax else null,
                )
            }
            is TimerSettingsEvents.UpdateSessionDurationUnit -> _uiModel.update {
                val model = it ?: return@update it
                if (item.unit == model.sessionDurationUnit) return@update model
                val result = validateTimerDurationUseCase.convertAndValidate(model.sessionDuration, item.unit)
                model.copy(
                    sessionDurationUnit = item.unit,
                    sessionDuration = result.validatedMs,
                    sessionDurationErrorMin = null,
                    sessionDurationErrorMax = null,
                )
            }
            is TimerSettingsEvents.UpdateShortBreakDurationUnit -> _uiModel.update {
                val model = it ?: return@update it
                if (item.unit == model.shortBreakDurationUnit) return@update model
                val result = validateTimerDurationUseCase.convertAndValidate(model.shortBreakDuration, item.unit)
                model.copy(
                    shortBreakDurationUnit = item.unit,
                    shortBreakDuration = result.validatedMs,
                    shortBreakDurationErrorMin = null,
                    shortBreakDurationErrorMax = null,
                )
            }
            is TimerSettingsEvents.UpdateLongBreakDurationUnit -> _uiModel.update {
                val model = it ?: return@update it
                if (item.unit == model.longBreakDurationUnit) return@update model
                val result = validateTimerDurationUseCase.convertAndValidate(model.longBreakDuration, item.unit)
                model.copy(
                    longBreakDurationUnit = item.unit,
                    longBreakDuration = result.validatedMs,
                    longBreakDurationErrorMin = null,
                    longBreakDurationErrorMax = null,
                )
            }
            is TimerSettingsEvents.UpdateLongBreakAfterSession -> _uiModel.update {
                val model = it ?: return@update it
                if (item.value == model.longBreakAfterSession) return@update model
                val result = validateLongBreakAfterUseCase.validate(item.value)
                model.copy(
                    longBreakAfterSession = result.clampedValue,
                    longBreakAfterErrorMin = if (result.isClamped) result.min else null,
                    longBreakAfterErrorMax = if (result.isClamped) result.max else null,
                )
            }
            is TimerSettingsEvents.UpdateIsTimerStartAuto -> _uiModel.update { it?.copy(isTimerStartAuto = item.value) }
            is TimerSettingsEvents.UpdateIsSessionStartAuto -> _uiModel.update { it?.copy(isSessionStartAuto = item.value) }
            is TimerSettingsEvents.UpdateIsBreakStartAuto -> _uiModel.update { it?.copy(isBreakStartAuto = item.value) }
            is TimerSettingsEvents.UpdateIsLongBreakEnabled -> _uiModel.update { it?.copy(isLongBreakEnabled = item.value) }
            is TimerSettingsEvents.UpdateIsShortBreakEnabled -> _uiModel.update { it?.copy(isShortBreakEnabled = item.value) }
            is TimerSettingsEvents.UpdateIsCountdownSoundEnabled -> _uiModel.update { it?.copy(isCountdownSoundEnabled = item.value) }
            is TimerSettingsEvents.UpdateCountdownSoundId -> _uiModel.update { it?.copy(countdownSoundId = item.value) }
            is TimerSettingsEvents.UpdateIsSessionEndSoundEnabled -> _uiModel.update { it?.copy(isSessionEndSoundEnabled = item.value) }
            is TimerSettingsEvents.UpdateSessionEndSoundId -> _uiModel.update { it?.copy(sessionEndSoundId = item.value) }
            is TimerSettingsEvents.UpdateIsRestEndSoundEnabled -> _uiModel.update { it?.copy(isRestEndSoundEnabled = item.value) }
            is TimerSettingsEvents.UpdateRestEndSoundId -> _uiModel.update { it?.copy(restEndSoundId = item.value) }
            is TimerSettingsEvents.UpdateProgressType -> _uiModel.update { it?.copy(progressType = item.value) }
            is TimerSettingsEvents.PreviewSound -> timerSoundInteractor.playPreview(item.soundId)
            is TimerSettingsEvents.StopPreviewSound -> timerSoundInteractor.stopPreview()
            is TimerSettingsEvents.ValidateSessionDuration -> _uiModel.update {
                val model = it ?: return@update it
                val result = validateTimerDurationUseCase.validate(model.sessionDuration, model.sessionDurationUnit)
                model.copy(
                    sessionDurationErrorMin = if (result.isClamped) result.displayMin else null,
                    sessionDurationErrorMax = if (result.isClamped) result.displayMax else null,
                )
            }
            is TimerSettingsEvents.ValidateShortBreakDuration -> _uiModel.update {
                val model = it ?: return@update it
                val result = validateTimerDurationUseCase.validate(model.shortBreakDuration, model.shortBreakDurationUnit)
                model.copy(
                    shortBreakDurationErrorMin = if (result.isClamped) result.displayMin else null,
                    shortBreakDurationErrorMax = if (result.isClamped) result.displayMax else null,
                )
            }
            is TimerSettingsEvents.ValidateLongBreakDuration -> _uiModel.update {
                val model = it ?: return@update it
                val result = validateTimerDurationUseCase.validate(model.longBreakDuration, model.longBreakDurationUnit)
                model.copy(
                    longBreakDurationErrorMin = if (result.isClamped) result.displayMin else null,
                    longBreakDurationErrorMax = if (result.isClamped) result.displayMax else null,
                )
            }
            is TimerSettingsEvents.ValidateLongBreakAfterSession -> _uiModel.update {
                val model = it ?: return@update it
                val result = validateLongBreakAfterUseCase.validate(model.longBreakAfterSession)
                model.copy(
                    longBreakAfterErrorMin = if (result.isClamped) result.min else null,
                    longBreakAfterErrorMax = if (result.isClamped) result.max else null,
                )
            }
            is TimerSettingsEvents.Apply -> {
                val timerId = _timerId.value
                if (timerId != null) {
                    applySingleTimer(timerId)
                } else {
                    applyGlobal()
                }
            }
        }
    }

    private fun loadSingleTimer(timerId: Long) {
        _timerId.value = timerId
        viewModelScope.launch {
            val result = getTimerByIdUseCase(timerId).first { it !is Result.Loading }
            when (result) {
                is Result.Error -> setAction(TimerSettingsActions.ShowError(Res.string.unknown_error))
                is Result.Success -> {
                    val timer = result.data
                    if (timer != null) {
                        _timerName.value = timer.name
                        _uiModel.value = timer.settings
                    } else {
                        _uiModel.value = null
                    }
                }
                is Result.Loading -> {}
            }
        }
    }

    private fun loadGlobalTemplate() {
        _timerId.value = null
        _timerName.value = null
        viewModelScope.launch {
            getTimersUseCase().collect { result ->
                when (result) {
                    is Result.Loading -> {}
                    is Result.Error -> {}
                    is Result.Success -> {
                        val first = result.data.firstOrNull()
                        if (first != null && _uiModel.value == null) {
                            _uiModel.value = first.settings
                        } else if (first == null) {
                            _uiModel.value = null
                        }
                    }
                }
            }
        }
    }

    private fun applySingleTimer(timerId: Long) {
        viewModelScope.launch {
            val current = _uiModel.value ?: return@launch
            val timer = TimerModel(
                id = timerId,
                name = _timerName.value ?: "",
                settings = current
            )
            when (val result = updateTimerUseCase(timer)) {
                is Result.Success -> setAction(TimerSettingsActions.Dismiss)
                is Result.Error -> setAction(TimerSettingsActions.ShowError(Res.string.unknown_error))
                is Result.Loading -> {}
            }
        }
    }

    private fun applyGlobal() {
        viewModelScope.launch {
            val settings = _uiModel.value ?: return@launch
            when (val result = updateAllTimersSettingsUseCase(settings)) {
                is Result.Success -> setAction(TimerSettingsActions.Dismiss)
                is Result.Error -> setAction(TimerSettingsActions.ShowError(Res.string.unknown_error))
                is Result.Loading -> {}
            }
        }
    }
}
