package com.timemeasurer.app.core.common.extensions

fun Long.secondsToHMS(): Array<Int> {
    return arrayOf((this / 3600).toInt(), ((this % 3600) / 60).toInt(), (this % 60).toInt())
}

fun Long.secondsToFormatTimeHMS(delimiter: Char = ':'): String {
    val time = secondsToHMS()
    val hours = time[0].takeIf { it > 0 }?.toString()?.padStart(2, '0')?.plus(delimiter) ?: ""
    val minutes = time[1].toString().padStart(2, '0') + delimiter
    val seconds = time[2].toString().padStart(2, '0')
    return "$hours$minutes$seconds"
}

fun Float.formatToDecimals(decimals: Int = 1, zeroValue: String = "0.0"): String {
    if (this == 0f) return zeroValue
    var multiplier = 1
    repeat(decimals) { multiplier *= 10 }
    val scaled = kotlin.math.round(this * multiplier).toInt()
    val whole = scaled / multiplier
    val fraction = kotlin.math.abs(scaled % multiplier)
    val fractionStr = fraction.toString().padStart(decimals, '0')
    return "$whole.$fractionStr"
}

fun Long.millisecondsToFormatStopwatchTime(delimiter: Char = ':'): String = buildString {
    val totalSeconds = this@millisecondsToFormatStopwatchTime / 1000
    val milliseconds = this@millisecondsToFormatStopwatchTime % 1000
    val hours = totalSeconds / 3600
    val minutes = (totalSeconds % 3600) / 60
    val seconds = totalSeconds % 60
    val msStr = (milliseconds / 10).toString().padStart(2, '0')
    if (hours > 0) {
        append(hours.toString().padStart(2, '0'))
        append(delimiter)
        append(minutes.toString().padStart(2, '0'))
        append(delimiter)
        append(seconds.toString().padStart(2, '0'))
        append('.')
        append(msStr)
    } else {
        append(minutes.toString().padStart(2, '0'))
        append(delimiter)
        append(seconds.toString().padStart(2, '0'))
        append('.')
        append(msStr)
    }
}

fun Long.roundToNearest(n: Long): Long = (this + n / 2) / n * n

fun Long.roundDown(n: Long): Long = this / n * n