package com.timemeasurer.app.core.data.di

import com.timemeasurer.app.core.common.di.DI_TAG_DISPATCHER_IO
import com.timemeasurer.app.core.common.di.DI_TAG_SCOPE_IO
import com.timemeasurer.app.core.data.database.databaseModule
import com.timemeasurer.app.core.data.repositories.settings.SettingsRepository
import com.timemeasurer.app.core.data.repositories.settings.SettingsRepositoryImpl
import com.timemeasurer.app.core.data.repositories.stopwatch_laps.StopwatchLapsRepository
import com.timemeasurer.app.core.data.repositories.stopwatch_laps.StopwatchLapsRepositoryImpl
import com.timemeasurer.app.core.data.repositories.stopwatches.StopwatchesRepository
import com.timemeasurer.app.core.data.repositories.stopwatches.StopwatchesRepositoryImpl
import com.timemeasurer.app.core.data.repositories.theme.ThemeRepository
import com.timemeasurer.app.core.data.repositories.theme.ThemeRepositoryImpl
import com.timemeasurer.app.core.data.repositories.timer_session.TimerSessionRepository
import com.timemeasurer.app.core.data.repositories.timer_session.TimerSessionRepositoryImpl
import com.timemeasurer.app.core.data.repositories.timers.TimersRepository
import com.timemeasurer.app.core.data.repositories.timers.TimersRepositoryImpl
import org.kodein.di.DI
import org.kodein.di.bind
import org.kodein.di.instance
import org.kodein.di.singleton

const val DI_MODULE_DATA = "dataModule"

val dataModule = DI.Module(DI_MODULE_DATA) {
    import(databaseModule)
    bind<TimersRepository>() with singleton {
        TimersRepositoryImpl(instance(), instance(tag = DI_TAG_SCOPE_IO), instance())
    }
    bind<TimerSessionRepository>() with singleton {
        TimerSessionRepositoryImpl(instance(), instance(tag = DI_TAG_SCOPE_IO), instance())
    }
    bind<StopwatchesRepository>() with singleton {
        StopwatchesRepositoryImpl(instance(), instance(tag = DI_TAG_SCOPE_IO), instance())
    }
    bind<StopwatchLapsRepository>() with singleton {
        StopwatchLapsRepositoryImpl(instance(), instance(tag = DI_TAG_SCOPE_IO), instance())
    }
    bind<SettingsRepository>() with singleton {
        SettingsRepositoryImpl(instance(), instance())
    }
    bind<ThemeRepository>() with singleton {
        ThemeRepositoryImpl(instance(), instance(tag = DI_TAG_DISPATCHER_IO))
    }
}
