@Composable
fun StopwatchItemContent(
    dataModel: StopwatchUiDataModel,
    tickState: StateFlow<StopwatchUiTickModel>,
    onEventAction: (StopwatchEvents) -> Unit,
    modifier: Modifier = Modifier
) {

    println("StopwatchItemContent()")

    val scrollState = rememberScrollState()

    Box(
        modifier = modifier
            .fillMaxSize()
            .verticalScroll(scrollState),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            modifier = Modifier.wrapContentSize()
        ) {
            Spacer(Modifier.height(16.dp))

            if (dataModel.showLaps) {
                StopwatchLapsList(
                    laps = dataModel.laps,
                    modifier = Modifier.fillMaxWidth()
                )

                Spacer(Modifier.height(16.dp))
            }

            StopwatchCenterDisplay(
                tickState = tickState,
                showCurrent = dataModel.showCurrent,
                showMinMax = dataModel.showMinMax,
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(Modifier.height(8.dp))

            StopwatchControls(
                isRunning = dataModel.isRunning,
                onStartStop = { onEventAction(StopwatchEvents.StartStop(dataModel.stopwatchId)) },
                onReset = { onEventAction(StopwatchEvents.ShowResetDialog(dataModel.stopwatchId)) },
                onLap = { onEventAction(StopwatchEvents.Lap(dataModel.stopwatchId)) },
            )

            Spacer(Modifier.height(16.dp))
        }
    }
}

