@Composable
fun soundDisplayName(soundId: String): String = when (PredefinedSound.fromId(soundId)) {
    PredefinedSound.BEEP_CLEAN -> stringResource(Res.string.sound_beep_clean)
    PredefinedSound.BEEP_SQUARE -> stringResource(Res.string.sound_beep_square)
    PredefinedSound.CHIRP_UP -> stringResource(Res.string.sound_chirp_up)
    PredefinedSound.FM_WHISTLE -> stringResource(Res.string.sound_fm_whistle)
    PredefinedSound.NOISE_CLICK -> stringResource(Res.string.sound_noise_click)
    PredefinedSound.DIGITAL_TICK -> stringResource(Res.string.sound_digital_tick)
    PredefinedSound.SOFT_PING -> stringResource(Res.string.sound_soft_ping)
    PredefinedSound.GLASS_TAP -> stringResource(Res.string.sound_glass_tap)
    PredefinedSound.BELL_BRIGHT -> stringResource(Res.string.sound_bell_bright)
    PredefinedSound.GONG_LOW -> stringResource(Res.string.sound_gong_low)
    PredefinedSound.GLASS_CHIME -> stringResource(Res.string.sound_glass_chime)
    PredefinedSound.DIGITAL_ALARM -> stringResource(Res.string.sound_digital_alarm)
    PredefinedSound.SYNTH_PAD -> stringResource(Res.string.sound_synth_pad)
    PredefinedSound.ORGAN_CHORD -> stringResource(Res.string.sound_organ_chord)
    PredefinedSound.CHIME_METAL -> stringResource(Res.string.sound_chime_metal)
    PredefinedSound.COSMIC_SHIMMER -> stringResource(Res.string.sound_cosmic_shimmer)
    PredefinedSound.WOOD_BLOCK -> stringResource(Res.string.sound_wood_block)
    PredefinedSound.HARP_GLISS -> stringResource(Res.string.sound_harp_gliss)
    PredefinedSound.PIANO_NOTE -> stringResource(Res.string.sound_piano_note)
    PredefinedSound.FLUTE_NOTE -> stringResource(Res.string.sound_flute_note)
    PredefinedSound.MARIMBA -> stringResource(Res.string.sound_marimba)
    PredefinedSound.PIZZICATO -> stringResource(Res.string.sound_pizzicato)
    PredefinedSound.STEEL_DRUM -> stringResource(Res.string.sound_steel_drum)
    PredefinedSound.CHOIR_PAD -> stringResource(Res.string.sound_choir_pad)
    PredefinedSound.NONE -> stringResource(Res.string.sound_none)
}

@Composable
fun SoundPickerDialog(
    title: String,
    selectedSoundId: String,
    isShortSound: Boolean,
    onDismiss: () -> Unit,
    onSoundSelected: (String) -> Unit,
    onPreviewSound: (String) -> Unit,
    onStopPreview: () -> Unit,
) {
    val selectableSounds = PredefinedSound.entries.filter {
        it != PredefinedSound.NONE && it.isShort == isShortSound
    }

    DisposableEffect(Unit) {
        onDispose { onStopPreview() }
    }

    GradientAlertDialog(
        onDismissRequest = {
            onStopPreview()
            onDismiss()
        },
        title = title,
        content = {
            SoundPickerList(
                selectableSounds = selectableSounds,
                selectedSoundId = selectedSoundId,
                onSoundSelected = { soundId ->
                    onStopPreview()
                    onSoundSelected(soundId)
                },
                onPreviewSound = onPreviewSound,
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(max = 300.dp),
            )
        },
        dismissText = stringResource(Res.string.cancel),
        onDismissClick = {
            onStopPreview()
            onDismiss()
        },
    )
}

@Composable
private fun SoundPickerList(
    selectableSounds: List<PredefinedSound>,
    selectedSoundId: String,
    onSoundSelected: (String) -> Unit,
    onPreviewSound: (String) -> Unit,
    modifier: Modifier = Modifier,
) {
    val listState = rememberLazyListState()
    Box(modifier = modifier) {
        LazyColumn(
            state = listState,
            modifier = Modifier
                .fillMaxWidth()
                .selectableGroup(),
            verticalArrangement = Arrangement.spacedBy(4.dp),
        ) {
            items(selectableSounds) { sound ->
                val isSelected = sound.id == selectedSoundId
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .selectable(
                            selected = isSelected,
                            role = Role.RadioButton,
                            onClick = { onSoundSelected(sound.id) },
                        ),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceBetween,
                ) {
                    Text(
                        text = soundDisplayName(sound.id),
                        modifier = Modifier
                            .weight(1f)
                            .padding(start = 24.dp),
                    )
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        modifier = Modifier.padding(end = 24.dp),
                    ) {
                        IconButton(
                            onClick = { onPreviewSound(sound.id) },
                            modifier = Modifier.size(40.dp),
                        ) {
                            Icon(
                                imageVector = Icons.Default.PlayArrow,
                                contentDescription = "Play preview",
                            )
                        }
                        RadioButton(
                            selected = isSelected,
                            onClick = null,
                        )
                    }
                }
            }
        }
    }
}
