package com.timemeasurer.app

import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.runtime.Composable
import androidx.compose.ui.tooling.preview.Preview
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import androidx.lifecycle.viewmodel.compose.viewModel
import com.timemeasurer.app.core.model.DarkThemeConfig
import com.timemeasurer.app.core.model.ThemeColor
import com.timemeasurer.app.core.ui.di.uiViewModelsModule
import com.timemeasurer.app.core.ui.system.KeepScreenOn
import com.timemeasurer.app.core.ui.theme.AppTheme
import org.kodein.di.compose.withDI

@Composable
@Preview
fun AppRoot(
    viewModel: AppViewModel = viewModel { AppViewModel() },
) {
    val uiState = viewModel.uiState.collectAsStateWithLifecycle()
    val darkTheme = shouldUseDarkTheme(uiState.value)
    val themeColor = shouldUseThemeColor(uiState.value)
    val isGradientEnabled = shouldUseGradient(uiState.value, darkTheme)
    val gradientEndColor = shouldUseGradientEndColor(uiState.value)
    val isKeepScreenOn = shouldUseKeepScreenOn(uiState.value)

    withDI(uiViewModelsModule) {
        AppTheme(
            darkTheme = darkTheme,
            themeColor = themeColor,
            isGradientEnabled = isGradientEnabled,
            gradientEndColor = gradientEndColor,
        ) {
            KeepScreenOn(enabled = isKeepScreenOn)
            AppScreen()
        }
    }
}

@Composable
private fun shouldUseDarkTheme(
    uiState: AppUiState,
): Boolean = when (uiState) {
    AppUiState.Loading -> isSystemInDarkTheme()
    is AppUiState.Success -> when (uiState.themeData.darkThemeConfig) {
        DarkThemeConfig.FOLLOW_SYSTEM -> isSystemInDarkTheme()
        DarkThemeConfig.LIGHT -> false
        DarkThemeConfig.DARK -> true
    }
}

@Composable
private fun shouldUseThemeColor(
    uiState: AppUiState,
): ThemeColor = when (uiState) {
    AppUiState.Loading -> ThemeColor.WHITE
    is AppUiState.Success -> uiState.themeData.themeColor
}

@Composable
private fun shouldUseGradient(
    uiState: AppUiState,
    darkTheme: Boolean,
): Boolean = when (uiState) {
    AppUiState.Loading -> false
    is AppUiState.Success -> uiState.themeData.isGradientBackgroundEnabled && !darkTheme
}

@Composable
private fun shouldUseGradientEndColor(
    uiState: AppUiState,
): ThemeColor = when (uiState) {
    AppUiState.Loading -> ThemeColor.WHITE
    is AppUiState.Success -> uiState.themeData.gradientEndColor
}

@Composable
private fun shouldUseKeepScreenOn(
    uiState: AppUiState,
): Boolean = when (uiState) {
    AppUiState.Loading -> false
    is AppUiState.Success -> uiState.isKeepScreenOn
}
