package com.timemeasurer.app.core.ui.theme

import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.material3.MaterialTheme
import androidx.compose.runtime.Composable
import androidx.compose.runtime.CompositionLocalProvider
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp
import com.materialkolor.dynamicColorScheme
import com.timemeasurer.app.core.model.ThemeColor

@Composable
fun AppTheme(
    darkTheme: Boolean = isSystemInDarkTheme(),
    themeColor: ThemeColor = ThemeColor.WHITE,
    isGradientEnabled: Boolean = false,
    gradientEndColor: ThemeColor = ThemeColor.WHITE,
    content: @Composable () -> Unit,
) {
    val colorScheme = if (isGradientEnabled && !darkTheme) {
        val primarySeed = themeColor.seedColor()
        val endSeed = gradientEndColor.seedColor()
        val primaryLuma = primarySeed.red * 0.299f + primarySeed.green * 0.587f + primarySeed.blue * 0.114f
        val endLuma = endSeed.red * 0.299f + endSeed.green * 0.587f + endSeed.blue * 0.114f
        val darkerSeed = if (primaryLuma < endLuma) primarySeed else endSeed
        dynamicColorScheme(seedColor = darkerSeed, isDark = darkTheme)
    } else {
        themeColor.toColorScheme(darkTheme)
    }

    val gradientBrush = if (isGradientEnabled && !darkTheme) {
        Brush.linearGradient(
            colors = listOf(themeColor.seedColor(), gradientEndColor.seedColor()),
            start = Offset(0f, 0f),
            end = Offset(Float.POSITIVE_INFINITY, Float.POSITIVE_INFINITY),
        )
    } else {
        null
    }

    val backgroundTheme = BackgroundTheme(
        color = if (gradientBrush != null) Color.Transparent else colorScheme.surface,
        tonalElevation = if (gradientBrush != null) 0.dp else 2.dp,
        gradientBrush = gradientBrush,
    )

    SystemBarAppearance(darkTheme = darkTheme)

    CompositionLocalProvider(
        LocalBackgroundTheme provides backgroundTheme,
        LocalTintTheme provides TintTheme(),
    ) {
        MaterialTheme(
            colorScheme = colorScheme,
            typography = Typography,
            content = content,
        )
    }
}
