@Composable
fun StopwatchCenterDisplay(
    tickState: StateFlow<StopwatchUiTickModel>,
    showCurrent: Boolean = false,
    showMinMax: Boolean = false,
    modifier: Modifier = Modifier
) {
    println("StopwatchCenterDisplay()")

    val tick by tickState.collectAsStateWithLifecycle()
    val currentLap = tick.currentLap
    val maxLap = tick.maxLap
    val minLap = tick.minLap

    println("StopwatchCenterDisplay() - timer: ${tick.stopwatchId}")

    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        modifier = modifier
    ) {
        if (currentLap != null && showCurrent) {
            BoxWithConstraints(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 8.dp)
            ) {
                val circleCount = when {
                    showMinMax && maxLap != null && minLap != null -> 3
                    else -> 1
                }
                val totalSpacing = 8.dp * (circleCount - 1)
                val maxCircleSize = ((maxWidth - totalSpacing) / circleCount.coerceAtLeast(1))
                    .coerceAtMost(110.dp)

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(maxCircleSize),
                    horizontalArrangement = Arrangement.spacedBy(
                        space = 8.dp,
                        alignment = Alignment.CenterHorizontally
                    ),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    if (showMinMax && maxLap != null) {
                        StopwatchLapTag(
                            lapNumber = maxLap.lapNumber,
                            lapTime = maxLap.formattedDuration(),
                            totalTime = maxLap.totalTimeFromStart.millisecondsToFormatStopwatchTime(),
                            backgroundColor = MaterialTheme.colorScheme.secondaryContainer,
                            textColor = MaterialTheme.colorScheme.onSecondaryContainer,
                            modifier = Modifier.size(maxCircleSize)
                        )
                    }

                    StopwatchLapTag(
                        lapNumber = currentLap.lapNumber,
                        lapTime = currentLap.formattedDuration(),
                        backgroundColor = MaterialTheme.colorScheme.primaryContainer,
                        textColor = MaterialTheme.colorScheme.onPrimaryContainer,
                        modifier = Modifier.size(maxCircleSize)
                    )

                    if (showMinMax && minLap != null) {
                        StopwatchLapTag(
                            lapNumber = minLap.lapNumber,
                            lapTime = minLap.formattedDuration(),
                            totalTime = minLap.totalTimeFromStart.millisecondsToFormatStopwatchTime(),
                            backgroundColor = MaterialTheme.colorScheme.tertiaryContainer,
                            textColor = MaterialTheme.colorScheme.onTertiaryContainer,
                            modifier = Modifier.size(maxCircleSize)
                        )
                    }
                }
            }

            Spacer(Modifier.height(16.dp))
        }

        StopwatchDisplay(time = tick.elapsed)
    }
}

@Preview
@Composable
private fun StopwatchCenterDisplayWithLapsPreview() {
    val laps = listOf(
        StopwatchLapModel(id = 1, stopwatchId = 1, lapNumber = 1, time = 123_456, totalTimeFromStart = 123_456),
        StopwatchLapModel(id = 2, stopwatchId = 1, lapNumber = 2, time = 76_544, totalTimeFromStart = 200_000),
        StopwatchLapModel(id = 3, stopwatchId = 1, lapNumber = 3, time = 150_000, totalTimeFromStart = 350_000)
    )
    val tick = StopwatchUiTickModel(
        stopwatchId = 0,
        elapsed = "07:42.34",
        currentLap = StopwatchLapModel(id = 0, stopwatchId = 1, lapNumber = 5, time = 12_340, totalTimeFromStart = 462_340),
        minLap = laps[2],
        maxLap = laps[0]
    )

    StopwatchCenterDisplay(
        tickState = MutableStateFlow(tick),
        showCurrent = true,
        showMinMax = true
    )
}

