package com.timemeasurer.app

import com.timemeasurer.app.core.common.di.Inject
import com.timemeasurer.app.core.common.di.commonModule
import com.timemeasurer.app.core.data.di.dataModule
import com.timemeasurer.app.core.datastore.di.dataStoreModule
import com.timemeasurer.app.core.domain.di.domainModule
import com.timemeasurer.app.core.domain.di.servicesModule
import com.timemeasurer.app.core.domain.services.BackgroundServiceManager
import com.timemeasurer.app.core.model.AppConfigModel
import com.timemeasurer.app.core.model.services.StopwatchServiceModel
import com.timemeasurer.app.core.model.services.TimerServiceModel
import com.timemeasurer.app.core.remote_services.RemoteServicesInitializer
import com.timemeasurer.app.core.remote_services.di.remoteServicesModule
import com.timemeasurer.app.di.platformModule
import org.kodein.di.DI
import org.kodein.di.bind
import org.kodein.di.direct
import org.kodein.di.singleton

object PlatformProvider {

    fun init(configuration: AppConfigModel) {
        val providerModule = DI.Module(
            name = "platform_provider",
            init = {
                bind<AppConfigModel>() with singleton { configuration }
            }
        )

        Inject.createDependencies(
            DI {
                importAll(
                    providerModule,
                    commonModule,
                    dataStoreModule,
                    dataModule,
                    domainModule,
                    servicesModule,
                    remoteServicesModule,
                    platformModule()
                )
            }.direct
        )

        Inject.instance<RemoteServicesInitializer>().initialize()
        Inject.instance<BackgroundServiceManager<TimerServiceModel>>()
        Inject.instance<BackgroundServiceManager<StopwatchServiceModel>>()
    }
}