package com.timemeasurer.app.core.datastore.di

import com.russhwolf.settings.Settings
import com.timemeasurer.app.core.common.di.DI_TAG_DISPATCHER_IO
import com.timemeasurer.app.core.datastore.settings.AppSettings
import com.timemeasurer.app.core.datastore.settings.AppSettingsImpl
import com.timemeasurer.app.core.datastore.themes.ThemesSource
import com.timemeasurer.app.core.datastore.themes.ThemesSourceImpl
import org.kodein.di.DI
import org.kodein.di.bind
import org.kodein.di.instance
import org.kodein.di.singleton

const val DI_MODULE_DATA_STORE = "dataStoreModule"

val dataStoreModule = DI.Module(DI_MODULE_DATA_STORE) {
    bind<Settings>() with singleton { Settings() }
    bind<AppSettings>() with singleton { AppSettingsImpl(instance(), instance(tag = DI_TAG_DISPATCHER_IO)) }
    bind<ThemesSource>() with singleton { ThemesSourceImpl(instance(), instance(tag = DI_TAG_DISPATCHER_IO)) }
}