private val DataColumnMinWidth = 48.dp
private val DataColumnCount = 4
private val DividerThickness = 1.dp
private val TableCellPadding = 8.dp
private val TableHorizontalPadding = 16.dp

@Composable
fun TimerStatisticsCard(
    item: TimerStatisticsItem,
    modifier: Modifier = Modifier
) {
    val dividerColor = MaterialTheme.colorScheme.outlineVariant
    val textMeasurer = rememberTextMeasurer()
    val density = LocalDensity.current

    val sessionLabel = stringResource(Res.string.timers_statistics_session)
    val breakLabel = stringResource(Res.string.timers_statistics_break)
    val ratioLabel = stringResource(Res.string.timers_statistics_ratio)
    val todayHeader = stringResource(Res.string.timers_statistics_today)
    val weekHeader = stringResource(Res.string.timers_statistics_week)
    val monthHeader = stringResource(Res.string.timers_statistics_month)
    val totalHeader = stringResource(Res.string.timers_statistics_total)

    val labelStyle = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.Bold)
    val headerStyle = MaterialTheme.typography.labelLarge.copy(fontWeight = FontWeight.Bold)
    val cellStyle = MaterialTheme.typography.bodyMedium

    val labelColumnWidth = remember(sessionLabel, breakLabel, ratioLabel) {
        val maxLabelWidthPx = listOf(sessionLabel, breakLabel, ratioLabel)
            .maxOf { textMeasurer.measure(it, labelStyle).size.width }
        with(density) { maxLabelWidthPx.toDp() } + TableCellPadding * 2
    }

    val dataColumnMinWidth = remember(item, todayHeader, weekHeader, monthHeader, totalHeader) {
        val dataTexts = listOf(
            todayHeader,
            weekHeader,
            monthHeader,
            totalHeader,
            item.today.sessionTime,
            item.week.sessionTime,
            item.month.sessionTime,
            item.total.sessionTime,
            item.today.breakTime,
            item.week.breakTime,
            item.month.breakTime,
            item.total.breakTime,
            item.today.periodRatio.formatToDecimals(decimals = 2),
            item.week.periodRatio.formatToDecimals(decimals = 2),
            item.month.periodRatio.formatToDecimals(decimals = 2),
            item.total.periodRatio.formatToDecimals(decimals = 2),
        )
        val maxDataWidthPx = dataTexts.maxOf { text ->
            maxOf(
                textMeasurer.measure(text, headerStyle).size.width,
                textMeasurer.measure(text, cellStyle).size.width,
            )
        }
        val contentWidth = with(density) { maxDataWidthPx.toDp() } + TableCellPadding * 2
        maxOf(contentWidth, DataColumnMinWidth)
    }

    OutlinedCard(
        modifier = modifier.fillMaxWidth(),
        border = BorderStroke(1.dp, dividerColor),
        colors = CardDefaults.outlinedCardColors(
            containerColor = MaterialTheme.colorScheme.surface.copy(alpha = 0.1f)
        )
    ) {
        BoxWithConstraints(modifier = Modifier.fillMaxWidth()) {
            val totalDividerWidth = DividerThickness * DataColumnCount
            val stretchableTableWidth = (
                maxWidth - TableHorizontalPadding * 2 - labelColumnWidth - totalDividerWidth
                ).coerceAtLeast(0.dp)
            val dataColumnWidth = maxOf(dataColumnMinWidth, stretchableTableWidth / DataColumnCount)
            val tableWidth = labelColumnWidth + dataColumnWidth * DataColumnCount + totalDividerWidth

            Column(modifier = Modifier.fillMaxWidth()) {

                Spacer(modifier = Modifier.height(24.dp))

                Text(
                    text = item.timerName,
                    style = MaterialTheme.typography.titleMedium,
                    color = MaterialTheme.colorScheme.primary,
                    modifier = Modifier.padding(horizontal = TableHorizontalPadding)
                )

                Spacer(modifier = Modifier.height(16.dp))

                Row(
                    modifier = Modifier.horizontalScroll(rememberScrollState())
                        .padding(horizontal = TableHorizontalPadding)
                ) {
                    Column {
                        Row(modifier = Modifier.height(IntrinsicSize.Min)) {
                            Spacer(modifier = Modifier.width(labelColumnWidth))
                            TableVerticalDivider()
                            TableHeaderCell(
                                text = todayHeader,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                            TableVerticalDivider()
                            TableHeaderCell(
                                text = weekHeader,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                            TableVerticalDivider()
                            TableHeaderCell(
                                text = monthHeader,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                            TableVerticalDivider()
                            TableHeaderCell(
                                text = totalHeader,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                        }
                        Box(
                            modifier = Modifier.width(tableWidth)
                                .height(DividerThickness)
                                .background(dividerColor)
                        )
                        Row(modifier = Modifier.height(IntrinsicSize.Min)) {
                            TableRowLabel(
                                text = sessionLabel,
                                color = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.width(labelColumnWidth)
                            )
                            TableVerticalDivider()
                            TableCell(
                                text = item.today.sessionTime,
                                color = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                            TableVerticalDivider()
                            TableCell(
                                text = item.week.sessionTime,
                                color = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                            TableVerticalDivider()
                            TableCell(
                                text = item.month.sessionTime,
                                color = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                            TableVerticalDivider()
                            TableCell(
                                text = item.total.sessionTime,
                                color = MaterialTheme.colorScheme.primary,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                        }
                        Box(
                            modifier = Modifier.width(tableWidth)
                                .height(DividerThickness)
                                .background(dividerColor)
                        )
                        Row(modifier = Modifier.height(IntrinsicSize.Min)) {
                            TableRowLabel(
                                text = breakLabel,
                                color = MaterialTheme.colorScheme.secondary,
                                modifier = Modifier.width(labelColumnWidth)
                            )
                            TableVerticalDivider()
                            TableCell(
                                text = item.today.breakTime,
                                color = MaterialTheme.colorScheme.secondary,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                            TableVerticalDivider()
                            TableCell(
                                text = item.week.breakTime,
                                color = MaterialTheme.colorScheme.secondary,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                            TableVerticalDivider()
                            TableCell(
                                text = item.month.breakTime,
                                color = MaterialTheme.colorScheme.secondary,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                            TableVerticalDivider()
                            TableCell(
                                text = item.total.breakTime,
                                color = MaterialTheme.colorScheme.secondary,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                        }
                        Box(
                            modifier = Modifier.width(tableWidth)
                                .height(DividerThickness)
                                .background(dividerColor)
                        )
                        Row(modifier = Modifier.height(IntrinsicSize.Min)) {
                            val ratioColor = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.7f)
                            TableRowLabel(
                                text = ratioLabel,
                                color = ratioColor,
                                modifier = Modifier.width(labelColumnWidth)
                            )
                            TableVerticalDivider()
                            TableCell(
                                text = item.today.periodRatio.formatToDecimals(decimals = 2),
                                color = ratioColor,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                            TableVerticalDivider()
                            TableCell(
                                text = item.week.periodRatio.formatToDecimals(decimals = 2),
                                color = ratioColor,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                            TableVerticalDivider()
                            TableCell(
                                text = item.month.periodRatio.formatToDecimals(decimals = 2),
                                color = ratioColor,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                            TableVerticalDivider()
                            TableCell(
                                text = item.total.periodRatio.formatToDecimals(decimals = 2),
                                color = ratioColor,
                                modifier = Modifier.width(dataColumnWidth)
                            )
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                TimerCircleProgressWidget(
                    data = item.toCircleProgressModels(),
                    settings = CircleProgressSettingsModel(),
                    modifier = Modifier
                        .align(Alignment.CenterHorizontally)
                        .size(240.dp)
                        .padding(bottom = 16.dp)
                )
            }
        }
    }
}

@Composable
private fun TimerStatisticsItem.toCircleProgressModels(): List<CircleProgressModel> {
    val sessionColor = MaterialTheme.colorScheme.primary
    val breakColor = MaterialTheme.colorScheme.inversePrimary

    fun buildSegments(period: TimerPeriodUiModel): List<Segment> {
        return buildList {
            val fraction = period.sessionFraction
            add(Segment(0f, fraction, sessionColor))
            add(Segment(fraction, 1f, breakColor))
        }
    }

    return listOf(
        CircleProgressModel(
            backgroundColor = MaterialTheme.colorScheme.surface,
            segments = buildSegments(today),
            arcText = stringResource(Res.string.timers_statistics_today),
            arcTextColor = Color.White,
            textAlpha = 0.8f
        ),
        CircleProgressModel(
            backgroundColor = MaterialTheme.colorScheme.surface,
            segments = buildSegments(week),
            arcText = stringResource(Res.string.timers_statistics_week),
            arcTextColor = Color.White,
            textAlpha = 0.8f
        ),
        CircleProgressModel(
            backgroundColor = MaterialTheme.colorScheme.surface,
            segments = buildSegments(month),
            arcText = stringResource(Res.string.timers_statistics_month),
            arcTextColor = Color.White,
            textAlpha = 0.8f
        ),
        CircleProgressModel(
            backgroundColor = MaterialTheme.colorScheme.surface,
            segments = buildSegments(total),
            arcText = stringResource(Res.string.timers_statistics_total),
            arcTextColor = Color.White,
            textAlpha = 0.8f
        )
    )
}

@Composable
private fun TableRowLabel(
    text: String,
    color: Color,
    modifier: Modifier = Modifier,
) {
    Text(
        text = text,
        style = MaterialTheme.typography.labelMedium,
        fontWeight = FontWeight.Bold,
        color = color,
        textAlign = TextAlign.End,
        modifier = modifier.padding(8.dp)
    )
}

