package com.timemeasurer.app

import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.wrapContentHeight
import androidx.compose.material3.ExperimentalMaterial3Api
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import com.timemeasurer.app.core.navigation.AppRoute
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.settings
import com.timemeasurer.app.core.resources.stopwatches
import com.timemeasurer.app.core.resources.stopwatches_statistics
import com.timemeasurer.app.core.resources.timer_settings
import com.timemeasurer.app.core.resources.timers
import com.timemeasurer.app.core.resources.timers_statistics
import com.timemeasurer.app.core.ui.components.AppTopBar
import com.timemeasurer.app.core.ui.icon.ChartIconSet
import com.timemeasurer.app.core.ui.icon.CommonIconSet
import com.timemeasurer.app.core.ui.models.TopBarState
import com.timemeasurer.app.core.ui.viewmodels.TopBarNavigationState
import com.timemeasurer.app.core.ui.viewmodels.TopBarNavigationViewModel
import org.jetbrains.compose.resources.stringResource
import org.kodein.di.compose.viewmodel.rememberViewModel

@Composable
internal fun rememberTopBarState(appState: AppState): TopBarState {
    val viewModel: TopBarNavigationViewModel by rememberViewModel<TopBarNavigationViewModel>()
    val route = appState.currentRoute
    val isExpanded = appState.isExpanded

    return when (route) {
        is AppRoute.Timers -> timersTopBarState(viewModel, appState)
        is AppRoute.Stopwatches -> stopwatchesTopBarState(viewModel, appState)
        is AppRoute.Settings -> settingsTopBarState()
        is AppRoute.TimerSettings -> timerSettingsTopBarState(appState)
        is AppRoute.TimersStatistics -> if (isExpanded) {
            timersTopBarState(viewModel, appState)
        } else {
            timersStatisticsTopBarState(appState)
        }
        is AppRoute.StopwatchesStatistics -> if (isExpanded) {
            stopwatchesTopBarState(viewModel, appState)
        } else {
            stopwatchesStatisticsTopBarState(appState)
        }
        is AppRoute.TimerSettingsDialog,
        is AppRoute.Themes,
        is AppRoute.Splash,
        null -> TopBarState(isVisible = false)
    }
}

@Composable
private fun timersTopBarState(
    viewModel: TopBarNavigationViewModel,
    appState: AppState,
): TopBarState = TopBarState(
    title = stringResource(Res.string.timers),
    isVisible = true,
    secondActionIcon = if (!appState.isExpanded) ChartIconSet.statistics.icon else null,
    secondActionIconContentDescription = if (!appState.isExpanded) stringResource(Res.string.timers_statistics) else null,
    onSecondActionClick = if (!appState.isExpanded) {
        { viewModel.emit("timers", TopBarNavigationState.Statistics) }
    } else null,
)

@Composable
private fun stopwatchesTopBarState(
    viewModel: TopBarNavigationViewModel,
    appState: AppState,
): TopBarState = TopBarState(
    title = stringResource(Res.string.stopwatches),
    isVisible = true,
    secondActionIcon = if (!appState.isExpanded) ChartIconSet.statistics.icon else null,
    secondActionIconContentDescription = if (!appState.isExpanded) stringResource(Res.string.stopwatches_statistics) else null,
    onSecondActionClick = if (!appState.isExpanded) {
        { viewModel.emit("stopwatches", TopBarNavigationState.Statistics) }
    } else null,
)

@Composable
private fun settingsTopBarState(): TopBarState = TopBarState(
    title = stringResource(Res.string.settings),
    isVisible = true,
)

@Composable
private fun timerSettingsTopBarState(appState: AppState): TopBarState = TopBarState(
    title = stringResource(Res.string.timer_settings),
    isVisible = true,
    navigationIcon = CommonIconSet.arrowBack.icon,
    onNavigationClick = { appState.goBack() },
)

@Composable
private fun timersStatisticsTopBarState(appState: AppState): TopBarState = TopBarState(
    title = stringResource(Res.string.timers_statistics),
    isVisible = !appState.isExpanded,
    navigationIcon = CommonIconSet.arrowBack.icon,
    onNavigationClick = { appState.goBack() },
)

@Composable
private fun stopwatchesStatisticsTopBarState(appState: AppState): TopBarState = TopBarState(
    title = stringResource(Res.string.stopwatches_statistics),
    isVisible = !appState.isExpanded,
    navigationIcon = CommonIconSet.arrowBack.icon,
    onNavigationClick = { appState.goBack() },
)

@OptIn(ExperimentalMaterial3Api::class)
@Composable
internal fun GlobalTopAppBar(appState: AppState) {
    val state = rememberTopBarState(appState)

    if (state.isVisible) {
        AppTopBar(
            title = state.title.takeIf { it.isNotEmpty() },
            navigationIcon = state.navigationIcon,
            navigationIconContentDescription = state.navigationIconContentDescription,
            actionIcon = state.actionIcon,
            actionIconContentDescription = state.actionIconContentDescription,
            secondActionIcon = state.secondActionIcon,
            secondActionIconContentDescription = state.secondActionIconContentDescription,
            onNavigationClick = state.onNavigationClick ?: {},
            onActionClick = state.onActionClick ?: {},
            onSecondActionClick = state.onSecondActionClick ?: {},
            modifier = Modifier.fillMaxWidth().wrapContentHeight(),
        )
    }
}
