package com.timemeasurer.app.core.data.model

import com.timemeasurer.app.core.model.converters.dateTimeConverter
import com.timemeasurer.app.core.model.converters.timerTypeConverter
import com.timemeasurer.app.core.model.timer.TimerSessionModel
import data.TimersSessionsEntity
import kotlin.time.ExperimentalTime

@OptIn(ExperimentalTime::class)
fun TimersSessionsEntity.toTimerSessionModel() = TimerSessionModel(
    id = id,
    timerId = timerId,
    session = session,
    type = timerTypeConverter(type),
    startedAt = dateTimeConverter(startedAt),
    endAt = dateTimeConverter(endAt),
)

fun List<TimersSessionsEntity>.entitiesToTimersSessionsModels() = map { it.toTimerSessionModel() }

@OptIn(ExperimentalTime::class)
fun TimerSessionModel.toTimersSessionsEntity() = TimersSessionsEntity(
    id = id,
    timerId = timerId,
    session = session,
    type = timerTypeConverter(type),
    startedAt = dateTimeConverter(startedAt),
    endAt = dateTimeConverter(endAt),
)

fun List<TimerSessionModel>.modelsToTimersSessionsEntities() = map { it.toTimersSessionsEntity() }