package com.timemeasurer.app.core.model.timer

import com.timemeasurer.app.core.model.icon.DefaultIconIds
import kotlinx.serialization.Serializable
import kotlin.time.ExperimentalTime

const val SESSION_DURATION = 30 * 60 * 1000L        // 30 minutes
const val SHORT_BREAK_DURATION = 5 * 60 * 1000L    // 5 minutes
const val LONG_BREAK_DURATION = 15 * 60 * 1000L      // 15 minutes
const val LONG_BREAK_AFTER_SESSIONS = 2
const val AUTOSAVE_SESSION_SEC = 5

@OptIn(ExperimentalTime::class)
@Serializable
data class TimerSettingsModel(
    val sessionDuration: Long = SESSION_DURATION,
    val shortBreakDuration: Long = SHORT_BREAK_DURATION,
    val longBreakDuration: Long = LONG_BREAK_DURATION,
    val longBreakAfterSession: Int = LONG_BREAK_AFTER_SESSIONS,
    val autoSaveSession: Int = AUTOSAVE_SESSION_SEC,
    val isTimerStartAuto: Boolean = true,
    val isSessionStartAuto: Boolean = true,
    val isBreakStartAuto: Boolean = true,
    val isLongBreakEnabled: Boolean = true,
    val isShortBreakEnabled: Boolean = true,
    val iconId: String = DefaultIconIds.TIMER,
    val isCountdownSoundEnabled: Boolean = true,
    val countdownSoundId: String = "beep_square",
    val isSessionEndSoundEnabled: Boolean = true,
    val sessionEndSoundId: String = "bell_bright",
    val isRestEndSoundEnabled: Boolean = true,
    val restEndSoundId: String = "gong_low",
    val sessionDurationUnit: TimerTimeType = TimerTimeType.MINUTES,
    val shortBreakDurationUnit: TimerTimeType = TimerTimeType.MINUTES,
    val longBreakDurationUnit: TimerTimeType = TimerTimeType.MINUTES,
    val progressType: TimerProgressType = TimerProgressType.Circular,
    val sessionDurationErrorMin: Int? = null,
    val sessionDurationErrorMax: Int? = null,
    val shortBreakDurationErrorMin: Int? = null,
    val shortBreakDurationErrorMax: Int? = null,
    val longBreakDurationErrorMin: Int? = null,
    val longBreakDurationErrorMax: Int? = null,
    val longBreakAfterErrorMin: Int? = null,
    val longBreakAfterErrorMax: Int? = null,
)