package com.timemeasurer.app.core.domain.di

import com.timemeasurer.app.core.domain.services.BackgroundServiceManager
import com.timemeasurer.app.core.domain.services.NoOpStopwatchBackgroundServiceManager
import com.timemeasurer.app.core.domain.services.NoOpTimerBackgroundServiceManager
import com.timemeasurer.app.core.model.services.StopwatchServiceModel
import com.timemeasurer.app.core.model.services.TimerServiceModel
import org.kodein.di.DI
import org.kodein.di.bind
import org.kodein.di.singleton

actual fun platformBackgroundServiceModule(): DI.Module = DI.Module("jsBackgroundServiceModule") {
    bind<BackgroundServiceManager<TimerServiceModel>>() with singleton { NoOpTimerBackgroundServiceManager() }
    bind<BackgroundServiceManager<StopwatchServiceModel>>() with singleton { NoOpStopwatchBackgroundServiceManager() }
}
