package com.timemeasurer.app.core.domain.stopwatch

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.data.repositories.stopwatch_laps.StopwatchLapsRepository
import com.timemeasurer.app.core.model.stopwatch.StopwatchLapModel
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.withContext

class UpdateAndCreateLapUseCase(
    private val stopwatchLapsRepository: StopwatchLapsRepository,
    private val dispatcher: CoroutineDispatcher,
) {
    suspend operator fun invoke(stopwatchId: Long, lapId: Long, time: Long = 0L, ): Result<StopwatchLapModel> =
        withContext(dispatcher) {
            stopwatchLapsRepository.updateAndCreateLap(
                stopwatchId = stopwatchId,
                lapId = lapId,
                time = time,
            )
        }
}
