package com.timemeasurer.app.core.domain.common

class ValidateNameUseCase {
    companion object {
        const val MAX_LENGTH = 20
    }

    fun validate(name: String): ValidateNameResult {
        val trimmed = name.trim()
        return when {
            trimmed.isEmpty() -> ValidateNameResult(
                isValid = false,
                error = NameValidationError.EMPTY
            )
            else -> ValidateNameResult(isValid = true, error = null)
        }
    }
}
