private val DataColumnMinWidth = 48.dp
private val DividerThickness = 1.dp
private val TableCellPadding = 8.dp

@Composable
fun StopwatchStatisticsCard(
    item: StopwatchStatisticsItem,
    onEvent: (StopwatchesStatisticsEvents) -> Unit,
    modifier: Modifier = Modifier,
) {
    val dividerColor = MaterialTheme.colorScheme.outlineVariant
    val textMeasurer = rememberTextMeasurer()
    val density = LocalDensity.current

    val isExpanded = windowSizeClass.widthSizeClass == WindowWidthSizeClass.Expanded

    val totalHeader = stringResource(Res.string.stopwatches_statistics_total_time)
    val lapsCountHeader = stringResource(Res.string.stopwatches_statistics_laps_count)
    val maxHeader = stringResource(Res.string.stopwatches_statistics_max_time)
    val minHeader = stringResource(Res.string.stopwatches_statistics_min_time)
    val avgHeader = stringResource(Res.string.stopwatches_statistics_avg_time)
    val maxLapLabel = stringResource(Res.string.stopwatches_statistics_lap_label, item.maxLapNumber)
    val minLapLabel = stringResource(Res.string.stopwatches_statistics_lap_label, item.minLapNumber)

    val headerStyle = MaterialTheme.typography.labelLarge.copy(fontWeight = FontWeight.Bold)
    val cellStyle = MaterialTheme.typography.bodyMedium
    val lapLabelStyle = MaterialTheme.typography.labelSmall

    val dataColumnWidth = remember(
        item, totalHeader, lapsCountHeader, maxHeader, minHeader, avgHeader,
    ) {
        val texts = listOf(
            totalHeader,
            lapsCountHeader,
            maxHeader,
            minHeader,
            avgHeader,
            item.totalTime,
            item.lapCount,
            item.maxLapTime,
            item.minLapTime,
            item.avgTime,
            maxLapLabel,
            minLapLabel,
        )
        val maxWidthPx = texts.maxOf { text ->
            maxOf(
                textMeasurer.measure(text, headerStyle).size.width,
                textMeasurer.measure(text, cellStyle).size.width,
                textMeasurer.measure(text, lapLabelStyle).size.width,
            )
        }
        val contentWidth = with(density) { maxWidthPx.toDp() } + TableCellPadding * 2
        maxOf(contentWidth, DataColumnMinWidth)
    }

    val tableWidth = dataColumnWidth * 5 + DividerThickness * 4

    OutlinedCard(
        modifier = modifier.then(
            if (isExpanded) Modifier else Modifier.fillMaxWidth()
        ),
        border = BorderStroke(1.dp, dividerColor),
        colors = CardDefaults.outlinedCardColors(
            containerColor = MaterialTheme.colorScheme.surface.copy(alpha = 0.1f)
        )
    ) {
        Column(modifier = Modifier) {

            Spacer(modifier = Modifier.height(24.dp))

            Text(
                text = item.stopwatchName,
                style = MaterialTheme.typography.titleMedium,
                color = MaterialTheme.colorScheme.primary,
                modifier = Modifier.padding(horizontal = 16.dp)
            )

            Spacer(modifier = Modifier.height(16.dp))

            Row(
                modifier = Modifier.horizontalScroll(rememberScrollState())
                    .padding(horizontal = 16.dp)
            ) {
                Column {
                    Row(modifier = Modifier.height(IntrinsicSize.Min)) {
                        TableHeaderCell(
                            text = totalHeader,
                            modifier = Modifier.width(dataColumnWidth)
                        )
                        TableVerticalDivider()
                        TableHeaderCell(
                            text = lapsCountHeader,
                            modifier = Modifier.width(dataColumnWidth)
                        )
                        TableVerticalDivider()
                        TableHeaderCell(
                            text = maxHeader,
                            modifier = Modifier.width(dataColumnWidth)
                        )
                        TableVerticalDivider()
                        TableHeaderCell(
                            text = minHeader,
                            modifier = Modifier.width(dataColumnWidth)
                        )
                        TableVerticalDivider()
                        TableHeaderCell(
                            text = avgHeader,
                            modifier = Modifier.width(dataColumnWidth)
                        )
                    }
                    Box(
                        modifier = Modifier.width(tableWidth)
                            .height(2.dp)
                            .background(dividerColor)
                    )
                    Row(modifier = Modifier.height(IntrinsicSize.Min)) {
                        TableCell(
                            text = item.totalTime,
                            modifier = Modifier.width(dataColumnWidth)
                        )
                        TableVerticalDivider()
                        TableCell(
                            text = item.lapCount,
                            modifier = Modifier.width(dataColumnWidth)
                        )
                        TableVerticalDivider()
                        MaxMinValueCell(
                            lapLabel = maxLapLabel,
                            value = item.maxLapTime,
                            modifier = Modifier.width(dataColumnWidth)
                        )
                        TableVerticalDivider()
                        MaxMinValueCell(
                            lapLabel = minLapLabel,
                            value = item.minLapTime,
                            modifier = Modifier.width(dataColumnWidth)
                        )
                        TableVerticalDivider()
                        TableCell(
                            text = item.avgTime,
                            modifier = Modifier.width(dataColumnWidth)
                        )
                    }
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            if (item.laps.size > 1) {
                LazyRow(
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                    contentPadding = androidx.compose.foundation.layout.PaddingValues(horizontal = 16.dp)
                ) {
                    items(item.laps) { lap ->
                        OutlinedCard(
                            border = BorderStroke(1.dp, dividerColor),
                            colors = CardDefaults.outlinedCardColors(
                                containerColor = MaterialTheme.colorScheme.surface.copy(alpha = 0.2f)
                            )
                        ) {
                            Column(
                                modifier = Modifier.padding(8.dp),
                                horizontalAlignment = Alignment.CenterHorizontally
                            ) {
                                Text(
                                    text = stringResource(Res.string.stopwatches_statistics_lap_card_label, lap.lapNumber),
                                    style = MaterialTheme.typography.labelMedium
                                )
                                Text(
                                    text = lap.duration,
                                    style = MaterialTheme.typography.titleSmall,
                                    color = MaterialTheme.colorScheme.onSurface
                                )
                                Text(
                                    text = lap.totalTimeFromStart,
                                    style = MaterialTheme.typography.bodySmall,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                        }
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                val primaryColor = MaterialTheme.colorScheme.primary
                val xAxisLabel = stringResource(Res.string.stopwatches_statistics_graph_x_axis)
                val yAxisLabel = stringResource(Res.string.stopwatches_statistics_graph_y_axis)
                val graphSettings = remember(item.graphType, xAxisLabel, yAxisLabel, primaryColor) {
                    GraphSettingsModel(
                        graphType = item.graphType.toGraphType,
                        graphColor = primaryColor,
                        xAxisLabel = xAxisLabel,
                        yAxisLabel = yAxisLabel,
                        showYAxisLabels = false
                    )
                }

                val onGraphTypeChange = remember(item.stopwatchId, onEvent) {
                    mutableStateOf<((GraphType) -> Unit)?>(
                        { type -> onEvent(StopwatchesStatisticsEvents.UpdateGraphType(item.stopwatchId, type.toStopwatchGraphType)) }
                    )
                }

                GraphWidget(
                    data = item.graphModels,
                    graphSettings = graphSettings,
                    onGraphTypeChange = onGraphTypeChange,
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(200.dp)
                        .padding(horizontal = 16.dp, vertical = 8.dp)
                )

                Spacer(modifier = Modifier.height(24.dp))
            }
        }
    }
}

@Composable
private fun MaxMinValueCell(
    lapLabel: String,
    value: String,
    modifier: Modifier = Modifier,
) {
    Column(
        modifier = modifier
            .fillMaxHeight()
            .padding(8.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Bottom
    ) {
        Text(
            text = lapLabel,
            style = MaterialTheme.typography.labelSmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            textAlign = TextAlign.Center,
        )
        Spacer(modifier = Modifier.height(2.dp))
        Text(
            text = value,
            style = MaterialTheme.typography.bodyMedium,
            color = MaterialTheme.colorScheme.onSurface,
            textAlign = TextAlign.Center,
        )
    }
}

