@Composable
fun SettingsScreen(
    showThemeDialog: () -> Unit,
    showTimerSettings: () -> Unit,
    viewModel: SettingsViewModel = viewModel { SettingsViewModel() },
) {
    val settingsUiState by viewModel.state.collectAsStateWithLifecycle()
    val settingsAction by viewModel.action.collectAsStateWithLifecycle(initialValue = SettingsActions.None)

    val mainUrl = stringResource(Res.string.project_url)

    var settingsData: SettingsData? = null
    var themeData: ThemeData? = null
    var isSingleActiveTimer: Boolean = true
    var isKeepScreenOn: Boolean = false
    var isVibrationEnabled: Boolean = true

    when(val state = settingsUiState) {
        UiState.Loading -> {}
        UiState.Empty -> {}
        is UiState.Error -> {}
        is UiState.Success -> {
            settingsData = state.item.settingsData
            themeData = state.item.themeData
            isSingleActiveTimer = state.item.isSingleActiveTimer
            isKeepScreenOn = state.item.isKeepScreenOn
            isVibrationEnabled = state.item.isVibrationEnabled
        }
    }

    Column(modifier = Modifier.fillMaxSize().verticalScroll(rememberScrollState())) {
        SettingsColumnBlockWidget(
            headerRes = Res.string.ui,
            headerPadding = PaddingValues(horizontal = 24.dp),
            contentPadding = PaddingValues(top = 16.dp, start = 0.dp, end = 0.dp, bottom = 0.dp)
        ) {
            TwoLinesSwitchButtonWidget(
                titleRes = Res.string.theme,
                subtitleRes = Res.string.change_theme,
                modifier = Modifier.padding(horizontal = 40.dp, vertical = 8.dp),
                onClick = showThemeDialog
            )

            themeData?.let { data ->
                Text(
                    text = stringResource(Res.string.dark_mode_preference),
                    style = MaterialTheme.typography.bodyLarge,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.padding(horizontal = 40.dp, vertical = 8.dp),
                )
                Column(Modifier.selectableGroup()) {
                    RadioButtonRow(
                        text = stringResource(Res.string.system_default),
                        selected = data.darkThemeConfig == DarkThemeConfig.FOLLOW_SYSTEM,
                        onClick = { viewModel.setEvent(SettingsEvents.UpdateDarkThemeConfig(DarkThemeConfig.FOLLOW_SYSTEM)) },
                        modifier = Modifier.padding(horizontal = 40.dp),
                    )
                    RadioButtonRow(
                        text = stringResource(Res.string.light),
                        selected = data.darkThemeConfig == DarkThemeConfig.LIGHT,
                        onClick = { viewModel.setEvent(SettingsEvents.UpdateDarkThemeConfig(DarkThemeConfig.LIGHT)) },
                        modifier = Modifier.padding(horizontal = 40.dp),
                    )
                    RadioButtonRow(
                        text = stringResource(Res.string.dark),
                        selected = data.darkThemeConfig == DarkThemeConfig.DARK,
                        onClick = { viewModel.setEvent(SettingsEvents.UpdateDarkThemeConfig(DarkThemeConfig.DARK)) },
                        modifier = Modifier.padding(horizontal = 40.dp),
                    )
                }
            }
        }

        SettingsColumnBlockWidget(
            headerRes = Res.string.timers,
            headerPadding = PaddingValues(horizontal = 24.dp),
            contentPadding = PaddingValues(top = 16.dp, start = 0.dp, end = 0.dp, bottom = 0.dp)
        ) {
            TwoLinesSwitchButtonWidget(
                titleRes = Res.string.preferences,
                subtitleRes = Res.string.timer_settings_global_subtitle,
                modifier = Modifier.padding(horizontal = 40.dp, vertical = 8.dp),
                onClick = showTimerSettings
            )

            TwoLinesSwitchButtonWidget(
                titleRes = Res.string.settings_single_active_timer,
                subtitleRes = Res.string.settings_single_active_timer_subtitle,
                checked = isSingleActiveTimer,
                onCheckedChange = { viewModel.setEvent(SettingsEvents.UpdateSingleActiveTimer(it)) },
                modifier = Modifier.padding(start = 40.dp, end = 24.dp, top = 8.dp, bottom = 8.dp),
            )

            if (isVibrationSupported) {
                TwoLinesSwitchButtonWidget(
                    titleRes = Res.string.settings_vibration,
                    subtitleRes = Res.string.settings_vibration_subtitle,
                    checked = isVibrationEnabled,
                    onCheckedChange = { viewModel.setEvent(SettingsEvents.UpdateVibration(it)) },
                    modifier = Modifier.padding(start = 40.dp, end = 24.dp, top = 8.dp, bottom = 8.dp),
                )
            }
        }

        if (isKeepScreenOnSupported || isBatteryOptimizationSupported || isNotificationSettingsSupported) {
            SettingsColumnBlockWidget(
                headerRes = Res.string.settings_common,
                headerPadding = PaddingValues(horizontal = 24.dp),
                contentPadding = PaddingValues(top = 16.dp, start = 0.dp, end = 0.dp, bottom = 0.dp)
            ) {
                if (isKeepScreenOnSupported) {
                    TwoLinesSwitchButtonWidget(
                        titleRes = Res.string.settings_keep_screen_on,
                        subtitleRes = Res.string.settings_keep_screen_on_subtitle,
                        checked = isKeepScreenOn,
                        onCheckedChange = { viewModel.setEvent(SettingsEvents.UpdateKeepScreenOn(it)) },
                        modifier = Modifier.padding(start = 40.dp, end = 24.dp, top = 8.dp, bottom = 8.dp),
                    )
                }

                if (isBatteryOptimizationSupported) {
                    val openBatteryOptimization = rememberBatteryOptimizationOpener()
                    TwoLinesSwitchButtonWidget(
                        titleRes = Res.string.settings_battery_optimization,
                        subtitleRes = Res.string.settings_battery_optimization_subtitle,
                        modifier = Modifier.padding(start = 40.dp, end = 24.dp, top = 8.dp, bottom = 8.dp),
                        onClick = openBatteryOptimization,
                    )
                }

                if (isNotificationSettingsSupported) {
                    val openNotificationSettings = rememberNotificationSettingsOpener()
                    TwoLinesSwitchButtonWidget(
                        titleRes = Res.string.settings_notifications,
                        subtitleRes = Res.string.settings_notifications_subtitle,
                        modifier = Modifier.padding(start = 40.dp, end = 24.dp, top = 8.dp, bottom = 8.dp),
                        onClick = openNotificationSettings,
                    )
                }
            }
        }

        Spacer(modifier = Modifier
            .fillMaxHeight()
            .padding(top = 8.dp)
            .weight(1.0f))

        Spacer(Modifier.height(24.dp))

        Text(
            text = stringResource(Res.string.version, settingsData?.version ?: "-"),
            fontSize = 12.sp,
            lineHeight = 12.sp,
            fontWeight = FontWeight.Normal,
            color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f),
            modifier = Modifier
                .padding(horizontal = 0.dp)
                .align(Alignment.CenterHorizontally)
        )

        Spacer(modifier = Modifier.height(8.dp))
    }

}
