package com.timemeasurer.app.feature.timers.widgets

import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.height
import androidx.compose.foundation.layout.size
import androidx.compose.material3.CircularProgressIndicator
import androidx.compose.material3.LinearProgressIndicator
import androidx.compose.material3.MaterialTheme
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import com.timemeasurer.app.core.model.timer.TimerProgressType

@Composable
fun TimerProgressIndicator(
    progress: Int,
    total: Int,
    progressType: TimerProgressType,
    modifier: Modifier = Modifier,
    strokeWidth: Dp = 4.dp
) {
    when (progressType) {
        TimerProgressType.Linear -> LinearProgressIndicator(
            progress = { progress.toFloat() / total.toFloat() },
            modifier = Modifier.fillMaxWidth().height(strokeWidth).then(modifier),
            color = MaterialTheme.colorScheme.primary,
            strokeCap = StrokeCap.Round,
            gapSize = (-2).dp,
            drawStopIndicator = {},
        )
        TimerProgressType.Circular -> CircularProgressIndicator(
            progress = { progress.toFloat() / total.toFloat() },
            modifier = modifier,
            color = MaterialTheme.colorScheme.primary,
            strokeCap = StrokeCap.Round,
            strokeWidth = strokeWidth,
            gapSize = (-2).dp
        )
    }
}

@Preview
@Composable
private fun TimerProgressIndicatorCircularPreview() {
    TimerProgressIndicator(
        progress = 50,
        total = 100,
        progressType = TimerProgressType.Circular,
        modifier = Modifier.size(320.dp),
    )
}
