package com.timemeasurer.app.core.domain.timer

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.data.repositories.timer_session.TimerSessionRepository
import com.timemeasurer.app.core.model.timer.TimerSessionModel
import com.timemeasurer.app.core.model.timer.TimerTotalSessionsModel
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map

class GetSessionByMaxValueUseCase(
    private val timerSessionRepository: TimerSessionRepository,
    private val dispatcher: CoroutineDispatcher,
) {

    suspend operator fun invoke(timerId: Long): Result<TimerTotalSessionsModel?> =
        timerSessionRepository.getSessionByMaxValue(timerId)
            .map { result ->
                when(result) {
                    is Result.Loading -> result
                    is Result.Error -> result
                    is Result.Success<List<TimerSessionModel>> -> {
                        var lastSession: TimerSessionModel? = null
                        var totalTime = 0L

                        result.data.forEach { item ->
                            totalTime += (item.endAt.toEpochMilliseconds() - item.startedAt.toEpochMilliseconds())
                            if ((lastSession?.startedAt?.toEpochMilliseconds() ?: 0L) < item.startedAt.toEpochMilliseconds()) {
                                lastSession = item
                            }
                        }

                        Result.Success(lastSession?.let {
                            TimerTotalSessionsModel(
                                timeSec = totalTime / 1000,
                                session = it
                            )
                        })
                   }
               }
            }.first {
                it !is Result.Loading
            }

}
