package com.timemeasurer.app.core.domain.timer

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.data.repositories.timer_session.TimerSessionRepository
import com.timemeasurer.app.core.model.timer.TimerSessionModel
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.flow.onEach
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

class GetSessionsPagesUseCase(
    private val timerSessionRepository: TimerSessionRepository,
    private val dispatcher: CoroutineDispatcher,
) {

    companion object Companion {
        const val SINCE_ID = 0L
        private const val LIMIT = 30L
    }

    private val mutex = Mutex()
    private var sinceId = SINCE_ID
    private var limit = LIMIT

    suspend operator fun invoke(timerId: Long, isNewSearch: Boolean = false): Flow<Result<List<TimerSessionModel>>> = mutex.withLock {
        if (isNewSearch) limit = LIMIT
        timerSessionRepository.getSessionsById(timerId = timerId, sinceId = SINCE_ID, count = limit)
            .onEach { new ->
                if (new is Result.Success) {
                    sinceId = new.data.lastOrNull()?.id ?: SINCE_ID
                    limit += LIMIT
                }
            }.flowOn(dispatcher)
    }

}
