@Composable
fun AppScreen() {
    val resourceEnvironment = rememberResourceEnvironment()
    LaunchedEffect(resourceEnvironment) {
        topLevelStrings.forEach { getString(resourceEnvironment, it) }
    }
    AppBackground {
        val appState = rememberAppState()
        val snackbarHostState = remember { SnackbarHostState() }

        CompositionLocalProvider(LocalSnackbarHost provides snackbarHostState) {
            Scaffold(
                containerColor = Color.Transparent,
                contentColor = MaterialTheme.colorScheme.onBackground,
                contentWindowInsets = WindowInsets.safeDrawing,
                snackbarHost = { SnackbarHost(snackbarHostState) },
                modifier = Modifier.fillMaxSize().imePadding(),
                topBar = {
                    if (!appState.isSplashVisible) {
                        GlobalTopAppBar(appState = appState)
                    }
                },
                bottomBar = {
                    if (appState.shouldShowBottomBar && !appState.isSplashVisible) {
                        AppBottomBar(
                            destinations = appState.topLevelDestinations.toImmutableList(),
                            onNavigateToDestination = appState::navigateToTopLevelDestination,
                            currentDestination = appState.currentTopLevelDestination,
                            modifier = Modifier.testTag("AppBottomBar"),
                        )
                    }
                },
            ) { innerPadding ->
                Row(
                    Modifier
                        .fillMaxSize()
                        .padding(innerPadding)
                        .consumeWindowInsets(innerPadding)
                        .windowInsetsPadding(
                            WindowInsets.safeDrawing.only(WindowInsetsSides.Horizontal),
                        ),
                ) {
                    if (appState.shouldShowNavRail && !appState.isSplashVisible) {
                        AppNavRail(
                            destinations = appState.topLevelDestinations.toImmutableSet(),
                            destinationsWithUnreadResources = emptySet(),
                            onNavigateToDestination = appState::navigateToTopLevelDestination,
                            currentDestination = appState.currentTopLevelDestination,
                            modifier = Modifier
                                .testTag("AppNavRail")
                                .safeDrawingPadding(),
                        )
                    }

                    AppNavHost(
                        appState = appState,
                        modifier = Modifier.fillMaxSize()
                    )
                }
            }
        }
    }
}

@Composable
private fun AppBottomBar(
    destinations: ImmutableList<TopLevelDestination>,
    onNavigateToDestination: (TopLevelDestination) -> Unit,
    currentDestination: TopLevelDestination?,
    modifier: Modifier = Modifier,
) {
    AppNavigationBar(modifier = modifier) {
        destinations.forEach { destination ->
            val selected = currentDestination == destination
            val label = stringResource(destination.iconText)
            AppNavigationBarItem(
                selected = selected,
                onClick = { onNavigateToDestination(destination) },
                icon = {
                    Icon(
                        imageVector = destination.unselectedIcon,
                        contentDescription = null,
                    )
                },
                selectedIcon = {
                    Icon(
                        imageVector = destination.selectedIcon,
                        contentDescription = null,
                    )
                },
                label = { Text(label) },
                modifier = modifier,
            )
        }
    }
}

@Composable
private fun AppNavRail(
    destinations: ImmutableSet<TopLevelDestination>,
    destinationsWithUnreadResources: Set<TopLevelDestination>,
    onNavigateToDestination: (TopLevelDestination) -> Unit,
    currentDestination: TopLevelDestination?,
    modifier: Modifier = Modifier,
) {
    AppNavigationRail(modifier = modifier) {
        destinations.forEach { destination ->
            val selected = currentDestination == destination
            val label = stringResource(destination.iconText)
            AppNavigationRailItem(
                selected = selected,
                onClick = { onNavigateToDestination(destination) },
                icon = {
                    Icon(
                        imageVector = destination.unselectedIcon,
                        contentDescription = null,
                    )
                },
                selectedIcon = {
                    Icon(
                        imageVector = destination.selectedIcon,
                        contentDescription = null,
                    )
                },
                label = { Text(label) },
                modifier = modifier,
            )
        }
    }
}

private val topLevelStrings = listOf(
    Res.string.timers,
    Res.string.stopwatches,
    Res.string.settings,
    Res.string.timer_settings,
    Res.string.timers_statistics,
    Res.string.stopwatches_statistics,
)
