package com.timemeasurer.app.feature.stopwatches.models

import com.timemeasurer.app.core.common.extensions.safeSubList
import com.timemeasurer.app.core.model.icon.DefaultIconIds
import com.timemeasurer.app.core.model.stopwatch.StopwatchLapModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchMetadataModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchTickModel
import kotlinx.collections.immutable.ImmutableList
import kotlinx.collections.immutable.toImmutableList

data class StopwatchUiDataModel(
    val stopwatchId: Long,
    val name: String,
    val iconId: String = DefaultIconIds.STOPWATCH,
    val isRunning: Boolean = false,
    val laps: ImmutableList<StopwatchLapModel> = emptyList<StopwatchLapModel>().toImmutableList(),
    val showLaps: Boolean = false,
    val showCurrent: Boolean = false,
    val showMinMax: Boolean = false,
)

data class StopwatchUiTickModel(
    val stopwatchId: Long = -1,
    val elapsed: String = "00:00.00",
    val currentLap: StopwatchLapModel? = null,
    val minLap: StopwatchLapModel? = null,
    val maxLap: StopwatchLapModel? = null,
)

data class StopwatchesUiModel(
    val stopwatches: ImmutableList<StopwatchUiDataModel>,
    val isSpeedDialExpanded: Boolean = false,
    val isDeleteVisible: Boolean = false,
    val isLoading: Boolean = false,
)

const val DEFAULT_LOADING_STOPWATCH_ID = -1L

fun emptyStopwatchesUiModel(
    defaultName: String = "",
    isSpeedDialExpanded: Boolean = false,
): StopwatchesUiModel =
    StopwatchesUiModel(
        stopwatches = listOf(
            StopwatchUiDataModel(
                stopwatchId = DEFAULT_LOADING_STOPWATCH_ID,
                name = defaultName,
            )
        ).toImmutableList(),
        isSpeedDialExpanded = isSpeedDialExpanded,
        isDeleteVisible = false,
        isLoading = true,
    )

fun StopwatchMetadataModel.toStopwatchUiDataModel(
    defaultName: String = "",
    showLaps: Boolean,
    showCurrent: Boolean,
    showMinMax: Boolean
): StopwatchUiDataModel =
    StopwatchUiDataModel(
        stopwatchId = stopwatchId,
        name = name.ifEmpty { defaultName },
        iconId = iconId,
        isRunning = isRunning,
        laps = laps.run { safeSubList(0, lastIndex) }.toImmutableList(),
        showLaps = showLaps,
        showCurrent = showCurrent,
        showMinMax = showMinMax,
    )

fun StopwatchTickModel.toStopwatchUiTickModel(): StopwatchUiTickModel =
    StopwatchUiTickModel(
        stopwatchId = stopwatchId,
        elapsed = elapsed,
        currentLap = currentLap,
        minLap = minLap,
        maxLap = maxLap,
    )

fun List<StopwatchMetadataModel>.toStopwatchUiDataModels(
    defaultName: String = "",
    getShowLaps: (StopwatchMetadataModel) -> Boolean,
    getShowCurrent: (StopwatchMetadataModel) -> Boolean,
    getShowMinMax: (StopwatchMetadataModel) -> Boolean,
    onEmptyName: (StopwatchMetadataModel) -> Unit
): List<StopwatchUiDataModel> =
    map {
        it.name.ifEmpty { onEmptyName(it) }
        it.toStopwatchUiDataModel(
            defaultName = defaultName,
            showLaps = getShowLaps(it),
            showCurrent = getShowCurrent(it),
            showMinMax = getShowMinMax(it)
        )
    }
