@file:OptIn(ExperimentalMaterial3Api::class)

package com.timemeasurer.app.feature.timers_statistics

import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.PaddingValues
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.ExperimentalMaterial3Api
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.getValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import androidx.lifecycle.viewmodel.compose.viewModel
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.empty
import com.timemeasurer.app.core.resources.timers_statistics_no_data
import com.timemeasurer.app.core.ui.icon.MainIconSet
import com.timemeasurer.app.core.ui.viewmodels.LocalSnackbarHost
import com.timemeasurer.app.core.ui.viewmodels.UiState
import com.timemeasurer.app.core.ui.widgets.CircularContent
import com.timemeasurer.app.core.ui.widgets.SimplePlaceholderContent
import com.timemeasurer.app.feature.timers_statistics.models.TimersStatisticsActions
import com.timemeasurer.app.feature.timers_statistics.models.TimersStatisticsEvents
import com.timemeasurer.app.feature.timers_statistics.widgets.TimerStatisticsCard
import org.jetbrains.compose.resources.stringResource

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TimersStatisticsScreen(
    viewModel: TimersStatisticsViewModel = viewModel { TimersStatisticsViewModel() }
) {
    val state by viewModel.state.collectAsStateWithLifecycle()
    val action by viewModel.action.collectAsStateWithLifecycle()

    when (val currentAction = action) {
        is TimersStatisticsActions.ShowError -> {
            val error = stringResource(currentAction.error)
            val snackbarHost = LocalSnackbarHost.current
            LaunchedEffect(key1 = action) {
                snackbarHost?.showSnackbar(error)
                viewModel.setEvent(TimersStatisticsEvents.None)
            }
        }
        else -> {}
    }

    when (val currentState = state) {
        UiState.Loading -> CircularContent()
        UiState.Empty -> SimplePlaceholderContent(
            header = stringResource(Res.string.empty),
            title = stringResource(Res.string.timers_statistics_no_data),
            image = MainIconSet.search.icon,
            imageContentDescription = stringResource(Res.string.timers_statistics_no_data)
        )
        is UiState.Success -> {
            LazyColumn(
                modifier = Modifier.fillMaxSize(),
                contentPadding = PaddingValues(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                items(currentState.item.items) { item ->
                    TimerStatisticsCard(item = item)
                }
            }
        }
        else -> {}
    }
}
