package com.timemeasurer.app.core.data.model

import com.timemeasurer.app.core.model.stopwatch.StopwatchModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchSettingsModel
import data.StopwatchesEntity
import kotlinx.serialization.json.Json

fun StopwatchesEntity.toStopwatchModel() = StopwatchModel(
    id = id,
    name = name,
    settings = Json.decodeFromString(StopwatchSettingsModel.serializer(), settings)
)

fun List<StopwatchesEntity>.entitiesToStopwatchesModels() = map { it.toStopwatchModel() }

fun StopwatchModel.toStopwatchesEntity() = StopwatchesEntity(
    id = id,
    name = name,
    settings = Json.encodeToString(StopwatchSettingsModel.serializer(), settings)
)

fun List<StopwatchModel>.modelsToStopwatchesEntities() = map { it.toStopwatchesEntity() }
