package com.timemeasurer.app.navigation

import androidx.compose.material3.adaptive.ExperimentalMaterial3AdaptiveApi
import androidx.compose.material3.adaptive.currentWindowAdaptiveInfo
import androidx.compose.material3.adaptive.layout.calculatePaneScaffoldDirectiveWithTwoPanesOnMediumWidth
import androidx.compose.material3.adaptive.navigation3.ListDetailSceneStrategy
import androidx.compose.material3.adaptive.navigation3.rememberListDetailSceneStrategy
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.unit.dp
import androidx.navigation3.runtime.NavKey
import com.timemeasurer.app.core.ui.ext.screenSize

/**
 * Creates a [ListDetailSceneStrategy] with a custom [PaneScaffoldDirective] that
 * uses dual-pane layout on medium-width screens (not just expanded).
 *
 * The list pane preferred width is set to 60% of the screen width, which causes the
 * detail pane to fill the remaining 40% (since the detail pane is the Primary/highest-
 * priority pane and stretches to occupy leftover space).
 *
 * Note: This is an approximation because [PaneScaffoldDirective.defaultPanePreferredWidth]
 * applies to all panes equally, but the Primary pane's stretching behavior effectively
 * gives the list pane ~60% and the detail pane ~40%.
 */
@OptIn(ExperimentalMaterial3AdaptiveApi::class)
@Composable
fun rememberCustomListDetailSceneStrategy(): ListDetailSceneStrategy<NavKey> {
    val adaptiveInfo = currentWindowAdaptiveInfo()
    val density = LocalDensity.current
    val screenPx = screenSize
    val directive = remember(adaptiveInfo, screenPx, density) {
        val widthDp = screenPx.width / density.density
        calculatePaneScaffoldDirectiveWithTwoPanesOnMediumWidth(adaptiveInfo)
            .copy(defaultPanePreferredWidth = (widthDp * 0.8f).dp)
    }
    return rememberListDetailSceneStrategy(directive = directive)
}
