package com.timemeasurer.app.core.datastore.themes

import com.russhwolf.settings.ExperimentalSettingsApi
import com.russhwolf.settings.ObservableSettings
import com.russhwolf.settings.Settings
import com.russhwolf.settings.coroutines.getStringFlow
import com.russhwolf.settings.observable.makeObservable
import com.timemeasurer.app.core.model.DarkThemeConfig
import com.timemeasurer.app.core.model.ThemeColor
import com.timemeasurer.app.core.model.ThemeData
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.combine

@OptIn(ExperimentalSettingsApi::class)
internal class ThemesSourceImpl(
    private val settings: Settings,
    private val coroutineDispatcher: CoroutineDispatcher
) : ThemesSource {

    private val flowSettings: ObservableSettings = settings.makeObservable()

    override val themeData: Flow<ThemeData> = combine(
            flowSettings.getStringFlow(KEY_THEME_COLOR, ThemeColor.PALE_PEACH.name),
            flowSettings.getStringFlow(KEY_DARK_THEME_CONFIG, DarkThemeConfig.FOLLOW_SYSTEM.name),
            flowSettings.getStringFlow(KEY_GRADIENT_ENABLED, true.toString()),
            flowSettings.getStringFlow(KEY_GRADIENT_END_COLOR, ThemeColor.WHITE.name),
        ) { color, config, gradientEnabled, gradientEnd ->
            ThemeData(
                themeColor = themeColorFromString(color),
                darkThemeConfig = DarkThemeConfig.valueOf(config),
                isGradientBackgroundEnabled = gradientEnabled.toBooleanStrictOrNull() ?: false,
                gradientEndColor = themeColorFromString(gradientEnd),
            )
        }
        //.flowOn(coroutineDispatcher) // Bug with multithreading

    override suspend fun setThemeColor(themeColor: ThemeColor) =
        flowSettings.putString(KEY_THEME_COLOR, themeColor.name)

    override suspend fun getThemeColor(): ThemeColor =
        themeColorFromString(flowSettings.getString(KEY_THEME_COLOR, ThemeColor.WHITE.name))

    override suspend fun setDarkThemeConfig(darkThemeConfig: DarkThemeConfig) =
        flowSettings.putString(KEY_DARK_THEME_CONFIG, darkThemeConfig.name)

    override suspend fun getDarkThemeConfig(): DarkThemeConfig =
        DarkThemeConfig.valueOf(
            flowSettings.getString(
                KEY_DARK_THEME_CONFIG,
                DarkThemeConfig.FOLLOW_SYSTEM.name
            )
        )

    override suspend fun setGradientBackgroundEnabled(enabled: Boolean) =
        flowSettings.putString(KEY_GRADIENT_ENABLED, enabled.toString())

    override suspend fun setGradientEndColor(color: ThemeColor) =
        flowSettings.putString(KEY_GRADIENT_END_COLOR, color.name)

    private fun themeColorFromString(value: String): ThemeColor =
        runCatching { ThemeColor.valueOf(value) }.getOrDefault(ThemeColor.WHITE)

    companion object {
        private const val KEY_THEME_COLOR = "KEY_THEME_COLOR"
        private const val KEY_DARK_THEME_CONFIG = "KEY_DARK_THEME_CONFIG"
        private const val KEY_GRADIENT_ENABLED = "gradient_enabled"
        private const val KEY_GRADIENT_END_COLOR = "gradient_end_color"
    }
}
