package com.timemeasurer.app.core.domain.timer

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.common.time.MonotonicClock
import com.timemeasurer.app.core.domain.services.TimerServiceActions
import com.timemeasurer.app.core.domain.settings.SingleActiveTimerSettingUseCase
import com.timemeasurer.app.core.domain.sound.TimerSoundInteractor
import com.timemeasurer.app.core.model.ActiveTimerSetting
import com.timemeasurer.app.core.model.icon.DefaultIconIds
import com.timemeasurer.app.core.model.timer.TimerMetadataModel
import com.timemeasurer.app.core.model.timer.TimerModel
import com.timemeasurer.app.core.model.timer.TimerSettingsModel
import com.timemeasurer.app.core.model.timer.TimerTickModel
import com.timemeasurer.app.core.remote_services.AnalyticsService
import com.timemeasurer.app.core.remote_services.CrashlyticsService
import com.timemeasurer.app.core.remote_services.NoOpAnalyticsService
import com.timemeasurer.app.core.remote_services.NoOpCrashlyticsService
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.emitAll
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.flatMapLatest
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

class TimersInteractors(
    private val getTimersUseCase: GetTimersUseCase,
    private val createNewTimerUseCase: CreateNewTimerUseCase,
    private val updateTimerUseCase: UpdateTimerUseCase,
    private val deleteTimerUseCase: DeleteTimerUseCase,
    private val getTimerByIdUseCase: GetTimerByIdUseCase,
    private val getSessionByMaxValueUseCase: GetSessionByMaxValueUseCase,
    private val createNewSessionUseCase: CreateNewSessionUseCase,
    private val createExistSessionUseCase: CreateExistSessionUseCase,
    private val updateSessionUseCase: UpdateSessionUseCase,
    private val deleteSessionsByTimerIdUseCase: DeleteSessionsByTimerIdUseCase,
    private val ioScope: CoroutineScope,
    private val ioDispatcher: CoroutineDispatcher,
    private val clock: MonotonicClock,
    private val timerSoundInteractor: TimerSoundInteractor,
    private val activeTimerSettingUseCase: SingleActiveTimerSettingUseCase,
    private val crashlytics: CrashlyticsService = NoOpCrashlyticsService(),
    private val analytics: AnalyticsService = NoOpAnalyticsService(),
) : TimerServiceActions {

    private val timersMutex = Mutex()
    private val timersInteractors = mutableMapOf<Long, TimerInteractor>()
    private var actionJob: Job? = null

    private val activeTimerSetting: StateFlow<ActiveTimerSetting> = activeTimerSettingUseCase()
        .stateIn(ioScope, SharingStarted.Eagerly, ActiveTimerSetting())

    init {
        ioScope.launch {
            var previous: ActiveTimerSetting? = null
            activeTimerSetting.collect { setting ->
                if (setting.isEnabled) {
                    if (previous?.isEnabled == false) {
                        // Setting was just enabled
                        val visibleRunningId = timersMutex.withLock {
                            timersInteractors.entries.firstOrNull { (_, interactor) ->
                                interactor.isVisible && interactor.isRunning
                            }?.key
                        }
                        if (visibleRunningId != null) {
                            activeTimerSettingUseCase.setActiveTimerId(visibleRunningId)
                        } else {
                            val runningIds = timersMutex.withLock {
                                timersInteractors.filter { (_, interactor) ->
                                    interactor.isRunning
                                }.keys.toList()
                            }
                            runningIds.forEach { timersInteractors[it]?.startPause() }
                        }
                    } else if (setting.activeTimerId != null) {
                        // Active id changed or initial value with active id
                        val idsToPause = timersMutex.withLock {
                            timersInteractors.filter { (id, interactor) ->
                                id != setting.activeTimerId && interactor.isRunning
                            }.keys.toList()
                        }
                        idsToPause.forEach { timersInteractors[it]?.startPause() }
                    }
                }
                previous = setting
            }
        }
    }

    private fun getTimerInteractor(timerModel: TimerModel): TimerInteractor =
        TimerInteractor(
            timerModel = timerModel,
            getTimerByIdUseCase = getTimerByIdUseCase,
            getSessionByMaxValueUseCase = getSessionByMaxValueUseCase,
            createNewSessionUseCase = createNewSessionUseCase,
            createExistSessionUseCase = createExistSessionUseCase,
            updateSessionUseCase = updateSessionUseCase,
            deleteSessionsByTimerIdUseCase = deleteSessionsByTimerIdUseCase,
            ioScope = ioScope,
            ioDispatcher = ioDispatcher,
            clock = clock,
            timerSoundInteractor = timerSoundInteractor,
            activeTimerSettingUseCase = activeTimerSettingUseCase,
            crashlytics = crashlytics,
        )

    val interactors: StateFlow<Result<List<Pair<Long, TimerInteractor>>>> = flow {
        emitAll(getTimersUseCase())
    }.map { result ->
        when (result) {
            is Result.Error -> result
            is Result.Loading -> result
            is Result.Success<List<TimerModel>> -> timersMutex.withLock {
                if (result.data.isEmpty()) {
                    timersInteractors.clear()
                    when (val timer = createNewTimerUseCase(name = "")) {
                        is Result.Error -> return@map timer
                        is Result.Loading -> return@map timer
                        is Result.Success<TimerModel> ->
                            timersInteractors[timer.data.id] = getTimerInteractor(timer.data)
                    }
                } else {
                    val ids = timersInteractors.keys.toMutableSet()
                    result.data.forEach {
                        ids.remove(it.id)
                        if (!timersInteractors.contains(it.id)) {
                            timersInteractors[it.id] = getTimerInteractor(it)
                        }
                    }
                    ids.forEach { timersInteractors.remove(it) }
                }
                Result.Success(timersInteractors.toList())
            }
        }
    }
    .catch {
        crashlytics.log("TimersInteractors() - interactors")
        crashlytics.recordException(it)
        emit(Result.Error(exception = it, error = it.message))
    }
    .flowOn(ioDispatcher)
    .stateIn(ioScope, SharingStarted.Lazily, Result.Success(emptyList()))

    val metadataState: StateFlow<Result<List<TimerMetadataModel>>> = interactors
        .flatMapLatest { result ->
            flow<Result<List<TimerMetadataModel>>> {
                when (result) {
                    is Result.Error -> emit(result)
                    is Result.Loading -> emit(result)
                    is Result.Success<List<Pair<Long, TimerInteractor>>> -> {
                        if (result.data.isEmpty()) {
                            emit(Result.Success(emptyList()))
                            return@flow
                        }
                        combine(result.data.map { it.second.metadataState }) { states ->
                            states.mapNotNull { state ->
                                when (state) {
                                    is Result.Loading -> return@mapNotNull null
                                    is Result.Error -> return@mapNotNull null
                                    is Result.Success<TimerMetadataModel> -> state.data
                                }
                            }
                        }.collect {
                            emit(Result.Success(it))
                        }
                    }
                }
            }
        }
        .catch {
            crashlytics.log("TimersInteractors() - metadataState")
            crashlytics.recordException(it)
            println("TimersInteractors() - metadataState - catch: ${it.message}")
            emit(Result.Error(exception = it, error = it.message))
        }
        .distinctUntilChanged()
        .flowOn(ioDispatcher)
        .stateIn(ioScope, SharingStarted.Eagerly, Result.Success(emptyList()))

    val tickState: StateFlow<Map<Long, StateFlow<Result<TimerTickModel>>>> = interactors
        .flatMapLatest { result ->
            flow<Map<Long, StateFlow<Result<TimerTickModel>>>> {
                when (result) {
                    is Result.Error -> emit(emptyMap())
                    is Result.Loading -> emit(emptyMap())
                    is Result.Success<List<Pair<Long, TimerInteractor>>> -> {
                        if (result.data.isEmpty()) {
                            emit(emptyMap())
                            return@flow
                        }
                        emit(result.data.associate { it.first to it.second.tickState })
                    }
                }
            }
        }
        .catch {
            crashlytics.log("TimersInteractors() - tickState")
            crashlytics.recordException(it)
            println("TimersInteractors() - tickState - catch: ${it.message}")
            emit(emptyMap())
        }
        .flowOn(ioDispatcher)
        .stateIn(ioScope, SharingStarted.Lazily, emptyMap())

    override fun startPause(timerId: Long) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            timersMutex.withLock {
                val interactor = timersInteractors[timerId] ?: return@withLock
                val wasRunning = interactor.isRunning
                interactor.startPause()
                analytics.logEvent("timer_start_pause", mapOf("timer_id" to timerId, "is_running" to !wasRunning))

                if (!wasRunning) {
                    val setting = activeTimerSetting.value
                    if (setting.isEnabled && setting.activeTimerId != timerId) {
                        ioScope.launch {
                            activeTimerSettingUseCase.setActiveTimerId(timerId)
                        }
                    }
                }
            }
        }
    }

    fun reset(timerId: Long) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            timersMutex.withLock {
                timersInteractors[timerId]?.reset()
                analytics.logEvent("timer_reset", mapOf("timer_id" to timerId))
            }
        }
    }

    override fun skip(timerId: Long) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            timersMutex.withLock {
                timersInteractors[timerId]?.skip()
                analytics.logEvent("timer_skip", mapOf("timer_id" to timerId))
            }
        }
    }

    fun stop(timerId: Long) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            timersMutex.withLock {
                timersInteractors[timerId]?.stop()
                analytics.logEvent("timer_stop", mapOf("timer_id" to timerId))
            }
        }
    }

    fun create(name: String, iconId: String = DefaultIconIds.TIMER) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            when (val result = createNewTimerUseCase(name = name, settings = TimerSettingsModel(iconId = iconId))) {
                is Result.Error -> {}
                is Result.Loading -> {}
                is Result.Success<TimerModel> -> {}
            }
        }
    }

    fun rename(timerId: Long, name: String, iconId: String = "") {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            when (val result = updateTimerUseCase(timerId = timerId, newName = name, iconId = iconId)) {
                is Result.Error -> {}
                is Result.Loading -> {}
                is Result.Success<Long> -> {}
            }
        }
    }

    fun delete(timerId: Long) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch {
            val setting = activeTimerSettingUseCase().first()
            if (setting.isEnabled && setting.activeTimerId == timerId) {
                activeTimerSettingUseCase.setActiveTimerId(null)
            }
            deleteTimerUseCase(timerId)
        }
    }

    fun setVisible(timerId: Long, isVisible: Boolean) {
        ioScope.launch {
            timersMutex.withLock {
                timersInteractors[timerId]?.setVisible(isVisible)
            }
        }
    }

}
