package com.timemeasurer.app.core.domain.stopwatch

import com.timemeasurer.app.core.common.extensions.millisecondsToFormatStopwatchTime
import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.common.time.ElapsedTimer
import com.timemeasurer.app.core.common.time.MonotonicClock
import com.timemeasurer.app.core.model.stopwatch.StopwatchLapModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchLapsModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchMetadataModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchTickModel
import com.timemeasurer.app.core.remote_services.CrashlyticsService
import com.timemeasurer.app.core.remote_services.NoOpCrashlyticsService
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.distinctUntilChanged
import kotlinx.coroutines.flow.emitAll
import kotlinx.coroutines.flow.flatMapLatest
import kotlinx.coroutines.flow.flow
import kotlinx.coroutines.flow.flowOf
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.flow.onCompletion
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlin.concurrent.atomics.AtomicBoolean
import kotlin.concurrent.atomics.ExperimentalAtomicApi

@OptIn(ExperimentalAtomicApi::class)
class StopwatchInteractor(
    private val stopwatchModel: StopwatchModel,
    private val getStopwatchByIdUseCase: GetStopwatchByIdUseCase,
    private val getAllLapsByStopwatchIdUseCase: GetAllLapsByStopwatchIdUseCase,
    private val createNewLapUseCase: CreateNewLapUseCase,
    private val updateLapUseCase: UpdateLapUseCase,
    private val updateAndCreateLapUseCase: UpdateAndCreateLapUseCase,
    private val deleteLapsByStopwatchIdUseCase: DeleteLapsByStopwatchIdUseCase,
    private val ioScope: CoroutineScope,
    private val ioDispatcher: CoroutineDispatcher,
    private val clock: MonotonicClock,
    private val crashlytics: CrashlyticsService = NoOpCrashlyticsService(),
) {

    companion object {
        private const val STOPWATCH_TICK_TIME = 50L
    }

    private val stopwatchTimer = ElapsedTimer(clock)
    private val lapTimer = ElapsedTimer(clock)

    private val stateMutex = Mutex()
    private val isTimersInitialized = AtomicBoolean(false)
    private var currentLap: StopwatchLapModel? = null

    private var actionJob: Job? = null

    private val _stopwatchStateFlow = MutableStateFlow(false)
    private val _isVisibleFlow = MutableStateFlow(false)

    val isVisible: Boolean get() = _isVisibleFlow.value

    val isRunning: Boolean get() = _stopwatchStateFlow.value

    private val _stopwatchTickFlow = combine(
        _stopwatchStateFlow,
        _isVisibleFlow
    ) { isRunning, isVisible ->
        isRunning && isVisible
    }.flatMapLatest { shouldTick ->
        if (shouldTick) {
            flow {
                while (currentCoroutineContext().isActive) {
                    emit(Unit)
                    delay(STOPWATCH_TICK_TIME)
                }
            }
        } else {
            flowOf(Unit)
        }
    }.flowOn(ioDispatcher)

    private val _stopwatchLapsFlow: StateFlow<Result<StopwatchLapsModel>> = flow {
        getAllLapsByStopwatchIdUseCase(stopwatchModel.id)
            .collect { result ->
                when (result) {
                    is Result.Loading -> emit(result)
                    is Result.Error -> emit(result)
                    is Result.Success<StopwatchLapsModel> -> {
                        if (result.data.laps.isNotEmpty()) {
                            if (isTimersInitialized.compareAndSet(expectedValue = false, newValue = true)) {
                                val lastLap = result.data.laps.last()
                                stopwatchTimer.add(result.data.totalTime)
                                lapTimer.add(lastLap.time)
                                stateMutex.withLock { currentLap = lastLap }
                            }

                            emit(result)
                        } else {
                            createNewLapUseCase(stopwatchModel.id)
                        }
                    }
                }
            }
    }
    .flowOn(ioDispatcher)
    .stateIn(
        scope = ioScope,
        started = SharingStarted.Lazily,
        initialValue = Result.Loading
    )

    private val _stopwatchesFlow = flow {
        emit(Result.Success(stopwatchModel))
        emitAll(getStopwatchByIdUseCase(stopwatchModel.id))
    }

    val metadataState: StateFlow<Result<StopwatchMetadataModel>> = combine(
        _stopwatchesFlow,
        _stopwatchLapsFlow,
        _stopwatchStateFlow
    ) { stopwatches, laps, isRunning ->
        val (timerName, timerIconId) = when (stopwatches) {
            is Result.Loading -> return@combine Result.Loading
            is Result.Error -> return@combine stopwatches
            is Result.Success<StopwatchModel?> -> stopwatches.data?.run { name to settings.iconId }
                ?: ("" to "")
        }

        val timerLaps = when (laps) {
            is Result.Loading -> return@combine Result.Loading
            is Result.Error -> {
                println("StopwatchInteractor(${stopwatchModel.id}) - metadataState - laps error: ${laps.error}")
                StopwatchLapsModel()
            }
            is Result.Success<StopwatchLapsModel> -> laps.data
        }

        Result.Success(
            StopwatchMetadataModel(
                stopwatchId = stopwatchModel.id,
                isRunning = isRunning,
                name = timerName,
                iconId = timerIconId,
                laps = timerLaps.laps,
                totalTime = timerLaps.totalTime
            )
        )
    }
    .onCompletion {
        println("StopwatchInteractor(${stopwatchModel.id}) - metadataState - onCompletion(): $it")
    }
    .catch {
        crashlytics.log("StopwatchInteractor(${stopwatchModel.id}) - metadataState")
        crashlytics.recordException(it)
        println("StopwatchInteractor(${stopwatchModel.id}) - metadataState - catch(): $it")
        emit(Result.Error(it))
    }
    .distinctUntilChanged()
    .flowOn(ioDispatcher)
    .stateIn(
        scope = ioScope,
        started = SharingStarted.Lazily,
        initialValue = Result.Loading
    )

    val tickState: StateFlow<Result<StopwatchTickModel>> = combine(
        _stopwatchTickFlow,
        _stopwatchLapsFlow,
        _stopwatchStateFlow,
        _isVisibleFlow
    ) { tick, lapsResult, isRunning, isVisible ->
        val timerLaps = when (lapsResult) {
            is Result.Loading -> return@combine Result.Loading
            is Result.Error -> return@combine Result.Error(lapsResult.exception, lapsResult.error)
            is Result.Success<StopwatchLapsModel> -> lapsResult.data
        }

        val stopwatchTime = stopwatchTimer.elapsed()
        val lapTime = lapTimer.elapsed()
        val stopwatchTimeFormatted = stopwatchTime.millisecondsToFormatStopwatchTime()

        val updatedCurrentLap = stateMutex.withLock {
            currentLap?.copy(time = lapTime, totalTimeFromStart = stopwatchTime)
        }

        val minLap = timerLaps.minLap
        val maxLap = timerLaps.maxLap

        val lapNumber = updatedCurrentLap?.lapNumber ?: (timerLaps.laps.size + 1)

        Result.Success(
            StopwatchTickModel(
                stopwatchId = stopwatchModel.id,
                elapsed = stopwatchTimeFormatted,
                isRunning = isRunning,
                currentLap = updatedCurrentLap,
                minLap = minLap,
                maxLap = maxLap,
                lapNumber = lapNumber,
                isVisible = isVisible
            )
        )
    }
    .distinctUntilChanged()
    .catch {
        crashlytics.log("StopwatchInteractor(${stopwatchModel.id}) - tickState")
        crashlytics.recordException(it)
        println("StopwatchInteractor(${stopwatchModel.id}) - tickState - catch(): $it")
        emit(Result.Error(it))
    }
    .stateIn(
        scope = ioScope,
        started = SharingStarted.Lazily,
        initialValue = Result.Loading
    )

    private suspend fun saveLapTime(lapTime: Long) {
        val lap = stateMutex.withLock { currentLap } ?: return
        when (val result = updateLapUseCase(id = lap.id, time = lapTime)) {
            is Result.Loading -> println("StopwatchInteractor() - saveLapTime - loading")
            is Result.Error -> println("StopwatchInteractor() - saveLapTime - error: $result")
            is Result.Success<StopwatchLapModel> -> println("StopwatchInteractor() - saveLapTime - success: ${result.data}")
        }
    }

    private fun launchAction(block: suspend () -> Unit) {
        if (actionJob?.isActive == true) return
        actionJob = ioScope.launch { block() }
    }

    suspend fun startStop() {
        val wasRunning = _stopwatchStateFlow.value
        if (wasRunning) {
            stopwatchTimer.pause()
            val lapTime = lapTimer.pause()
            saveLapTime(lapTime)
        } else {
            stopwatchTimer.start()
            lapTimer.start()
        }
        _stopwatchStateFlow.value = !wasRunning
    }

    fun lap() {
        if (!_stopwatchStateFlow.value) return
        launchAction {
            val lap = stateMutex.withLock { currentLap } ?: return@launchAction
            when (val result = updateAndCreateLapUseCase(
                stopwatchId = stopwatchModel.id,
                lapId = lap.id,
                time = lapTimer.elapsed()
            )) {
                is Result.Loading -> println("StopwatchInteractor() - lap - loading")
                is Result.Error -> println("StopwatchInteractor() - lap - error: $result")
                is Result.Success<StopwatchLapModel> -> {
                    println("StopwatchInteractor() - lap - success: ${result.data}")
                    lapTimer.restart()
                    stateMutex.withLock { currentLap = result.data }
                }
            }
        }
    }

    fun reset() {
        launchAction {
            _stopwatchStateFlow.value = false
            stopwatchTimer.reset()
            lapTimer.reset()
            isTimersInitialized.store(false)
            stateMutex.withLock { currentLap = null }

            when (val result = deleteLapsByStopwatchIdUseCase(stopwatchModel.id)) {
                is Result.Loading -> println("StopwatchInteractor() - reset - loading")
                is Result.Error -> println("StopwatchInteractor() - reset - error: $result")
                is Result.Success<Long> -> println("StopwatchInteractor() - reset - success: ${result.data}")
            }
        }
    }

    fun setVisible(isVisible: Boolean) {
        _isVisibleFlow.value = isVisible
    }
}
