package com.timemeasurer.app.core.data.model

import com.timemeasurer.app.core.model.timer.TimerModel
import com.timemeasurer.app.core.model.timer.TimerSettingsModel
import data.TimersEntity
import kotlinx.serialization.json.Json
import kotlin.time.ExperimentalTime

@OptIn(ExperimentalTime::class)
fun TimersEntity.toTimerModel() = TimerModel(
    id = id,
    name = name,
    settings = Json.decodeFromString(TimerSettingsModel.serializer(), settings)
)

fun List<TimersEntity>.entitiesToTimersModels() = map { it.toTimerModel() }

@OptIn(ExperimentalTime::class)
fun TimerModel.toTimersEntity() = TimersEntity(
    id = id,
    name = name,
    settings = Json.encodeToString(TimerSettingsModel.serializer(), settings)
)

fun List<TimerModel>.modelsToTimersEntities() = map { it.toTimersEntity() }