package com.timemeasurer.app.core.ui.ext

import com.timemeasurer.app.core.model.exceptions.CommonException
import com.timemeasurer.app.core.model.exceptions.EmptyException
import com.timemeasurer.app.core.model.exceptions.NetworkException
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.bad_request
import com.timemeasurer.app.core.resources.conflict
import com.timemeasurer.app.core.resources.error_with_code
import com.timemeasurer.app.core.resources.forbidden
import com.timemeasurer.app.core.resources.internal_server_error
import com.timemeasurer.app.core.resources.method_not_allowed
import com.timemeasurer.app.core.resources.network_unknown_error
import com.timemeasurer.app.core.resources.no_data
import com.timemeasurer.app.core.resources.not_found
import com.timemeasurer.app.core.resources.request_timeout
import com.timemeasurer.app.core.resources.unauthorized
import com.timemeasurer.app.core.resources.unknown_error
import com.timemeasurer.app.core.resources.unsupported_media_type
import org.jetbrains.compose.resources.StringResource


internal val NETWORK_ERRORS = mapOf(
    400 to Res.string.bad_request,
    401 to Res.string.unauthorized,
    403 to Res.string.forbidden,
    404 to Res.string.not_found,
    405 to Res.string.method_not_allowed,
    408 to Res.string.request_timeout,
    409 to Res.string.conflict,
    415 to Res.string.unsupported_media_type,
    500 to Res.string.internal_server_error,
)

val Throwable?.toStringResource: StringResource
    get() = when(val error = this) {
        is EmptyException -> Res.string.no_data
        is CommonException -> error.code?.let { Res.string.error_with_code }
                ?: Res.string.unknown_error
        is NetworkException -> NETWORK_ERRORS[error.errorCode]
            ?: Res.string.network_unknown_error
        else -> Res.string.unknown_error
    }