@Composable
fun ThemeColorPaletteWidget(
    selectedColor: ThemeColor,
    onColorSelected: (ThemeColor) -> Unit,
    modifier: Modifier = Modifier,
    columns: Int = 8,
    swatchSize: Dp = 36.dp,
    spacing: Dp = 4.dp,
    secondarySelectedColor: ThemeColor? = null,
) {
    BoxWithConstraints(
        modifier = modifier.fillMaxWidth(),
        contentAlignment = Alignment.Center,
    ) {
        val availableWidth = maxWidth - spacing * (columns - 1)
        val actualSwatchSize = if (availableWidth > 0.dp) {
            minOf(swatchSize, availableWidth / columns)
        } else {
            swatchSize
        }
        val actualSpacing = if (actualSwatchSize > 0.dp) spacing else 0.dp

        Column(
            verticalArrangement = Arrangement.spacedBy(actualSpacing),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            ThemeColor.entries.chunked(columns).forEach { rowColors ->
                Row(
                    horizontalArrangement = Arrangement.spacedBy(actualSpacing),
                ) {
                    rowColors.forEach { color ->
                        ThemeColorSwatch(
                            color = color,
                            isPrimarySelected = color == selectedColor,
                            isSecondarySelected = color == secondarySelectedColor,
                            swatchSize = actualSwatchSize,
                            onClick = { onColorSelected(color) },
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun ThemeColorSwatch(
    color: ThemeColor,
    isPrimarySelected: Boolean,
    isSecondarySelected: Boolean,
    swatchSize: Dp,
    onClick: () -> Unit,
) {
    val shape = MaterialTheme.shapes.small
    Box(
        modifier = Modifier
            .size(swatchSize)
            .clip(shape)
            .background(color = color.seedColor(), shape = shape)
            .clickable(onClick = onClick),
        contentAlignment = Alignment.Center,
    ) {
        if (isPrimarySelected) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .clip(shape)
                    .border(1.dp, Color.Black, shape)
                    .padding(1.dp)
                    .clip(shape)
                    .border(1.dp, Color.White, shape)
            )
        } else if (isSecondarySelected) {
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .clip(shape)
                    .border(1.dp, Color.White, shape)
                    .padding(1.dp)
                    .clip(shape)
                    .border(1.dp, Color.Black, shape)
            )
        }
    }
}

