package com.timemeasurer.app.feature.timers_statistics.navigation

import androidx.compose.material3.adaptive.ExperimentalMaterial3AdaptiveApi
import androidx.navigation3.runtime.EntryProviderScope
import androidx.navigation3.runtime.NavKey
import com.timemeasurer.app.core.navigation.AppRoute
import com.timemeasurer.app.core.navigation.AppRouter
import com.timemeasurer.app.core.navigation.CustomListDetailKeys
import com.timemeasurer.app.feature.timers_statistics.TimersStatisticsScreen

@OptIn(ExperimentalMaterial3AdaptiveApi::class)
fun EntryProviderScope<NavKey>.timersStatisticsEntry(
    appRouter: AppRouter,
) {
    entry<AppRoute.TimersStatistics>(
        metadata = CustomListDetailKeys.detailPane()
    ) {
        TimersStatisticsScreen()
    }
}
