package com.timemeasurer.app.feature.themes

import androidx.lifecycle.viewModelScope
import com.timemeasurer.app.core.common.di.Inject
import com.timemeasurer.app.core.data.repositories.theme.ThemeRepository
import com.timemeasurer.app.core.ui.viewmodels.UiState
import com.timemeasurer.app.core.ui.viewmodels.UiStateViewModel
import com.timemeasurer.app.feature.themes.models.ColorSelectionTarget
import com.timemeasurer.app.feature.themes.models.ThemesActions
import com.timemeasurer.app.feature.themes.models.ThemesEvents
import com.timemeasurer.app.feature.themes.models.ThemesUiModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

class ThemesViewModel(
    private val themeRepository: ThemeRepository = Inject.instance(),
) : UiStateViewModel<ThemesUiModel, ThemesActions, ThemesEvents>(
    initialAction = ThemesActions.None,
) {

    private val _colorSelectionTarget = MutableStateFlow(ColorSelectionTarget.PRIMARY)

    override val state: StateFlow<UiState<ThemesUiModel>> = combine(
        themeRepository.themeData,
        _colorSelectionTarget,
    ) { themeData, target ->
        UiState.Success(ThemesUiModel(themeData, colorSelectionTarget = target))
    }.stateIn(
        scope = viewModelScope,
        started = SharingStarted.WhileSubscribed(5_000),
        initialValue = UiState.Loading,
    )

    override fun setEvent(item: ThemesEvents) {
        when (item) {
            is ThemesEvents.UpdateThemeColor -> updateThemeColor(item.themeColor)
            is ThemesEvents.UpdateGradientEnabled -> updateGradientEnabled(item.enabled)
            is ThemesEvents.UpdateGradientEndColor -> updateGradientEndColor(item.color)
            is ThemesEvents.SelectColorTarget -> _colorSelectionTarget.value = item.target
        }
    }

    private fun updateThemeColor(themeColor: com.timemeasurer.app.core.model.ThemeColor) {
        viewModelScope.launch {
            themeRepository.setThemeColor(themeColor)
        }
    }

    private fun updateGradientEnabled(enabled: Boolean) {
        viewModelScope.launch {
            themeRepository.setGradientBackgroundEnabled(enabled)
        }
    }

    private fun updateGradientEndColor(color: com.timemeasurer.app.core.model.ThemeColor) {
        viewModelScope.launch {
            themeRepository.setGradientEndColor(color)
        }
    }
}
