@Composable
fun TwoLinesSwitchButtonWidget(
    titleRes: StringResource,
    subtitleRes: StringResource? = null,
    onClick: (() -> Unit)? = null,
    modifier: Modifier = Modifier,
    icon: ImageVector? = null,
    checked: Boolean = false,
    onCheckedChange: ((Boolean) -> Unit)? = null,
    enabled: Boolean = true,
) {
    TwoLinesSwitchButtonWidget(
        title = stringResource(titleRes),
        subtitle = subtitleRes?.let { stringResource(it) },
        onClick = onClick,
        modifier = modifier,
        icon = icon,
        checked = checked,
        onCheckedChange = onCheckedChange,
        enabled = enabled,
    )
}

@Composable
fun TwoLinesSwitchButtonWidget(
    title: String,
    subtitle: String? = null,
    onClick: (() -> Unit)? = null,
    modifier: Modifier = Modifier,
    icon: ImageVector? = null,
    checked: Boolean = false,
    onCheckedChange: ((Boolean) -> Unit)? = null,
    enabled: Boolean = true,
) {
    val rowClickAction: (() -> Unit)? = onClick
        ?: onCheckedChange?.let { { it(!checked) } }

    val isClickable = rowClickAction != null

    val clickableModifier = if (isClickable) {
        Modifier
            .clip(RectangleShape)
            .clickable(
                interactionSource = remember { MutableInteractionSource() },
                indication = ripple(bounded = true),
                enabled = enabled,
                onClick = rowClickAction,
            )
    } else {
        Modifier
    }

    Row(
        modifier = clickableModifier
            .fillMaxWidth()
            .wrapContentHeight()
            .then(modifier),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.SpaceBetween,
    ) {
        Row(
            modifier = Modifier.weight(1f).padding(end = 16.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            if (icon != null) {
                Icon(
                    imageVector = icon,
                    contentDescription = null,
                )
                Spacer(Modifier.width(8.dp))
            }

            Column {
                Text(
                    text = title,
                    style = MaterialTheme.typography.bodyLarge,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )

                if (subtitle != null) {
                    Spacer(Modifier.height(4.dp))
                    Text(
                        text = subtitle,
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
            }
        }

        if (onCheckedChange != null) {
            Switch(
                checked = checked,
                onCheckedChange = onCheckedChange,
                enabled = enabled,
            )
        }
    }
}

@Preview
@Composable
private fun TwoLinesButtonWidgetPreview() {
    Column(modifier = Modifier.padding(16.dp)) {
        TwoLinesSwitchButtonWidget(
            title = "Button with subtitle",
            subtitle = "This is a subtitle",
            onClick = {},
        )
        TwoLinesSwitchButtonWidget(
            title = "Switch with subtitle",
            subtitle = "This is a subtitle",
            checked = true,
            onCheckedChange = {},
        )
        TwoLinesSwitchButtonWidget(
            title = "Switch without subtitle",
            checked = false,
            onCheckedChange = {},
        )
    }
}
