package com.timemeasurer.app.feature.splash.navigation

import androidx.navigation3.runtime.EntryProviderScope
import androidx.navigation3.runtime.NavKey
import com.timemeasurer.app.core.navigation.AppRoute
import com.timemeasurer.app.core.navigation.AppRouter
import com.timemeasurer.app.feature.splash.SplashScreen

fun EntryProviderScope<NavKey>.splashEntry(
    appRouter: AppRouter,
) {
    entry<AppRoute.Splash> {
        SplashScreen(
            onNavigationEvent = { appRouter.navigateTo(AppRoute.Timers) },
        )
    }
}
