package com.timemeasurer.app.feature.timers.models

import com.timemeasurer.app.core.model.icon.DefaultIconIds
import com.timemeasurer.app.core.model.timer.TimerMetadataModel
import com.timemeasurer.app.core.model.timer.TimerProgressType
import com.timemeasurer.app.core.model.timer.TimerTickModel
import com.timemeasurer.app.core.model.timer.TimerTypeModel

data class TimerUiDataModel(
    val timerId: Long,
    val name: String,
    val iconId: String = DefaultIconIds.TIMER,
    val isRunning: Boolean,
    val type: TimerTypeModel,
    val progressType: TimerProgressType = TimerProgressType.Linear,
)

data class TimerUiTickModel(
    val timerId: Long = -1,
    val timer: String = "00:00:00",
    val progress: Int = 0,
    val toProgress: Int = 100,
)

data class TimersUiModel(
    val timers: List<TimerUiDataModel>,
    val isSpeedDialExpanded: Boolean = false,
    val isDeleteVisible: Boolean = false,
    val isLoading: Boolean = false,
)

const val DEFAULT_LOADING_TIMER_ID = -1L

fun emptyTimersUiModel(
    defaultName: String = "",
    isSpeedDialExpanded: Boolean = false,
): TimersUiModel =
    TimersUiModel(
        timers = listOf(
            TimerUiDataModel(
                timerId = DEFAULT_LOADING_TIMER_ID,
                name = defaultName,
                isRunning = false,
                type = TimerTypeModel.Session,
                progressType = TimerProgressType.Circular
            )
        ),
        isSpeedDialExpanded = isSpeedDialExpanded,
        isDeleteVisible = false,
        isLoading = true,
    )

fun TimerMetadataModel.toTimerUiDataModel(defaultName: String = ""): TimerUiDataModel =
    TimerUiDataModel(
        timerId = timerId,
        name = name.ifEmpty { defaultName },
        iconId = iconId,
        isRunning = isRunning,
        type = type,
        progressType = progressType,
    )

fun TimerTickModel.toTimerUiTickModel(): TimerUiTickModel =
    TimerUiTickModel(
        timerId = timerId,
        timer = timer,
        progress = progress,
        toProgress = toProgress,
    )

fun List<TimerMetadataModel>.toTimerUiDataModels(defaultName: String = "", onEmptyName: (TimerMetadataModel) -> Unit): List<TimerUiDataModel> =
    map {
        it.name.ifEmpty { onEmptyName(it) }
        it.toTimerUiDataModel(defaultName = defaultName)
    }
