package com.timemeasurer.app.core.domain.stopwatch

import com.timemeasurer.app.core.common.result.Result
import com.timemeasurer.app.core.domain.ext.toHoursMinutesSecondsMillis
import com.timemeasurer.app.core.model.stopwatch.StopwatchLapModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchModel
import com.timemeasurer.app.core.model.stopwatch.StopwatchStatisticsModel
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.flatMapLatest
import kotlinx.coroutines.flow.flowOf
import kotlinx.coroutines.flow.flowOn
import kotlinx.coroutines.flow.map
class GetStopwatchesStatisticsUseCase(
    private val getStopwatchesUseCase: GetStopwatchesUseCase,
    private val getAllLapsByStopwatchIdUseCase: GetAllLapsByStopwatchIdUseCase,
    private val dispatcher: CoroutineDispatcher,
) {
    suspend operator fun invoke(): Flow<Result<List<StopwatchStatisticsModel>>> {
        return getStopwatchesUseCase().flatMapLatest { stopwatchesResult ->
            when (stopwatchesResult) {
                is Result.Loading -> flowOf(Result.Loading)
                is Result.Error -> flowOf(Result.Error(stopwatchesResult.exception, stopwatchesResult.error))
                is Result.Success -> {
                    val stopwatches = stopwatchesResult.data
                    if (stopwatches.isEmpty()) {
                        return@flatMapLatest flowOf(Result.Success(emptyList()))
                    }

                    val lapFlows = stopwatches.map { stopwatch ->
                        getAllLapsByStopwatchIdUseCase(stopwatch.id).map { lapsResult ->
                            stopwatch to lapsResult
                        }
                    }

                    combine(lapFlows) { stopwatchLapsArray ->
                        val models = stopwatchLapsArray.mapNotNull { (stopwatch, lapsResult) ->
                            when (lapsResult) {
                                is Result.Success -> buildStatisticsModel(stopwatch, lapsResult.data.laps)
                                else -> null
                            }
                        }
                        Result.Success(models)
                    }
                }
            }
        }.flowOn(dispatcher)
    }

    private fun buildStatisticsModel(
        stopwatch: StopwatchModel,
        laps: List<StopwatchLapModel>,
    ): StopwatchStatisticsModel {
        val validLaps = laps.filter { it.time > 0 }
        val durations = validLaps.map { it.time }

        val totalTime = durations.sum()
        val lapCount = validLaps.size
        val avgTime = if (lapCount > 0) totalTime / lapCount else 0L

        val maxLap = validLaps.maxByOrNull { it.time }
        val minLap = validLaps.minByOrNull { it.time }

        return StopwatchStatisticsModel(
            stopwatchId = stopwatch.id,
            stopwatchName = stopwatch.name.ifEmpty { "Default" },
            totalTime = totalTime.toHoursMinutesSecondsMillis(),
            lapCount = lapCount.toString(),
            maxLapNumber = maxLap?.lapNumber ?: 0,
            maxLapTime = maxLap?.let { it.time.toHoursMinutesSecondsMillis() } ?: "00:00:00.000",
            minLapNumber = minLap?.lapNumber ?: 0,
            minLapTime = minLap?.let { it.time.toHoursMinutesSecondsMillis() } ?: "00:00:00.000",
            avgTime = avgTime.toHoursMinutesSecondsMillis(),
            laps = validLaps,
            graphType = stopwatch.settings.graphType,
        )
    }
}
