package com.timemeasurer.app.feature.timers_statistics.models

import com.timemeasurer.app.core.model.timer.TimerPeriodStatisticsModel
import com.timemeasurer.app.core.model.timer.TimerStatisticsModel

data class TimerPeriodUiModel(
    val sessionTime: String,
    val breakTime: String,
    val sessionFraction: Float,
    val periodRatio: Float,
)

data class TimerStatisticsItem(
    val timerId: Long,
    val timerName: String,
    val today: TimerPeriodUiModel,
    val week: TimerPeriodUiModel,
    val month: TimerPeriodUiModel,
    val total: TimerPeriodUiModel,
)

data class TimersStatisticsUiModel(
    val items: List<TimerStatisticsItem>
)

val TimerStatisticsModel.toStatisticsItem: TimerStatisticsItem
    get() = TimerStatisticsItem(
        timerId = timerId,
        timerName = timerName,
        today = today.toPeriodUiModel,
        week = week.toPeriodUiModel,
        month = month.toPeriodUiModel,
        total = total.toPeriodUiModel,
    )

val TimerPeriodStatisticsModel.toPeriodUiModel: TimerPeriodUiModel
    get() = TimerPeriodUiModel(
        sessionTime = sessionTime,
        breakTime = breakTime,
        sessionFraction = sessionFraction,
        periodRatio = periodRatio,
    )
