package com.timemeasurer.app.core.model

enum class PredefinedSound(val id: String, val isShort: Boolean) {
    // Short (countdown)
    BEEP_CLEAN("beep_clean", true),
    BEEP_SQUARE("beep_square", true),
    CHIRP_UP("chirp_up", true),
    FM_WHISTLE("fm_whistle", true),
    NOISE_CLICK("noise_click", true),
    DIGITAL_TICK("digital_tick", true),
    SOFT_PING("soft_ping", true),
    GLASS_TAP("glass_tap", true),

    // Long (period end)
    BELL_BRIGHT("bell_bright", false),
    GONG_LOW("gong_low", false),
    GLASS_CHIME("glass_chime", false),
    DIGITAL_ALARM("digital_alarm", false),
    SYNTH_PAD("synth_pad", false),
    ORGAN_CHORD("organ_chord", false),
    CHIME_METAL("chime_metal", false),
    COSMIC_SHIMMER("cosmic_shimmer", false),
    WOOD_BLOCK("wood_block", false),
    HARP_GLISS("harp_gliss", false),
    PIANO_NOTE("piano_note", false),
    FLUTE_NOTE("flute_note", false),
    MARIMBA("marimba", false),
    PIZZICATO("pizzicato", false),
    STEEL_DRUM("steel_drum", false),
    CHOIR_PAD("choir_pad", false),

    NONE("none", false);

    companion object {
        fun fromId(id: String): PredefinedSound = entries.find { it.id == id } ?: BEEP_CLEAN
        val all: List<PredefinedSound> = entries
    }
}
