@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun TimerSettingsForm(
    settings: TimerSettingsModel,
    onSettingsChange: (TimerSettingsModel) -> Unit,
    onPreviewSound: (String) -> Unit,
    onStopPreview: () -> Unit,
    onValidateSessionDuration: () -> Unit = {},
    onValidateShortBreakDuration: () -> Unit = {},
    onValidateLongBreakDuration: () -> Unit = {},
    onValidateLongBreakAfter: () -> Unit = {},
    modifier: Modifier = Modifier,
) {
    var dialogType by remember { mutableStateOf<SoundDialogType?>(null) }
    var wasFocused by remember { mutableStateOf(false) }
    val longBreakAfterFocusRequester = remember { FocusRequester() }
    val contentPadding = 16.dp
    val twoLinesSwitchPadding = remember {
        PaddingValues(
            start = 24.dp + contentPadding,
            end = 24.dp,
            top = 4.dp,
            bottom = 4.dp
        )
    }

    LazyColumn(
        contentPadding = PaddingValues(start = 0.dp, end = 0.dp, top = 0.dp, bottom = 16.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
        modifier = modifier,
    ) {
        item {
            SettingsColumnBlockWidget(headerRes = Res.string.timer_settings_durations) {
                DurationWithUnitRow(
                    displayValue = settings.sessionDuration / settings.sessionDurationUnit.factorToMs,
                    currentUnit = settings.sessionDurationUnit,
                    label = Res.string.timer_settings_session_duration,
                    onValueChange = { value ->
                        val newMs = value * settings.sessionDurationUnit.factorToMs
                        onSettingsChange(settings.copy(sessionDuration = newMs))
                    },
                    onUnitChange = { unit ->
                        onSettingsChange(settings.copy(sessionDurationUnit = unit))
                    },
                    errorMin = settings.sessionDurationErrorMin,
                    errorMax = settings.sessionDurationErrorMax,
                    onValidate = onValidateSessionDuration,
                    modifier = Modifier.fillMaxWidth().padding(start = contentPadding)
                )

                Spacer(Modifier.height(4.dp))

                DurationWithUnitRow(
                    displayValue = settings.shortBreakDuration / settings.shortBreakDurationUnit.factorToMs,
                    currentUnit = settings.shortBreakDurationUnit,
                    label = Res.string.timer_settings_short_break_duration,
                    onValueChange = { value ->
                        val newMs = value * settings.shortBreakDurationUnit.factorToMs
                        onSettingsChange(settings.copy(shortBreakDuration = newMs))
                    },
                    onUnitChange = { unit ->
                        onSettingsChange(settings.copy(shortBreakDurationUnit = unit))
                    },
                    errorMin = settings.shortBreakDurationErrorMin,
                    errorMax = settings.shortBreakDurationErrorMax,
                    onValidate = onValidateShortBreakDuration,
                    modifier = Modifier.fillMaxWidth().padding(start = contentPadding)
                )

                AnimatedVisibility(
                    visible = settings.isLongBreakEnabled,
                    enter = expandVertically(),
                    exit = shrinkVertically(),
                ) {
                    Column {
                        Spacer(Modifier.height(4.dp))

                        DurationWithUnitRow(
                            displayValue = settings.longBreakDuration / settings.longBreakDurationUnit.factorToMs,
                            currentUnit = settings.longBreakDurationUnit,
                            label = Res.string.timer_settings_long_break_duration,
                            onValueChange = { value ->
                                val newMs = value * settings.longBreakDurationUnit.factorToMs
                                onSettingsChange(settings.copy(longBreakDuration = newMs))
                            },
                            onUnitChange = { unit ->
                                onSettingsChange(settings.copy(longBreakDurationUnit = unit))
                            },
                            errorMin = settings.longBreakDurationErrorMin,
                            errorMax = settings.longBreakDurationErrorMax,
                            onValidate = onValidateLongBreakDuration,
                            modifier = Modifier.fillMaxWidth().padding(start = contentPadding)
                        )
                    }
                }
            }
        }

        item {
            SettingsColumnBlockWidget(
                headerRes = Res.string.timer_settings_behavior,
                contentPadding = PaddingValues(start = 0.dp, end = 0.dp, top = 16.dp, bottom = 0.dp),
                headerPadding = PaddingValues(horizontal = 24.dp)
            ) {
                TwoLinesSwitchButtonWidget(
                    titleRes = Res.string.timer_settings_auto_start_timer,
                    checked = settings.isTimerStartAuto,
                    onCheckedChange = { onSettingsChange(settings.copy(isTimerStartAuto = it)) },
                    modifier = Modifier.padding(twoLinesSwitchPadding),
                )

                TwoLinesSwitchButtonWidget(
                    titleRes = Res.string.timer_settings_auto_start_session,
                    checked = settings.isSessionStartAuto,
                    onCheckedChange = { onSettingsChange(settings.copy(isSessionStartAuto = it)) },
                    modifier = Modifier.padding(twoLinesSwitchPadding),
                )

                TwoLinesSwitchButtonWidget(
                    titleRes = Res.string.timer_settings_auto_start_break,
                    checked = settings.isBreakStartAuto,
                    onCheckedChange = { onSettingsChange(settings.copy(isBreakStartAuto = it)) },
                    modifier = Modifier.padding(twoLinesSwitchPadding),
                )

                TwoLinesSwitchButtonWidget(
                    titleRes = Res.string.timer_settings_enable_short_break,
                    checked = settings.isShortBreakEnabled,
                    onCheckedChange = { onSettingsChange(settings.copy(isShortBreakEnabled = it)) },
                    modifier = Modifier.padding(twoLinesSwitchPadding),
                )

                TwoLinesSwitchButtonWidget(
                    titleRes = Res.string.timer_settings_enable_long_break,
                    checked = settings.isLongBreakEnabled,
                    onCheckedChange = { onSettingsChange(settings.copy(isLongBreakEnabled = it)) },
                    modifier = Modifier.padding(twoLinesSwitchPadding),
                )

                AnimatedVisibility(
                    visible = settings.isLongBreakEnabled,
                    enter = expandVertically(),
                    exit = shrinkVertically(),
                ) {
                    Column {
                        Spacer(Modifier.height(8.dp))

                        var longBreakTextValue by remember {
                            mutableStateOf(
                                TextFieldValue(
                                    text = settings.longBreakAfterSession.toString(),
                                    selection = TextRange(settings.longBreakAfterSession.toString().length),
                                )
                            )
                        }

                        LaunchedEffect(settings.longBreakAfterSession) {
                            val external = settings.longBreakAfterSession.toString()
                            if (longBreakTextValue.text != external) {
                                longBreakTextValue = TextFieldValue(
                                    text = external,
                                    selection = TextRange(external.length),
                                )
                            }
                        }

                        Column {
                            OutlinedTextField(
                                value = longBreakTextValue,
                                onValueChange = { newValue ->
                                    val input = newValue.text
                                    val value = input.toIntOrNull() ?: 0
                                    onSettingsChange(settings.copy(longBreakAfterSession = value))
                                    val newText = value.toString()
                                    longBreakTextValue = TextFieldValue(
                                        text = newText,
                                        selection = TextRange(newText.length),
                                    )
                                },
                                label = { Text(stringResource(Res.string.timer_settings_long_break_after)) },
                                suffix = { Text(stringResource(Res.string.sessions)) },
                                isError = settings.longBreakAfterErrorMin != null,
                                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(start = 24.dp + contentPadding, end = 24.dp)
                                    .focusRequester(longBreakAfterFocusRequester)
                                    .onFocusChanged { focusState ->
                                        if (!focusState.isFocused && wasFocused) {
                                            onValidateLongBreakAfter()
                                        }
                                        wasFocused = focusState.isFocused
                                    },
                                singleLine = true,
                            )
                            if (settings.longBreakAfterErrorMin != null && settings.longBreakAfterErrorMax != null) {
                                Text(
                                    text = stringResource(Res.string.timer_settings_invalid_value, settings.longBreakAfterErrorMin!!, settings.longBreakAfterErrorMax!!),
                                    style = MaterialTheme.typography.bodySmall,
                                    color = MaterialTheme.colorScheme.error,
                                    modifier = Modifier.padding(start = 24.dp + contentPadding + 16.dp, top = 4.dp),
                                )
                            }
                        }
                    }
                }

            }
        }

        item {
            SettingsColumnBlockWidget(
                headerRes = Res.string.timer_settings_appearance,
                contentPadding = PaddingValues(start = 0.dp, end = 0.dp, top = 16.dp, bottom = 0.dp),
                headerPadding = PaddingValues(horizontal = 24.dp)
            ) {
                ProgressTypeDropdownRow(
                    currentType = settings.progressType,
                    onTypeChange = { onSettingsChange(settings.copy(progressType = it)) },
                    modifier = Modifier.fillMaxWidth().padding(start = 24.dp + contentPadding, end = 24.dp),
                )
            }
        }

        item {
            SettingsColumnBlockWidget(
                headerRes = Res.string.timer_settings_sounds,
                contentPadding = PaddingValues(start = 0.dp, end = 0.dp, top = 16.dp, bottom = 0.dp),
                headerPadding = PaddingValues(horizontal = 24.dp)
            ) {
                TwoLinesSwitchButtonWidget(
                    title = stringResource(Res.string.timer_settings_countdown_sound),
                    subtitle = soundDisplayName(settings.countdownSoundId),
                    checked = settings.isCountdownSoundEnabled,
                    onCheckedChange = { onSettingsChange(settings.copy(isCountdownSoundEnabled = it)) },
                    onClick = { dialogType = SoundDialogType.Countdown },
                    modifier = Modifier.padding(twoLinesSwitchPadding),
                )

                TwoLinesSwitchButtonWidget(
                    title = stringResource(Res.string.timer_settings_session_end_sound),
                    subtitle = soundDisplayName(settings.sessionEndSoundId),
                    checked = settings.isSessionEndSoundEnabled,
                    onCheckedChange = { onSettingsChange(settings.copy(isSessionEndSoundEnabled = it)) },
                    onClick = { dialogType = SoundDialogType.SessionEnd },
                    modifier = Modifier.padding(twoLinesSwitchPadding),
                )

                TwoLinesSwitchButtonWidget(
                    title = stringResource(Res.string.timer_settings_rest_end_sound),
                    subtitle = soundDisplayName(settings.restEndSoundId),
                    checked = settings.isRestEndSoundEnabled,
                    onCheckedChange = { onSettingsChange(settings.copy(isRestEndSoundEnabled = it)) },
                    onClick = { dialogType = SoundDialogType.RestEnd },
                    modifier = Modifier.padding(twoLinesSwitchPadding),
                )
            }
        }
    }

    dialogType?.let { type ->
        val title = when (type) {
            SoundDialogType.Countdown -> stringResource(Res.string.timer_settings_countdown_sound)
            SoundDialogType.SessionEnd -> stringResource(Res.string.timer_settings_session_end_sound)
            SoundDialogType.RestEnd -> stringResource(Res.string.timer_settings_rest_end_sound)
        }
        SoundPickerDialog(
            title = title,
            selectedSoundId = when (type) {
                SoundDialogType.Countdown -> settings.countdownSoundId
                SoundDialogType.SessionEnd -> settings.sessionEndSoundId
                SoundDialogType.RestEnd -> settings.restEndSoundId
            },
            isShortSound = when (type) {
                SoundDialogType.Countdown -> true
                SoundDialogType.SessionEnd, SoundDialogType.RestEnd -> false
            },
            onDismiss = { dialogType = null },
            onSoundSelected = { soundId ->
                when (type) {
                    SoundDialogType.Countdown -> onSettingsChange(settings.copy(countdownSoundId = soundId))
                    SoundDialogType.SessionEnd -> onSettingsChange(settings.copy(sessionEndSoundId = soundId))
                    SoundDialogType.RestEnd -> onSettingsChange(settings.copy(restEndSoundId = soundId))
                }
                dialogType = null
            },
            onPreviewSound = onPreviewSound,
            onStopPreview = onStopPreview,
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun DurationWithUnitRow(
    displayValue: Long,
    currentUnit: TimerTimeType,
    label: org.jetbrains.compose.resources.StringResource,
    onValueChange: (Long) -> Unit,
    onUnitChange: (TimerTimeType) -> Unit,
    errorMin: Int? = null,
    errorMax: Int? = null,
    onValidate: () -> Unit = {},
    modifier: Modifier = Modifier
) {
    var unitExpanded by remember { mutableStateOf(false) }
    var wasFocused by remember { mutableStateOf(false) }
    val focusRequester = remember { FocusRequester() }

    Row(
        modifier = modifier,
        horizontalArrangement = Arrangement.spacedBy(8.dp),
        verticalAlignment = Alignment.Top,
    ) {
        var durationTextValue by remember {
            mutableStateOf(
                TextFieldValue(
                    text = displayValue.toString(),
                    selection = TextRange(displayValue.toString().length),
                )
            )
        }

        LaunchedEffect(displayValue) {
            val external = displayValue.toString()
            if (durationTextValue.text != external) {
                durationTextValue = TextFieldValue(
                    text = external,
                    selection = TextRange(external.length),
                )
            }
        }

        Column(modifier = Modifier.weight(1f)) {
            OutlinedTextField(
                value = durationTextValue,
                onValueChange = { newValue ->
                    val input = newValue.text
                    val value = input.toLongOrNull() ?: 0L
                    onValueChange(value)
                    val newText = value.toString()
                    durationTextValue = TextFieldValue(
                        text = newText,
                        selection = TextRange(newText.length),
                    )
                },
                label = { Text(stringResource(label)) },
                isError = errorMin != null,
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                modifier = Modifier
                    .fillMaxWidth()
                    .focusRequester(focusRequester)
                    .onFocusChanged { focusState ->
                        if (!focusState.isFocused && wasFocused) {
                            onValidate()
                        }
                        wasFocused = focusState.isFocused
                    },
                singleLine = true,
            )
            if (errorMin != null && errorMax != null) {
                Text(
                    text = stringResource(Res.string.timer_settings_invalid_value, errorMin, errorMax),
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.error,
                    modifier = Modifier.padding(start = 16.dp, top = 4.dp),
                )
            }
        }

        ExposedDropdownMenuBox(
            expanded = unitExpanded,
            onExpandedChange = { unitExpanded = it },
            modifier = Modifier.weight(0.55f),
        ) {
            OutlinedTextField(
                value = currentUnit.displayName(),
                onValueChange = {},
                readOnly = true,
                label = { Text("") },
                trailingIcon = { ExposedDropdownMenuDefaults.TrailingIcon(expanded = unitExpanded) },
                modifier = Modifier.menuAnchor(),
                singleLine = true,
            )
            ExposedDropdownMenu(
                expanded = unitExpanded,
                onDismissRequest = { unitExpanded = false },
            ) {
                TimerTimeType.entries.forEach { type ->
                    DropdownMenuItem(
                        text = { Text(type.displayName()) },
                        onClick = {
                            onUnitChange(type)
                            unitExpanded = false
                        },
                        contentPadding = ExposedDropdownMenuDefaults.ItemContentPadding,
                    )
                }
            }
        }
    }
}

@Composable
private fun TimerTimeType.displayName(): String = when (this) {
    TimerTimeType.SECONDS -> stringResource(Res.string.seconds_short)
    TimerTimeType.MINUTES -> stringResource(Res.string.minutes_short)
    TimerTimeType.HOURS -> stringResource(Res.string.hours_short)
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun ProgressTypeDropdownRow(
    currentType: TimerProgressType,
    onTypeChange: (TimerProgressType) -> Unit,
    modifier: Modifier = Modifier,
) {
    var expanded by remember { mutableStateOf(false) }

    ExposedDropdownMenuBox(
        expanded = expanded,
        onExpandedChange = { expanded = it },
        modifier = modifier,
    ) {
        OutlinedTextField(
            value = currentType.displayName(),
            onValueChange = {},
            readOnly = true,
            label = { Text(stringResource(Res.string.timer_settings_progress_type)) },
            trailingIcon = { ExposedDropdownMenuDefaults.TrailingIcon(expanded = expanded) },
            modifier = Modifier.menuAnchor().fillMaxWidth(),
            singleLine = true,
        )
        ExposedDropdownMenu(
            expanded = expanded,
            onDismissRequest = { expanded = false },
            modifier = Modifier.exposedDropdownSize(),
        ) {
            TimerProgressType.entries.forEach { type ->
                DropdownMenuItem(
                    text = { Text(type.displayName()) },
                    onClick = {
                        onTypeChange(type)
                        expanded = false
                    },
                    contentPadding = ExposedDropdownMenuDefaults.ItemContentPadding,
                )
            }
        }
    }
}

@Composable
private fun TimerProgressType.displayName(): String = when (this) {
    TimerProgressType.Linear -> stringResource(Res.string.timer_progress_type_linear)
    TimerProgressType.Circular -> stringResource(Res.string.timer_progress_type_circular)
}
