package com.timemeasurer.app.navigation

import androidx.compose.animation.AnimatedContentTransitionScope
import androidx.compose.animation.ContentTransform
import androidx.compose.animation.core.tween
import androidx.compose.animation.slideInHorizontally
import androidx.compose.animation.slideOutHorizontally
import androidx.compose.material3.adaptive.ExperimentalMaterial3AdaptiveApi
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.navigation3.runtime.entryProvider
import androidx.navigation3.scene.Scene
import androidx.navigation3.ui.NavDisplay
import androidx.navigationevent.NavigationEvent
import com.timemeasurer.app.AppState
import com.timemeasurer.app.core.ui.navigation.BackPressHandler
import com.timemeasurer.app.feature.settings.navigation.settingsEntry
import com.timemeasurer.app.feature.splash.navigation.splashEntry
import com.timemeasurer.app.feature.stopwatches.navigation.stopwatchesEntry
import com.timemeasurer.app.feature.stopwatches_statistics.navigation.stopwatchesStatisticsEntry
import com.timemeasurer.app.feature.themes.navigation.themesEntry
import com.timemeasurer.app.feature.timer_settings.navigation.timerSettingsEntry
import com.timemeasurer.app.feature.timers.navigation.timersEntry
import com.timemeasurer.app.feature.timers_statistics.navigation.timersStatisticsEntry

private const val IOS_TRANSITION_DURATION = 300

private fun <T : Any> iosTransitionSpec(): AnimatedContentTransitionScope<Scene<T>>.() -> ContentTransform = {
    ContentTransform(
        slideInHorizontally(
            initialOffsetX = { it },
            animationSpec = tween(IOS_TRANSITION_DURATION),
        ),
        slideOutHorizontally(
            targetOffsetX = { -it },
            animationSpec = tween(IOS_TRANSITION_DURATION),
        ),
    )
}

private fun <T : Any> iosPopTransitionSpec(): AnimatedContentTransitionScope<Scene<T>>.() -> ContentTransform = {
    ContentTransform(
        slideInHorizontally(
            initialOffsetX = { -it },
            animationSpec = tween(IOS_TRANSITION_DURATION),
        ),
        slideOutHorizontally(
            targetOffsetX = { it },
            animationSpec = tween(IOS_TRANSITION_DURATION),
        ),
    )
}

private fun <T : Any> iosPredictivePopTransitionSpec(): AnimatedContentTransitionScope<Scene<T>>.(@NavigationEvent.SwipeEdge Int) -> ContentTransform = { edge ->
    val enterOffset: (Int) -> Int
    val exitOffset: (Int) -> Int
    if (edge == NavigationEvent.EDGE_LEFT) {
        enterOffset = { -it }
        exitOffset = { it }
    } else {
        enterOffset = { it }
        exitOffset = { -it }
    }
    ContentTransform(
        slideInHorizontally(
            initialOffsetX = enterOffset,
            animationSpec = tween(IOS_TRANSITION_DURATION),
        ),
        slideOutHorizontally(
            targetOffsetX = exitOffset,
            animationSpec = tween(IOS_TRANSITION_DURATION),
        ),
    )
}

@OptIn(ExperimentalMaterial3AdaptiveApi::class)
@Composable
fun AppNavHost(
    appState: AppState,
    modifier: Modifier = Modifier,
) {
    val backStack = appState.backStack
    val listDetailStrategy = rememberCustomListDetailSceneStrategy()

    val canGoBack = backStack.size > 1

    BackPressHandler(enabled = canGoBack) {
        appState.goBack()
    }

    if (useDefaultNavAnimations()) {
        NavDisplay(
            backStack = backStack,
            modifier = modifier,
            onBack = { appState.goBack() },
            sceneStrategies = listOf(listDetailStrategy),
            entryProvider = entryProvider {
                splashEntry(appState)
                timersEntry(appState)
                stopwatchesEntry(appState)
                timerSettingsEntry(appState)
                timersStatisticsEntry(appState)
                stopwatchesStatisticsEntry(appState)
                settingsEntry(appState)
                themesEntry(appState)
            }
        )
    } else {
        NavDisplay(
            backStack = backStack,
            modifier = modifier,
            onBack = { appState.goBack() },
            sceneStrategies = listOf(listDetailStrategy),
            transitionSpec = iosTransitionSpec(),
            popTransitionSpec = iosPopTransitionSpec(),
            predictivePopTransitionSpec = iosPredictivePopTransitionSpec(),
            entryProvider = entryProvider {
                splashEntry(appState)
                timersEntry(appState)
                stopwatchesEntry(appState)
                timerSettingsEntry(appState)
                timersStatisticsEntry(appState)
                stopwatchesStatisticsEntry(appState)
                settingsEntry(appState)
                themesEntry(appState)
            }
        )
    }
}
