package com.timemeasurer.app.feature.timer_settings

import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import com.timemeasurer.app.core.model.timer.TimerSettingsEvents
import com.timemeasurer.app.feature.timer_settings.models.TimerSettingsActions
import org.jetbrains.compose.resources.stringResource

@Composable
internal fun TimerSettingsActionsHandler(
    action: TimerSettingsActions,
    snackbarHost: androidx.compose.material3.SnackbarHostState?,
    onDismiss: () -> Unit,
    onEvent: (TimerSettingsEvents) -> Unit,
) {
    when (val currentAction = action) {
        is TimerSettingsActions.ShowError -> {
            val error = stringResource(currentAction.error)
            LaunchedEffect(key1 = currentAction) {
                snackbarHost?.showSnackbar(error)
                onEvent(TimerSettingsEvents.None)
            }
        }
        is TimerSettingsActions.Dismiss -> {
            LaunchedEffect(key1 = currentAction) {
                onDismiss()
                onEvent(TimerSettingsEvents.None)
            }
        }
        else -> {}
    }
}