package com.timemeasurer.app.feature.timers.widgets

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.unit.dp
import com.timemeasurer.app.core.model.timer.TimerTypeModel
import com.timemeasurer.app.core.resources.Res
import com.timemeasurer.app.core.resources.break_text
import com.timemeasurer.app.core.resources.long_break
import com.timemeasurer.app.core.resources.session
import org.jetbrains.compose.resources.stringResource

@Composable
fun TimerTypeTag(
    type: TimerTypeModel,
    modifier: Modifier = Modifier
) {
    val backgroundColor = when (type) {
        TimerTypeModel.Session -> MaterialTheme.colorScheme.errorContainer
        TimerTypeModel.Break -> MaterialTheme.colorScheme.secondaryContainer
        TimerTypeModel.LongBreak -> MaterialTheme.colorScheme.tertiaryContainer
    }
    val textColor = when (type) {
        TimerTypeModel.Session -> MaterialTheme.colorScheme.onErrorContainer
        TimerTypeModel.Break -> MaterialTheme.colorScheme.onSecondaryContainer
        TimerTypeModel.LongBreak -> MaterialTheme.colorScheme.onTertiaryContainer
    }
    val label = when (type) {
        TimerTypeModel.Session -> stringResource(Res.string.session)
        TimerTypeModel.Break -> stringResource(Res.string.break_text)
        TimerTypeModel.LongBreak -> stringResource(Res.string.long_break)
    }

    Box(
        modifier = modifier
            .clip(RoundedCornerShape(100.dp))
            .background(backgroundColor)
            .padding(horizontal = 16.dp, vertical = 6.dp)
    ) {
        Text(
            text = label,
            color = textColor,
            style = MaterialTheme.typography.labelMedium
        )
    }
}
