import androidx.compose.foundation.Canvas
import androidx.compose.foundation.layout.BoxWithConstraints
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.size
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.CompositingStrategy
import androidx.compose.ui.graphics.Shadow
import androidx.compose.ui.graphics.StrokeCap
import androidx.compose.ui.graphics.drawscope.Stroke
import androidx.compose.ui.graphics.drawscope.withTransform
import androidx.compose.ui.graphics.graphicsLayer
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.text.TextStyle
import androidx.compose.ui.text.drawText
import androidx.compose.ui.text.rememberTextMeasurer
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import com.timemeasurer.app.widget.circleprogress.models.CircleProgressModel
import com.timemeasurer.app.widget.circleprogress.models.CircleProgressSettingsModel
import com.timemeasurer.app.widget.circleprogress.models.Segment
import kotlin.math.PI
import kotlin.math.cos
import kotlin.math.sin

private const val SEGMENT_START_ANGLE = -90.0f

@Composable
fun TimerCircleProgressWidget(
    data: List<CircleProgressModel>,
    settings: CircleProgressSettingsModel = CircleProgressSettingsModel(),
    modifier: Modifier = Modifier
) {
    val localDensity = LocalDensity.current
    val textMeasurer = rememberTextMeasurer()

    BoxWithConstraints(modifier = modifier) {
        val thicknessPx = with(localDensity) { settings.ringThickness.toPx() }
        val gapPx = with(localDensity) { settings.gapThickness.toPx() }

        // Workaround because of blend mode
        val drawRoundedArcsActions = remember { mutableListOf<() -> Unit>() }

        Canvas(modifier = Modifier.fillMaxSize()
            .graphicsLayer {
                // This isolates the canvas blend calculations from the root background
                compositingStrategy = CompositingStrategy.Offscreen
            }) {
            val center = Offset(size.width / 2f, size.height / 2f)

            data.forEachIndexed { index, model ->
                val ringOffset = index * (thicknessPx + gapPx)
                val arcRadius = size.width / 2f - ringOffset - thicknessPx

                if (arcRadius <= 0f) return@forEachIndexed

                val topLeft = Offset(center.x - arcRadius, center.y - arcRadius)
                val ringSize = Size(arcRadius * 2f, arcRadius * 2f)

                drawArc(
                    color = model.backgroundColor,
                    startAngle = 0f,
                    sweepAngle = 360f,
                    useCenter = false,
                    topLeft = topLeft,
                    size = ringSize,
                    style = Stroke(width = thicknessPx, cap = StrokeCap.Butt),
                )

                drawRoundedArcsActions.clear()

                for (segment in model.segments) {
                    val segmentStart = SEGMENT_START_ANGLE + segment.start * 360f
                    val sweepAngle = (segment.end - segment.start) * 360f

                    if (sweepAngle > 0f) {
                        drawArc(
                            color = segment.color,
                            startAngle = segmentStart,
                            sweepAngle = sweepAngle,
                            useCenter = false,
                            topLeft = topLeft,
                            size = ringSize,
                            style = Stroke(width = thicknessPx, cap = StrokeCap.Round),
                        )

                        drawRoundedArcsActions.add {
                            val capRadius = thicknessPx / 2f
                            val endAngle = segmentStart + sweepAngle
                            val endRad = endAngle * PI.toFloat() / 180f
                            val endX = center.x + arcRadius * cos(endRad)
                            val endY = center.y + arcRadius * sin(endRad)
                            drawCircle(
                                color = segment.color,
                                radius = capRadius,
                                center = Offset(endX, endY),
                            )
                        }
                    }
                }

                for (item in drawRoundedArcsActions) item()

                val arcText = model.arcText
                if (!arcText.isNullOrEmpty()) {
                    val fontSizeSp = thicknessPx * 0.5f / this.density / this.fontScale
                    val textColor = model.arcTextColor.takeIf { it != Color.Unspecified } ?: Color.Black
                    val textStyle = TextStyle(
                        fontSize = fontSizeSp.sp,
                        color = textColor,
                        shadow = Shadow(color = Color.Black, blurRadius = 2f, offset = Offset(1f, 1f))
                    )

                    val charWidths = arcText.map { char ->
                        textMeasurer.measure(char.toString(), textStyle).size.width.toFloat()
                    }

                    val sampleLayout = textMeasurer.measure("M", textStyle)
                    val textHeight = sampleLayout.size.height.toFloat()
                    val outerRadius = arcRadius + thicknessPx / 2f - fontSizeSp
                    val textArcRadius = outerRadius - textHeight / 2f
                    val totalTextWidth = charWidths.sum()
                    val totalAngularWidthRad = totalTextWidth / textArcRadius
                    val totalAngularWidthDeg = totalAngularWidthRad * (180f / PI.toFloat())
                    val textStartAngle = SEGMENT_START_ANGLE - totalAngularWidthDeg / 2f

                    var cumulativeWidth = 0f
                    arcText.forEachIndexed { charIndex, char ->
                        val charWidth = charWidths[charIndex]
                        val charCenterWidth = cumulativeWidth + charWidth / 2f
                        val charAngularOffsetRad = charCenterWidth / textArcRadius
                        val charAngleDeg = textStartAngle + charAngularOffsetRad * (180f / PI.toFloat())
                        val charX = center.x + textArcRadius * cos(charAngleDeg * PI.toFloat() / 180f)
                        val charY = center.y + textArcRadius * sin(charAngleDeg * PI.toFloat() / 180f)
                        val textLayoutResult = textMeasurer.measure(char.toString(), textStyle)

                        withTransform({
                            rotate(charAngleDeg + 90f, pivot = Offset(charX, charY))
                        }) {
                            drawText(
                                textLayoutResult = textLayoutResult,
                                topLeft = Offset(
                                    charX - charWidth / 2f,
                                    charY - textLayoutResult.size.height / 2f
                                ),
                                alpha = model.textAlpha
                            )
                        }

                        cumulativeWidth += charWidth
                    }
                }
            }
        }

    }
}

