package com.timemeasurer.app.core.data.model

import com.timemeasurer.app.core.model.stopwatch.StopwatchSettingsModel
import kotlinx.serialization.json.Json

fun StopwatchSettingsModel.toEncodeString(): String = Json.encodeToString(StopwatchSettingsModel.serializer(), this)

fun String.toStopwatchSettingsModel(): StopwatchSettingsModel = Json.decodeFromString(StopwatchSettingsModel.serializer(), this)
