@Composable
fun TimersScreen(
    onTimerSettingsClick: (Long) -> Unit,
    onStatisticsClick: () -> Unit = {},
    onTimerSelected: () -> Unit = {},
    isExpanded: Boolean = false,
    viewModel: TimersViewModel = viewModel { TimersViewModel() },
    topBarNavigationViewModel: TopBarNavigationViewModel = viewModel { TopBarNavigationViewModel() },
) {
    println("TimersScreen()")

    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    val tickState by viewModel.tickState.collectAsStateWithLifecycle()
    val action by viewModel.action.collectAsStateWithLifecycle()

    println("TimersScreen() - state: $uiState, $action")

    val defaultTimerName = stringResource(Res.string.timer)
    LaunchedEffect(defaultTimerName) {
        if (defaultTimerName.isNotEmpty()) {
            viewModel.setEvent(TimerEvents.TimerDefaultName(defaultTimerName))
        }
    }

    LaunchedEffect(Unit) {
        topBarNavigationViewModel.collect("timers").collect { event ->
            when (event) {
                TopBarNavigationState.Statistics -> {
                    onStatisticsClick()
                    topBarNavigationViewModel.emit("timers", TopBarNavigationState.None)
                }
                else -> {}
            }
        }
    }

    when (val state = uiState) {
        UiState.Empty -> SimplePlaceholderContent(
            header = stringResource(Res.string.empty),
            title = stringResource(Res.string.no_data_to_display),
            image = MainIconSet.search.icon,
            imageContentDescription = stringResource(Res.string.no_data_to_display)
        )

        is UiState.Success -> {
            if (state.item.timers.isEmpty()) {
                Box(modifier = Modifier.fillMaxSize()) {
                    SimplePlaceholderContent(
                        header = stringResource(Res.string.empty),
                        title = stringResource(Res.string.no_data_to_display),
                        image = MainIconSet.search.icon,
                        imageContentDescription = stringResource(Res.string.no_data_to_display)
                    )
                    if (state.item.isSpeedDialExpanded) {
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .clickable(
                                    interactionSource = remember { MutableInteractionSource() },
                                    indication = null
                                ) {
                                    viewModel.setEvent(TimerEvents.ToggleSpeedDial)
                                }
                        )
                    }
                    TimerSpeedDial(
                        isExpanded = state.item.isSpeedDialExpanded,
                        showDelete = state.item.isDeleteVisible,
                        onToggle = { viewModel.setEvent(TimerEvents.ToggleSpeedDial) },
                        onCreate = { viewModel.setEvent(TimerEvents.ShowCreateDialog) },
                        onRename = {},
                        onDelete = {},
                        onSettings = {},
                        modifier = Modifier
                            .align(if (isExpanded) Alignment.BottomStart else Alignment.BottomEnd)
                            .padding(
                                start = if (isExpanded) 16.dp else 0.dp,
                                end = if (isExpanded) 0.dp else 16.dp,
                                bottom = 16.dp
                            )
                    )
                }
            } else {
                val timers = state.item.timers
                val pagerState = rememberPagerState(pageCount = { timers.size })
                val lastIndex = timers.lastIndex
                val selectedTabIndex = pagerState.currentPage.coerceIn(0, lastIndex)

                LaunchedEffect(timers.size) {
                    if (pagerState.currentPage > lastIndex) {
                        pagerState.scrollToPage(lastIndex)
                    }
                }

                LaunchedEffect(timers, pagerState) {
                    viewModel.setEvent(TimerEvents.OnPageSelected(pagerState.currentPage))
                    snapshotFlow { pagerState.currentPage }.collect { page ->
                        viewModel.setEvent(TimerEvents.OnPageSelected(page))
                        if (isExpanded) {
                            onTimerSelected()
                        }
                    }
                }

                val coroutineScope = rememberCoroutineScope()

                val tabItems = timers.map { timer ->
                    AnimatedTabItem(
                        title = timer.name.takeIf { it.isNotEmpty() }
                            ?: stringResource(Res.string.default),
                        icon = AppIconRegistry.findById(timer.iconId)?.icon,
                    )
                }

                Box(modifier = Modifier.fillMaxSize()) {
                    Column(modifier = Modifier.fillMaxSize()) {
                        AnimatedTabRowWidget(
                            items = tabItems,
                            selectedPage = pagerState.currentPage,
                            pageOffset = pagerState.currentPageOffsetFraction,
                            onTabClick = { index ->
                                coroutineScope.launch {
                                    pagerState.animateScrollToPage(index)
                                }
                            },
                            modifier = Modifier.fillMaxWidth(),
                        )

                        HorizontalPager(
                            state = pagerState,
                            pageSize = PageSize.Fill,
                            pageSpacing = 16.dp,
                            contentPadding = PaddingValues(start = 16.dp, end = 16.dp, top = 16.dp, bottom = 4.dp),
                            beyondViewportPageCount = 1,
                            modifier = Modifier.fillMaxSize()
                        ) { page ->
                            val dataModel = timers[page]
                            val timerTickState = tickState[dataModel.timerId] ?: return@HorizontalPager
                            TimerItemContent(
                                dataModel = dataModel,
                                tickState = timerTickState,
                                onEventAction = viewModel::setEvent,
                                modifier = Modifier.fillMaxSize()
                            )
                        }
                    }

                    if (state.item.isSpeedDialExpanded) {
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .clickable(
                                    interactionSource = remember { MutableInteractionSource() },
                                    indication = null
                                ) {
                                    viewModel.setEvent(TimerEvents.ToggleSpeedDial)
                                }
                        )
                    }

                    TimerSpeedDial(
                        isExpanded = state.item.isSpeedDialExpanded,
                        showDelete = state.item.isDeleteVisible,
                        onToggle = { viewModel.setEvent(TimerEvents.ToggleSpeedDial) },
                        onCreate = { viewModel.setEvent(TimerEvents.ShowCreateDialog) },
                        onRename = { viewModel.setEvent(TimerEvents.ShowRenameDialog(selectedTabIndex)) },
                        onDelete = { viewModel.setEvent(TimerEvents.ShowDeleteDialog(selectedTabIndex)) },
                        onSettings = { viewModel.setEvent(TimerEvents.ShowSettings(selectedTabIndex)) },
                        modifier = Modifier
                            .align(if (isExpanded) Alignment.BottomStart else Alignment.BottomEnd)
                            .padding(
                                start = if (isExpanded) 16.dp else 0.dp,
                                end = if (isExpanded) 0.dp else 16.dp,
                                bottom = 16.dp
                            )
                    )

                    if (state.item.isLoading) {
                        Box(
                            modifier = Modifier
                                .fillMaxSize()
                                .clickable(
                                    interactionSource = remember { MutableInteractionSource() },
                                    indication = null,
                                    onClick = {}
                                )
                        )
                    }
                }
            }
        }

        else -> {}
    }

    when (val action = action) {
        TimerActions.None -> {}

        is TimerActions.ShowError -> {
            println("User action: $action")
            val error = stringResource(action.error)
            val snackbarHost = LocalSnackbarHost.current
            LaunchedEffect(key1 = action) {
                snackbarHost?.showSnackbar(error)
                viewModel.setEvent(TimerEvents.None)
            }
        }

        is TimerActions.ShowCreateTimerDialog -> {
            if (action.isDialogVisible) {
                IconPickerInputDialog(
                    title = stringResource(Res.string.input_timer_name),
                    initialText = stringResource(Res.string.timer_default_name_format, action.timerId.toInt()),
                    initialIconId = action.iconId,
                    confirmText = stringResource(Res.string.create),
                    onConfirm = { name, iconId -> viewModel.setEvent(TimerEvents.Create(name, iconId)) },
                    onDismiss = { viewModel.setEvent(TimerEvents.None) },
                    nameError = action.nameError,
                    onValidateName = { name -> viewModel.setEvent(TimerEvents.ValidateCreateName(name)) },
                    maxNameLength = action.maxNameLength,
                )
            }
        }

        is TimerActions.ShowRenameTimerDialog -> {
            if (action.isDialogVisible) {
                IconPickerInputDialog(
                    title = stringResource(Res.string.input_timer_rename),
                    initialText = action.currentName,
                    initialIconId = action.iconId,
                    confirmText = stringResource(Res.string.save),
                    onConfirm = { name, iconId -> viewModel.setEvent(TimerEvents.Rename(action.timerId, name, iconId)) },
                    onDismiss = { viewModel.setEvent(TimerEvents.None) },
                    nameError = action.nameError,
                    onValidateName = { name -> viewModel.setEvent(TimerEvents.ValidateRenameName(name)) },
                    maxNameLength = action.maxNameLength,
                )
            }
        }

        is TimerActions.ShowDeleteTimerDialog -> {
            if (action.isDialogVisible) {
                SimpleDialog(
                    dialogTitle = stringResource(Res.string.delete_timer),
                    dialogText = stringResource(Res.string.confirm_delete_timer),
                    confirmText = stringResource(Res.string.delete),
                    onConfirmation = { viewModel.setEvent(TimerEvents.Delete(action.timerId)) },
                    onCancel = { viewModel.setEvent(TimerEvents.None) },
                    dismissText = stringResource(Res.string.close),
                )
            }
        }

        is TimerActions.ShowResetTimerDialog -> {
            if (action.isDialogVisible) {
                SimpleDialog(
                    dialogTitle = stringResource(Res.string.reset_timer),
                    dialogText = stringResource(Res.string.confirm_reset_timer),
                    confirmText = stringResource(Res.string.reset),
                    onConfirmation = { viewModel.setEvent(TimerEvents.Reset(action.timerId)) },
                    onCancel = { viewModel.setEvent(TimerEvents.None) },
                    dismissText = stringResource(Res.string.cancel),
                )
            }
        }

        is TimerActions.OpenTimerSettings -> {
            LaunchedEffect(key1 = action) {
                onTimerSettingsClick(action.timerId)
                viewModel.setEvent(TimerEvents.None)
            }
        }

        is TimerActions.OpenStatistics -> {
            LaunchedEffect(key1 = action) {
                onStatisticsClick()
                viewModel.setEvent(TimerEvents.None)
            }
        }
    }
}
