package com.timemeasurer.app.core.data.database

import app.cash.sqldelight.db.SqlDriver
import com.timemeasurer.app.core.data.Database
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock


interface AppDatabase {
    suspend fun db(): Database
    suspend fun driver(): SqlDriver
}

class AppDatabaseImpl(
    private val dbDriverFactory: DbDriverFactory
): AppDatabase {

    private val mutex = Mutex()
    private lateinit var appDatabase: Database
    private lateinit var sqlDrive: SqlDriver

    private suspend fun ensureInitialized() {
        mutex.withLock {
            if (!::appDatabase.isInitialized) {
                val driver = dbDriverFactory.provideDbDriver(Database.Schema)
                Database(driver).also {
                    sqlDrive = driver
                    appDatabase = it
                }
            }
        }
    }

    override suspend fun db(): Database {
        ensureInitialized()
        return appDatabase
    }

    override suspend fun driver(): SqlDriver {
        ensureInitialized()
        return sqlDrive
    }

}
